window.PACK={"book":{"id":"mutash-kirmani","title":"البرهان في توجيه متشابه القرآن (أسرار التكرار)","type":"mutash","author":"تاج القراء الكرماني (ت 505هـ)","linkedTo":"quran","source":"المكتبة الشاملة عبر مشروع OpenITI","packVersion":"9524f1d6007a"},"items":[{"id":"mutash-kirmani:1","bookId":"mutash-kirmani","type":"section","surah":1,"num":1,"title":"سورة الفاتحة","page":"ج1 ص64","text":"أول المتشابهات قوله {الرحمن الرحيم مالك} فيمن جعل {بسم الله الرحمن الرحيم} آية من الفاتحة وفي تكراره قولان قال علي بن عيسى إنما كرر للتوكيد وأنشد قول الشاعر ... هلا سألت جموع كندة يوم ولوا أين أينا ... وقال قاسم بن حبيب إنما كرر لأن المعنى وجب الحمد لله لأنه الرحمن الرحيم قلت إنما كرر لأن الرحمة هي الإنعام على المحتاج وذكر في الآية الأولى المنعم ولم يذكر المنعم عليهم فأعادها مع ذكرهم وقال {رب العالمين الرحمن} لهم جميعا ينعم عليهم ويرزقهم {الرحيم} بالمؤمنين خاصة يوم الدين ينعم عليهم ويغفر لهم"},{"id":"mutash-kirmani:2","bookId":"mutash-kirmani","type":"section","surah":1,"num":2,"title":"سورة الفاتحة","page":"ج1 ص65","text":"قوله تعالى {إياك نعبد وإياك نستعين} كرر {إياك} وقدمه ولم يقتصر على ذكره مرة كما اقتصر على ذكر أحد المفعولين في آيات كثيرة منها {ما ودعك ربك وما قلى} أي ما قلاك وكذلك الآيات التي بعدها معناها فآواك فهداك فأغناك لأن في التقديم فائدة وهي قطع الاشتراك ولو حذف لم يدل على التقديم لأنك لو قلت إياك نعبد ونستعين لم يظهر أن التقدير إياك نعبد وإياك نستعين أم إياك نعبد ونستعينك فكرر"},{"id":"mutash-kirmani:3","bookId":"mutash-kirmani","type":"section","surah":1,"num":3,"title":"سورة الفاتحة","page":"ج1 ص65","text":"قوله تعالى {صراط الذين أنعمت عليهم} كرر {الصراط} لعلة تقرب مما ذكرت في {الرحمن الرحيم} وذلك أن الصراط هو المكان المهيأ للسلوك فذكر في الأول المكان ولم يذكر السالكين فأعاده مع ذكرهم فقال {صراط الذين أنعمت عليهم} أي الذي يسلكه النبيون والمؤمنون ولهذا كرر أيضا في قوله {إلى صراط مستقيم} {صراط الله} لأنه ذكر المكان المهيأ ولم يذكر المهيئ فأعاده مع ذكره فقال {صراط الله} أي الذي هيأه للسالكين"},{"id":"mutash-kirmani:4","bookId":"mutash-kirmani","type":"section","surah":1,"num":4,"title":"سورة الفاتحة","page":"ج1 ص65","text":"قوله {عليهم} ليس بتكرار لأن كل واحد منهما متصل بفعل غير الآخر وهو الإنعام والغضب وكل واحد منهما يقتضيه اللفظ وما كان هذا سبيله فليس بتكرار ولا من المتشابه"},{"id":"mutash-kirmani:5","bookId":"mutash-kirmani","type":"section","surah":2,"num":5,"title":"سورة البقرة","page":"ج1 ص66","text":"قوله تعالى {الم} هذه الآية تتكرر في أوائل ست سور فهي من المتشابه لفظا وذهب جماعة من المفسرين إلى أن قوله {وأخر متشابهات} هي هذه الحروف الواقعة في أوائل السور فهي أيضا من المتشابه لفظا ومعنى والموجب لذكره أول البقرة من القسم وغيره هو بعينه الموجب لذكره في أوائل سائر السور المبدوءة به وزاد في الأعراف صادا لما جاء بعده {فلا يكن في صدرك حرج منه} ولهذا قال بعض المفسرين معنى {المص} ألم نشرح لك صدرك وقيل معناه المصور وزاد في الرعد راء لقوله بعده {الله الذي رفع السماوات}"},{"id":"mutash-kirmani:6","bookId":"mutash-kirmani","type":"section","surah":2,"num":6,"title":"سورة البقرة","page":"ج1 ص66","text":"قوله {سواء عليهم} وفي يس {وسواء} بزيادة واو لأن ما في البقرة جملة هي خبر عن اسم إن وما في يس جملة عطفت بالواو على جملة"},{"id":"mutash-kirmani:7","bookId":"mutash-kirmani","type":"section","surah":2,"num":7,"title":"سورة البقرة","page":"ج1 ص66","text":"قوله {آمنا بالله وباليوم الآخر} ليس في القرآن غيره تكرار العامل مع حرف العطف لا يكون إلا للتأكيد وهذه حكاية كلام المنافقين وهم أكدوا كلامهم نفيا للريبة وإبعادا للتهمة فكانوا في ذلك كما قيل يكاد المريب يقول خذوني فنفى الله الإيمان عنهم بأوكد الألفاظ فقال {وما هم بمؤمنين} ويكثر ذلك مع النفي وقد جاء في القرآن في موضعين في النساء {ولا يؤمنون بالله ولا باليوم الآخر} وفي التوبة {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر}"},{"id":"mutash-kirmani:8","bookId":"mutash-kirmani","type":"section","surah":2,"num":8,"title":"سورة البقرة","page":"ج1 ص68","text":"قوله {يا أيها الناس اعبدوا ربكم} ليس في القرآن غيره ليس لأن العبادة في الآية التوحيد والتوحيد أول ما يلزم العبد من المعارف فكان هذا أول خطاب خاطب الله به الناس في القرآن فخاطبهم بما ألزمهم أولا ثم ذكر سائر المعارف وبنى عليها العبادات فيما بعدها من السور والآيات فإن قيل سورة البقرة ليست من أول القرآن نزولا فلا يحسن فيها ما ذكرت قلت أول القرآن سورة الفاتحة ثم البقرة ثم آل عمران على هذا الترتيب إلى سورة الناس وهكذا هو عند الله في اللوح المحفوظ وهو على هذا الترتيب كان يعرضه عليه الصلاة والسلام على جبريل عليه السلام كل سنة أي ما كان يجتمع عنده منه وعرضه عليه الصلاة والسلام في السنة التي توفى فيها مرتين وكان آخر الآيات نزولا {واتقوا يوما ترجعون فيه إلى الله} فأمره جبريل أن يضعها بين آيتي الربا والدين وذهب جماعة من المفسرين إلى أن قوله في هود {فأتوا بعشر سور مثله} معناه مثل البقرة إلى هود وهي العاشرة ومعلوم أن سورة هود مكية وأن البقرة وآل عمران والنساء والمائدة والأنفال والتوبة مدنيات نزلن بعدها وفسر بعضهم قوله {ورتل القرآن ترتيلا} : 4 أي اقرأه على هذا الترتيب من غير تقديم وتأخير وجاء النكير على من قرأه معكوسا ولو حلف إنسان أن يقرأ القرآن على الترتيب لم يلزمه إلا على هذا الترتيب ولو نزل جملة كما اقترحوا عليه بقولهم {لولا نزل عليه القرآن جملة واحدة} : 32 لنزل على هذا الترتيب وإنما تفرقت سوره وآياته نزولا لحاجة الناس حالة بعد حالة ولأن فيه الناسخ والمنسوخ ولم يكونا ليجتمعا نزولا وأبلغ الحكم في تفرقه ما قاله سبحانه {وقرآنا فرقناه لتقرأه على الناس على مكث} وهذا أصل تنبني عليه مسائل والله أعلم"},{"id":"mutash-kirmani:9","bookId":"mutash-kirmani","type":"section","surah":2,"num":9,"title":"سورة البقرة","page":"ج1 ص69","text":"قوله تعالى {فأتوا بسورة من مثله} بزيادة {من} في هذه السورة وفي غيرها {بسورة مثله} لأن {من} تدل على التبعيض ولما كانت هذه السورة سنام القرآن وأوله بعد الفاتحة حسن دخول {من} فيها ليعلم أن التحدي واقع على جميع سور القرآن من أوله إلى آخره وغيرها من السور لو دخلها من لكان التحدي واقعا على بعض السور دون بعض ولم يكن ذلك بالسهل والهاء في قوله {من مثله} تعود إلى {ما} وهو القرآن وذهب بعضهم إلى أنه يعود على محمد عليه السلام أي فأتوا بسورة من إنسان مثله وقيل يعود إلى الأنداد وهو ضعيف لأن الأنداد جماعة والهاء للفرد وقيل مثله التوراة والهاء تعود إلى القرآن والمعنى فأتو بسورة من التوراة التي هي مثل القرآن ليعلموا وفاقهما {وهو} خطاب لليهود"},{"id":"mutash-kirmani:10","bookId":"mutash-kirmani","type":"section","surah":2,"num":10,"title":"سورة البقرة","page":"ج1 ص69","text":"قوله {فسجدوا إلا إبليس أبى واستكبر} ذكر هذه الخلال في هذه السورة جملة ثم ذكرها في سائر السور مفصلا فقال في الأعراف {إلا إبليس لم يكن من الساجدين} وفي الحجر {إلا إبليس أبى أن يكون مع الساجدين} وفي سبحان {إلا إبليس قال أأسجد لمن خلقت طينا} وفي الكهف {إلا إبليس كان من الجن} وفي طه {إلا إبليس أبى} وفي ص {إلا إبليس استكبر وكان من الكافرين}"},{"id":"mutash-kirmani:11","bookId":"mutash-kirmani","type":"section","surah":2,"num":11,"title":"سورة البقرة","page":"ج1 ص70","text":"قوله {اسكن أنت وزوجك الجنة وكلا} بالواو وفي الأعراف {فكلا} بالفاء {اسكن} في الآيتين ليس بأمر بالسكون الذي هو ضد الحركة وإنما الذي في البقرة من السكون الذي معناه الإقامة وذلك يستدعي زمانا ممتدا فلم يصلح إلا بالواو لأن المعنى اجمع بين الإقامة فيها والأكل من ثمارها ولو كان الفاء مكان الواو لوجب تأخير الأكل إلى الفراغ من الإقامة لأن الفاء للتعقيب والترتيب والذي في الأعراف من السكنى الذي معناها اتخاذ الموضع مسكنا لأن الله تعالى أخرج إبليس من الجنة بقوله { اخرج منها مذؤوما} وخاطب آدم فقال {يا آدم اسكن أنت وزوجك الجنة} أي اتخذاها لأنفسكما مسكنا {فكلا من حيث شئتما} فكانت الفاء أولى لأن اتخاذ المسكن لا يستدعي زمانا ممتدا ولا يمكن الجمع بين الاتخاذ والأكل فيه بل يقع الأكل عقيبه وزاد في البقرة {رغدا} لما زاد في الخبر تعظيما بقوله {وقلنا} بخلاف سورة الأعراف فإن فيها (قال) والخطيب ذهب إلى أن ما في الأعراف"},{"id":"mutash-kirmani:12","bookId":"mutash-kirmani","type":"section","surah":2,"num":12,"title":"سورة البقرة","page":"ج1 ص70","text":"قوله {اهبطوا منها} كرر الأمر بالهبوط لأن الأول من الجنة والثاني من السماء"},{"id":"mutash-kirmani:13","bookId":"mutash-kirmani","type":"section","surah":2,"num":13,"title":"سورة البقرة","page":"ج1 ص70","text":"قوله {فمن تبع} وفي طه {فمن اتبع} تبع واتبع بمعنى وإنما اختار في طه {اتبع} موافقة لقوله تعالى {يتبعون الداعي}"},{"id":"mutash-kirmani:14","bookId":"mutash-kirmani","type":"section","surah":2,"num":14,"title":"سورة البقرة","page":"ج1 ص71","text":"قوله {ولا يقبل منها شفاعة ولا يؤخذ منها عدل} قدم الشفاعة في هذه الآية وأخر العدل وقدم العدل في الآية الأخرى من هذه السورة وأخر الشفاعة وإنما قدم الشفاعة قطعا لطمع من زعم أن آباءهم تشفع لهم وأن الأصنام شفعاؤهم عند الله وأخرها في الآية الأخرى لأن التقدير في الآيتين معا لا يقبل منها شفاعة فتنفعها تلك الشفاعة لأن النفع بعد القبول وقدم العدل في الآية الأخرى ليكون لفظ القبول مقدما فيها"},{"id":"mutash-kirmani:15","bookId":"mutash-kirmani","type":"section","surah":2,"num":15,"title":"سورة البقرة","page":"ج1 ص71","text":"قوله {يذبحون} بغير واو هنا على البدل من {يسومونكم} وفي الأعراف {يقتلون} وفي إبراهيم {ويذبحون} بالواو لأن ما في هذه السورة والأعراف من كلام الله تعالى فلم يرد تعداد المحن عليهم والذي في إبراهيم من كلام موسى فعدد المحن عليهم وكان مأمورا بذلك في قوله {وذكرهم بأيام الله}"},{"id":"mutash-kirmani:16","bookId":"mutash-kirmani","type":"section","surah":2,"num":16,"title":"سورة البقرة","page":"ج1 ص71","text":"قوله {ولكن كانوا أنفسهم يظلمون} ههنا وفي الأعراف 160 وقال في آل عمران {ولكن أنفسهم يظلمون} لأن ما في السورتين إخبار عن قوم ماتوا وانقرضوا وما في آل عمران مثل"},{"id":"mutash-kirmani:17","bookId":"mutash-kirmani","type":"section","surah":2,"num":17,"title":"سورة البقرة","page":"ج1 ص73","text":"قوله {وإذ قلنا ادخلوا هذه القرية فكلوا} بالفاء وفي الأعراف 161 بالواو لأن الدخول سريع الانقضاء فيتبعه الأكل وفي الأعراف {وإذ قيل لهم اسكنوا} المعنى أقيموا فيها وذلك ممتد فذكر بالواو أي اجمعوا بين الأكل والسكون وزاد في البقرة {رغدا} لأنه سبحانه أسنده إلى ذاته بلفظ التعظيم وهو قوله {وإذ قلنا} خلاف ما في الأعراف فإن فيه {وإذ قيل} وقدم {وادخلوا الباب سجدا} على قوله {وقولوا حطة} في هذه السورة وأخرها في الأعراف لأن السابق في هذه السورة {ادخلوا} فبين كيفية الدخول وفي هذه السورة {خطاياكم} بالإجماع وفي الأعراف {خطيئاتكم} مختلف لأن خطايا صيغة الجمع الكثير ومغفرتها أليق في الآية بإسناد الفعل إلى نفسه سبحانه وفي هذه السورة {وسنزيد} وفي الأعراف {سنزيد} بغير واو لأن اتصالها في هذه السورة أشد لاتفاق اللفظين واختلفا في الإعراب لأن اللائق {سنزيد} محذوف الواو ليكون استئنافا لكلام وفي هذه السورة {فبدل الذين ظلموا قولا} وفي الأعراف 62 {ظلموا منهم} لأن في الأعراف {ومن قوم موسى} ولقوله {منهم الصالحون ومنهم دون ذلك} وفي هذه السورة {فأنزلنا على الذين ظلموا} وفي الأعراف {فأرسلنا} لأن لفظ الرسول والرسالة كثرت في الأعراف فجاء ذلك وفقا لما قبله وليس كذلك في سورة البقرة"},{"id":"mutash-kirmani:18","bookId":"mutash-kirmani","type":"section","surah":2,"num":18,"title":"سورة البقرة","page":"ج1 ص73","text":"قوله {فانفجرت} وفي الأعراف {فانبجست} لأن الانفجار انصباب الماء بكثرة والانبجاس ظهور الماء وكان في هذه السورة {كلوا واشربوا} فذكر بلفظ بليغ وفي الأعراف {كلوا من طيبات ما رزقناكم} وليس فيه واشربوا فلم يبالغ فيه"},{"id":"mutash-kirmani:19","bookId":"mutash-kirmani","type":"section","surah":2,"num":19,"title":"سورة البقرة","page":"ج1 ص74","text":"قوله {ويقتلون النبيين بغير الحق} في هذه السورة وفي آل عمران {ويقتلون النبيين بغير حق} وفيها وفي النساء {وقتلهم الأنبياء بغير حق} لأن ما في البقرة إشارة إلى الحق الذي أذن الله أن تقتل النفس به وهو قوله {ولا تقتلوا النفس التي حرم الله إلا بالحق} فكان الأولى أن يذكر معرفا لأنه من الله تعالى وما في آل عمران والنساء نكرة أي بغير حق في معتقدهم ودينهم فكان هذا بالتنكير أولى وجمع النبيين جمع السلامة في البقرة لموافقة ما بعده من جمعى السلامة وهو {النبيين} {الصابئين} وكذلك في آل عمران {إن الذين} وناصرين ومعرضون بخلاف الأنبياء في السورتين"},{"id":"mutash-kirmani:20","bookId":"mutash-kirmani","type":"section","surah":2,"num":20,"title":"سورة البقرة","page":"ج1 ص75","text":"قوله {إن الذين آمنوا والذين هادوا والنصارى والصابئين} وقال في الحج {والصابئين والنصارى} وقال في المائدة {والصابئون والنصارى} لأن النصارى مقدمون على الصابئين في الرتبة لأنهم أهل كتاب فقدمهم في البقرة والصابئون مقدمون على النصارى في الزمان لأنهم كانوا قبلهم فقدمهم في الحج وداعى في المائدة بين المعنين وقدمهم في اللفظ وأخرهم في التقدير لأن تقديره والصابئون في كذلك قال الشاعر فإن يك أمسى بالمدينة رحله ... فإني وقيار بها لغريب أراد إني لغريب وقيار كذلك فتأمل فيها وفي أمثالها يظهر لك إعجاز القرآن"},{"id":"mutash-kirmani:21","bookId":"mutash-kirmani","type":"section","surah":2,"num":21,"title":"سورة البقرة","page":"ج1 ص75","text":"قوله {أياما معدودة} وفي آل عمران {أياما معدودات} لأن الأصل في الجمع إذا كان واحده مذكرا أن يقتصر في الوصف على التأنيث نحو قوله {سرر مرفوعة وأكواب موضوعة ونمارق مصفوفة وزرابي مبثوثة} : 13 16 وقد يأتي سرر مرفوعات على تقدير ثلاث سرر مرفوعة وتسع سرر مرفوعات إلا أنه ليس بالأصل فجاء في البقرة على الأصل وفي آل عمران على الفرع وقوله {في أيام معدودات} أي في ساعات أيام معدودات وكذلك {في أيام معلومات}"},{"id":"mutash-kirmani:22","bookId":"mutash-kirmani","type":"section","surah":2,"num":22,"title":"سورة البقرة","page":"ج1 ص75","text":"قوله {فتمنوا الموت إن كنتم صادقين} {ولن يتمنوه} وفي الجمعة {ولا يتمنونه} لأن دعواهم في هذه السورة بالغة قاطعة وهي كون الجنة {لهم} بصفة الخلوص فبالغ في الرد عليهم بلن وهو أبلغ ألفاظ النفي ودعواهم في الجمعة قاصرة مترددة وهي زعمهم أنهم أولياء الله فاقتصر على {لا}"},{"id":"mutash-kirmani:23","bookId":"mutash-kirmani","type":"section","surah":2,"num":23,"title":"سورة البقرة","page":"ج1 ص76","text":"قوله {بل أكثرهم لا يؤمنون} وفي غيرها {لا يعقلون} {لا يعلمون} لأنهم بين ناقض عهد وجاحد حق إلا القليل منهم عبد الله بن سلام وأصحابه ولم يأت هذان المعنيان معا في غير هذه السورة"},{"id":"mutash-kirmani:24","bookId":"mutash-kirmani","type":"section","surah":2,"num":24,"title":"سورة البقرة","page":"ج1 ص77","text":"قوله {ولئن اتبعت أهواءهم بعد الذي جاءك من العلم} وفيها أيضا {من بعد ما جاءك من العلم} فجعل مكان قول {الذي} {ما} وزاد في أوله {من} لأن العلم في الآية الأولى علم بالكمال وليس وراءه علم لأن معناه بعد الذي جاءك من العلم بالله وصفاته وبأن الهدى هدى الله ومعناه بأن دين الله الإسلام وأن القرآن كلام الله فكان لفظ {الذي} أليق به من لفظ {ما} لأنه في التعريف أبلغ وفي الوصف أقعد لأن {الذي} تعرفه صلته فلا يتنكر قط وتتقدمه أسماء الإشارة نحو قوله {أم من هذا الذي هو جند لكم} {أم من هذا الذي يرزقكم} فيكتنف {الذي} بيانان هما الإشارة قبلها والصلة بعدها ويلزمه الألف واللام ويثنى ويجمع وليس لما شيء من ذلك لأنه يتنكر مرة ويتعرف أخرى ولا يقع وصفا لأسماء الإشارة ولا تدخله الألف واللام ولا يثنى ولا يجمع وخص الثاني {بما} لأن المعنى من بعد ما جاءك من العلم بأن قبلة الله هي الكعبة وذلك قليل من كثير من العلم وزيدت معه {من} التي لابتداء الغاية لأن تقديره من الوقت الذي جاءك فيه العلم بالقبلة لأن القبلة الأولى نسخت بهذه الآية وليست الأولى مؤقتة بوقت وقال في سورة الرعد {بعد ما جاءك} فعبر بلفظ {ما} ولم يزد {من} لأن العلم هنا هو الحكم العربي أي القرآن فكان بعضا من الأول ولم يزد فيه {من} لأنه غير مؤقت وقريب من معنى القبلة ما في آل عمران {من بعد ما جاءك من العلم} فهذا جاء بلفظ {ما} وزيدت فيه {من}"},{"id":"mutash-kirmani:25","bookId":"mutash-kirmani","type":"section","surah":2,"num":25,"title":"سورة البقرة","page":"ج1 ص77","text":"قوله {واتقوا يوما لا تجزي نفس عن نفس شيئا} هذه الآية والتي قبلها متكررتان وإنما كررت لأن كل واحدة منهما صادفت معصية تقتضي تنبيها ووعظا لأن كل واحدة وقعت في غير وقت الأخرى والمعصية الأول {أتأمرون الناس بالبر وتنسون أنفسكم} والثانية {ولن ترضى عنك اليهود ولا النصارى حتى تتبع ملتهم}"},{"id":"mutash-kirmani:26","bookId":"mutash-kirmani","type":"section","surah":2,"num":26,"title":"سورة البقرة","page":"ج1 ص78","text":"قوله {رب اجعل هذا بلدا آمنا} وفي إبراهيم {هذا البلد آمنا} لأن {هذا} هنا إشارة إلى المذكور في قوله {بواد غير ذي زرع} قبل بناء الكعبة وفي إبراهيم إشارة إلى البلد بعد الكعبة فيكون {بلدا} في هذه السورة المفعول الثاني و {آمنا} صفته {وهذا البلد} في إبراهيم المفعول الأول و {آمنا} المفعول الثاني وقيل لأن النكرة إذا تكررت صارت معرفة وقيل تقديره في البقرة البلدا بلدا آمنا فحذف اكتفاء بالإشارة فتكون الآيتان سواء"},{"id":"mutash-kirmani:27","bookId":"mutash-kirmani","type":"section","surah":2,"num":27,"title":"سورة البقرة","page":"ج1 ص78","text":"قوله {وما أنزل إلينا} في هذه السورة وفي آل عمران {علينا} لأن {إلى} للانتهاء إلى الشيء من أي جهة كانت والكتب منتهية إلى الأنبياء وإلى أممهم جميعا والخطاب في هذه السورة لهذه الأمة لقوله تعالى {قولوا} فلم يصح إلى {إلى} و {على} مختص بجانب الفوق وهو مختص بالأنبياء لأن الكتب منزلة عليهم لا شركة للأمة فيها وفي آل عمران {قل} وهو مختص بالنبي صلى الله عليه وسلم دون أمته فكان الذي يليق به {على} وزاد في هذه السورة {وما أوتي} وحذف من آل عمران لأن في آل عمران قد تقدم ذكر الأنبياء حيث قال {وإذ أخذ الله ميثاق النبيين لما آتيتكم من كتاب وحكمة}"},{"id":"mutash-kirmani:28","bookId":"mutash-kirmani","type":"section","surah":2,"num":28,"title":"سورة البقرة","page":"ج1 ص79","text":"قوله {ومن حيث خرجت} هذه الآية مكررة ثلاث مرات قيل إن الأولى لنسخ القبلة والثانية للسبب وهو قوله {وإنه للحق من ربك} والثالثة للعلة وهو قوله {لئلا يكون للناس عليكم حجة} وقيل الأولى في مسجد المدينة والثانية خارج المسجد والثالثة خارج البلد وقيل في الآيات خروجان خروج إلى مكان ترى فيه القبلة وخروج إلى مكان لا ترى أي الحالتان فيه سواء قلت إنما كرر لأن المراد بذلك الحال والمكان والزمان وقلت في الآية الأولى {ومن حيث خرجت} وليس فيها {وحيث ما كنتم} فجمع في الآية الثالثة بين قوله {حيث خرجت} {وحيث ما كنتم} ليعلم أن للنبي والمؤمنين في ذلك سواء"},{"id":"mutash-kirmani:29","bookId":"mutash-kirmani","type":"section","surah":2,"num":29,"title":"سورة البقرة","page":"ج1 ص79","text":"قوله {إلا الذين تابوا وأصلحوا وبينوا} ليس في هذه {من بعد ذلك} وفي غيرها {من بعد ذلك} لأن قبله هنا {من بعد ما بيناه} فلو أعاد التبس"},{"id":"mutash-kirmani:30","bookId":"mutash-kirmani","type":"section","surah":2,"num":30,"title":"سورة البقرة","page":"ج1 ص79","text":"قوله {لآيات لقوم يعقلون} خص العقل بالذكر لأن به يتوصل إلى معرفة الآيات ومثله في الرعد 4 والنحل 12 والنور 61 والروم 24"},{"id":"mutash-kirmani:31","bookId":"mutash-kirmani","type":"section","surah":2,"num":31,"title":"سورة البقرة","page":"ج1 ص80","text":"قوله {ما ألفينا عليه آباءنا} في هذه السورة وفي المائدة 4 7 ولقمان 21 {ما وجدنا} لأن ألفيت يتعدى إلى مفعولين تقول ألفيت زيدا قائما وألفيت عمرا على كذا ووجدت يتعدى مرة إلى مفعول واحد تقول وجدت الضالة ومرة إلى مفعولين تقول وجدت زيدا جالسا فهو مشترك فكان الموضع الأول باللفظ الأخص أولى لأن غيره إذا وقع موقعه في الثاني والثالث علم أنه بمعناه"},{"id":"mutash-kirmani:32","bookId":"mutash-kirmani","type":"section","surah":2,"num":32,"title":"سورة البقرة","page":"ج1 ص80","text":"قوله {أو لو كان آباؤهم لا يعلمون شيئا} وفي المائدة {لا يعلمون} لأن العلم أبلغ درجة من العقل ولهذا جاز وصف الله به ولم يجز وصفه بالعقل فكانت دعواهم في المائدة أبلغ لقولهم {حسبنا ما وجدنا عليه آباءنا} فادعوا النهاية بلفظ {حسبنا} فنفى ذلك بالعلم وهو النهاية وقال في البقرة {بل نتبع ما ألفينا عليه آباءنا} ولم تكن النهاية فنفى بما هو دون العلم لتكون كل دعوى منفية بما يلائمها والله أعلم"},{"id":"mutash-kirmani:33","bookId":"mutash-kirmani","type":"section","surah":2,"num":33,"title":"سورة البقرة","page":"ج1 ص80","text":"قوله {وما أهل به لغير الله} قدم {به} في هذه السورة وأخرها في المائدة 3 والأنعام 145 والنحل 115 لأن تقديم الباء الأصل فإنها تجري مجرى الهمزة والتشديد في التعدي فكانت كحرف من الفعل فكان الموضع الأول أولى بما هو الأصل ليعلم ما يقتضيه اللفظ ثم قدم فيما سواها ما هو المستنكر وهو الذبح لغير الله وتقديم ما هو الغرض أولى ولهذا جاز تقديم المفعول على الفاعل والحال على ذي الحال والظرف على العامل فيه إذا كان ذلك أكثر للغرض في الإخبار"},{"id":"mutash-kirmani:34","bookId":"mutash-kirmani","type":"section","surah":2,"num":34,"title":"سورة البقرة","page":"ج1 ص81","text":"قوله في هذه السورة {فلا إثم عليه} وفي السور الثلاث بحذفها لأنه لما قال في الموضع الأول {فلا إثم عليه} صريحا كان نفي الإثم في غيره تضمينا لأن قوله { غفور رحيم} يدل على أنه لا إثم عليه"},{"id":"mutash-kirmani:35","bookId":"mutash-kirmani","type":"section","surah":2,"num":35,"title":"سورة البقرة","page":"ج1 ص81","text":"قوله {إن الله غفور رحيم} في هذه السورة خلاف سورة الأنعام فإن فيها {فإن ربك غفور رحيم} لأن لفظ الرب تكرر في الأنعام مرات ولأن في الأنعام قوله {وهو الذي أنشأ جنات معروشات} الآية وفيها ذكر الحبوب والثمار وأتبعها بذكر الحيوان من الضأن والمعز والإبل وبها تربية الأجسام فكان ذكر الرب فيها أليق"},{"id":"mutash-kirmani:36","bookId":"mutash-kirmani","type":"section","surah":2,"num":36,"title":"سورة البقرة","page":"ج1 ص82","text":"قوله {إن الذين يكتمون ما أنزل الله من الكتاب ويشترون به ثمنا قليلا أولئك ما يأكلون في بطونهم إلا النار ولا يكلمهم الله يوم القيامة ولا يزكيهم ولهم عذاب أليم} الآية في السورة على هذا النسق وفي آل عمران {أولئك لا خلاق لهم في الآخرة ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم} لأن المنكر في هذه السورة أكثر فالمتوعد فيها أكثر وإن شئت قلت زاد في آل عمران {ولا ينظر إليهم} في مقابلة {ما يأكلون في بطونهم إلا النار}"},{"id":"mutash-kirmani:37","bookId":"mutash-kirmani","type":"section","surah":2,"num":37,"title":"سورة البقرة","page":"ج1 ص82","text":"قوله في آية الوصية {إن الله سميع عليم} خص السمع بالذكر لما في الآية من قوله {فمن بدله بعد ما سمعه} ليكون مطابقا وقال في الآية الأخرى بعدها {إن الله غفور رحيم} لقوله قبله {فلا إثم عليه} فهو مطابق معنى له"},{"id":"mutash-kirmani:38","bookId":"mutash-kirmani","type":"section","surah":2,"num":38,"title":"سورة البقرة","page":"ج1 ص82","text":"قوله {فمن كان منكم مريضا أو على سفر} قيد بقوله {منكم} وكذلك {فمن كان منكم مريضا أو به أذى من رأسه} ولم يقيد في قوله {ومن كان مريضا أو على سفر} اكتفاء بقوله {فمن شهد منكم الشهر فليصمه} لاتصاله به"},{"id":"mutash-kirmani:39","bookId":"mutash-kirmani","type":"section","surah":2,"num":39,"title":"سورة البقرة","page":"ج1 ص82","text":"قوله {تلك حدود الله فلا تقربوها} وقال بعده {تلك حدود الله فلا تعتدوها} لأن الحد الأول نهى وهو قوله {ولا تباشروهن وأنتم عاكفون في المساجد} وما كان من الحدود نهيا أمر بترك المقاربة والحد الثاني أمر وهو بيان عدد الطلاق بخلاف ما كان عليه العرب من المراجعة بعد الطلاق من غير عدد وما كان أمرا أمر بترك المجاوزة وهو الاعتداء"},{"id":"mutash-kirmani:40","bookId":"mutash-kirmani","type":"section","surah":2,"num":40,"title":"سورة البقرة","page":"ج1 ص83","text":"قوله {يسألونك عن الأهلة} جميع ما جاء في القرآن من السؤال وقع عقبه الجواب بغير الفاء إلا في قوله {ويسألونك عن الجبال فقل ينسفها ربي} فإنه أجيب بالفاء لأن الأجوبة في الجميع كانت بعد السؤال وفي طه قبل وقوع السؤال فكأنه قيل إن سئلت عن الجبال فقل ينسفها ربي"},{"id":"mutash-kirmani:41","bookId":"mutash-kirmani","type":"section","surah":2,"num":41,"title":"سورة البقرة","page":"ج1 ص83","text":"قوله {ويكون الدين لله} في هذه السورة وفي الأنفال {ويكون الدين كله لله} لأن القتال في هذه السورة مع أهل مكة وفي الأنفال مع جميع الكفار فقيده بقوله {كله}"},{"id":"mutash-kirmani:42","bookId":"mutash-kirmani","type":"section","surah":2,"num":42,"title":"سورة البقرة","page":"ج1 ص83","text":"قوله {أم حسبتم أن تدخلوا الجنة ولما يأتكم مثل الذين خلوا من قبلكم} وقال في آل عمران {أم حسبتم أن تدخلوا الجنة ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين} وقال في التوبة {أم حسبتم أن تتركوا ولما يعلم الله الذين جاهدوا منكم} الآية الخطيب أطنب في هذه الآيات ومحصول كلامه أن الأول للنبي والمؤمنين والثاني للمؤمنين والثالث للمخاطبين جميعا"},{"id":"mutash-kirmani:43","bookId":"mutash-kirmani","type":"section","surah":2,"num":43,"title":"سورة البقرة","page":"ج1 ص83","text":"قوله {لعلكم تتفكرون في الدنيا والآخرة} وفي آخر السورة {لعلكم تتفكرون} ومثله في الأنعام لأنه لما بين في الأول مفعول التفكر وهو قوله {في الدنيا والآخرة} حذفه مما بعده للعلم به وقيل في متعلقة بقوله {يبين الله لكم الآيات لعلكم تتفكرون}"},{"id":"mutash-kirmani:44","bookId":"mutash-kirmani","type":"section","surah":2,"num":44,"title":"سورة البقرة","page":"ج1 ص84","text":"قوله {ولا تنكحوا المشركات} بفتح التاء والثاني بضمها لأن الأول من نكحت والثاني من أنكحت وهو يتعدى إلى مفعولين والمفعول الأول في الآية المشركين والثاني محذوف وهو المؤمنات أي لا تنكحوا المشركين النساء المؤمنات حتى يؤمنوا"},{"id":"mutash-kirmani:45","bookId":"mutash-kirmani","type":"section","surah":2,"num":45,"title":"سورة البقرة","page":"ج1 ص84","text":"قوله {ولا تمسكوهن} أجمعوا على تخفيفه إلا شاذا وما في عير هذه السورة قرئ بالوجهين لأن قبله {فأمسكوهن} وقبل ذلك {فإمساك} فاقتضى ذلك التخفيف"},{"id":"mutash-kirmani:46","bookId":"mutash-kirmani","type":"section","surah":2,"num":46,"title":"سورة البقرة","page":"ج1 ص84","text":"قوله {ذلك يوعظ به من كان منكم} وفي الطلاق {ذلكم يوعظ به من كان يؤمن} الكاف في ذلك لمجرد الخطاب لا محل له من الإعراب فجاز الاختصار على التوحيد وجاز إجراؤه على عدد المخاطبين ومثله {عفونا عنكم من بعد ذلك} وقيل حيث جاء موحدا فالخطاب للنبي صلى الله عليه وسلم وخص بالتوحيد في هذه السورة لقوله {من كان منكم} وجمع في الطلاق لما لم يكن بعده {منكم}"},{"id":"mutash-kirmani:47","bookId":"mutash-kirmani","type":"section","surah":2,"num":47,"title":"سورة البقرة","page":"ج1 ص86","text":"قوله {فلا جناح عليكم فيما فعلن في أنفسهن بالمعروف} وقال في الآية الأخرى من معروف 240 لأن تقدير الأول فيما فعلن بأمر الله وهو المعروف والثاني فيما فعلن في أنفسهن فعلا من أفعالهن معروفا أي جاز فعله شرعا قال أبو مسلم حاكيا عن الخطيب إنما جاء المعروف الأول معرف اللفظ لأن المعنى بالوجه المعروف من الشرع لهن وهو الوجه الذي دل الله عليه وأبانه والثاني كان وجها من الوجوه التي لهن أن يأتينه فأخرج مخرج النكرة لذلك قلت النكرة إذا تكررت صارت معرفة فإن قيل كيف يصح ما قلت والأول معرفة والثاني نكرة وما ذهبت إليه يقتضي ضد هذا بدليل قوله تعالى {كما أرسلنا إلى فرعون رسولا} {فعصى فرعون الرسول} فالجواب أن هذه الآية بإجماع من المفسرين مقدمة على تلك الآية في النزول وإن وقعت متأخرة في التلاوة ولهذا نظير في القرآن في موضع آخر أو موضعين وقد سبق بيانه وأجمعوا أيضا على أن هذه الآية منسوخة بتلك الآية والمنسوخ سابق على الناسخ ضرورة فصح ما ذكرت أن قوله بالمعروف هو ما ذكر في قوله من معروف فتأمل فيه فإن هذا دليل على إعجاز القرآن"},{"id":"mutash-kirmani:48","bookId":"mutash-kirmani","type":"section","surah":2,"num":48,"title":"سورة البقرة","page":"ج1 ص86","text":"قوله {ولو شاء الله ما اقتتلوا} كرر هنا تأكيدا وقيل ليس بتكرار لأن الأول للجماعة والثاني للمؤمنين وقيل كرر تكذيبا لمن زعم أن ذلك لم يكن بمشيئة الله تعالى"},{"id":"mutash-kirmani:49","bookId":"mutash-kirmani","type":"section","surah":2,"num":49,"title":"سورة البقرة","page":"ج1 ص86","text":"قوله {ويكفر عنكم من سيئاتكم} في هذه السورة بزيادة {من} موافقة لما بعدها لأن بعدها ثلاث آيات فيها {من} على التوالي وهي قوله {وما تنفقوا من خير} ثلاث مرات"},{"id":"mutash-kirmani:50","bookId":"mutash-kirmani","type":"section","surah":2,"num":50,"title":"سورة البقرة","page":"ج1 ص87","text":"قوله {فيغفر لمن يشاء ويعذب من يشاء} {يغفر} مقدم في هذه السورة وغيرها إلا في المائدة فإن فيها {يعذب من يشاء ويغفر} لأنها نزلت بعدها في حق السارق والسارقة وعذابهما يقع في الدنيا فقدم لفظ العذاب وفي غيرها قدم لفظ المغفرة رحمة منه تعالى وترغيبا للعباد في المسارعة إلى موجبات المغفرة جعلنا الله تعالى منهم يمنه وكرمه"},{"id":"mutash-kirmani:51","bookId":"mutash-kirmani","type":"section","surah":3,"num":51,"title":"سورة آل عمران","page":"ج1 ص87","text":"قوله تعالى {إنك جامع الناس ليوم لا ريب فيه إن الله لا يخلف الميعاد} أو السورة وفي آخرها {إنك لا تخلف الميعاد} فعدل من الخطاب إلى لفظ الغيبة في أول السورة واستمر على الخطاب في آخرها لأن ما في أول السورة لا يتصل بالكلام الأول كاتصال ما في آخرها فإن اتصال قوله تعالى {إن الله لا يخلف الميعاد} بقوله {إنك جامع الناس ليوم لا ريب فيه} معنوي واتصال قوله {إنك لا تخلف الميعاد} بقوله {ربنا وآتنا ما وعدتنا} لفظي ومعنوي جميعا لتقدم لفظ الوعد ويجوز أن يكون الأول استئنافا والآخر من تمام الكلام"},{"id":"mutash-kirmani:52","bookId":"mutash-kirmani","type":"section","surah":3,"num":52,"title":"سورة آل عمران","page":"ج1 ص87","text":"قوله {كدأب آل فرعون والذين من قبلهم كذبوا بآياتنا فأخذهم الله} كان القياس فأخذناهم لكن لما عدل في الآية الأولى إلى قوله {إن الله لا يخلف الميعاد} عدل في هذه الآية أيضا لتكون الآيات على منهج واحد"},{"id":"mutash-kirmani:53","bookId":"mutash-kirmani","type":"section","surah":3,"num":53,"title":"سورة آل عمران","page":"ج1 ص88","text":"قوله {شهد الله أنه لا إله إلا هو} ثم كرر في هذه الآية فقال {لا إله إلا هو} لأن الأول جرى مجرى الشهادة وأعاده ليجري الثاني مجرى الحكم بصحة ما شهد به الشهود"},{"id":"mutash-kirmani:54","bookId":"mutash-kirmani","type":"section","surah":3,"num":54,"title":"سورة آل عمران","page":"ج1 ص88","text":"قوله {ويحذركم الله نفسه} كرره مرتين لأنه وعيد عطف عليه وعيد آخر في الآية الأولى فإن قوله {وإلى الله المصير} معناه مصيركم إلى الله والعذاب معد لديه فاستدركه في الآية الثانية بوعد وهو قوله تعالى {والله رؤوف بالعباد} والرأفة أشد من الرحمة وقيل من رأفته تحذيره"},{"id":"mutash-kirmani:55","bookId":"mutash-kirmani","type":"section","surah":3,"num":55,"title":"سورة آل عمران","page":"ج1 ص88","text":"قوله {قال رب أنى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر} قدم في هذه السورة ذكر الكبر وأخر ذكر المرأة وقال في سورة مريم {وكانت امرأتي عاقرا وقد بلغت من الكبر عتيا} فقدم ذكر المرأة لأن في مريم قد تقدم ذكر الكبر في قوله {وهن العظم مني} وتأخر ذكر المرأة في قوله {وإني خفت الموالي من ورائي وكانت امرأتي عاقرا} ثم أعاد ذكرها فأخر ذكر الكبر ليوافق {عتيا} ما بعده من الآيات وهي {سويا} و {عشيا} و {صبيا}"},{"id":"mutash-kirmani:56","bookId":"mutash-kirmani","type":"section","surah":3,"num":56,"title":"سورة آل عمران","page":"ج1 ص88","text":"قوله {قالت رب أنى يكون لي ولد} وفي مريم {قال رب أنى يكون لي غلام} لأن في هذه السورة تقدم ذكر المسيح وهو ولدها وفي مريم تقدم ذكر الغلام حيث قال {لأهب لك غلاما زكيا}"},{"id":"mutash-kirmani:57","bookId":"mutash-kirmani","type":"section","surah":3,"num":57,"title":"سورة آل عمران","page":"ج1 ص89","text":"قوله {فأنفخ فيه} وفي المائدة {فتنفخ فيها} قيل الضمير في هذه السورة يعود إلى الطير وقيل إلى الطين وقيل إلى المهيأ وقيل إلى الكاف فإنه في معنى مثل وفي المائدة يعود إلى الهيئة وهذا جواب التذكير والتأنيث لا جواب التخصيص وإنما الكلام وقع في التخصيص وهل يجوز أن يكون كل واحد منهما مكان الآخر أم لا فالجواب أن يقال في هذه السورة إخبار قبل الفعل فوحده وفي المائدة خطاب من الله تعالى له يوم القيامة وقد تقدم من عيسى عليه السلام الفعل مرات والطير صالح للواحد وصالح للجميع"},{"id":"mutash-kirmani:58","bookId":"mutash-kirmani","type":"section","surah":3,"num":58,"title":"سورة آل عمران","page":"ج1 ص90","text":"قوله {بإذن الله} ذكر في هذه الآية مرتين وقال في المائدة {بإذني} أربع مرات لأن ما في هذه السورة كلام عيسى فما يتصور أن يكون من فعل البشر أضافه إلى نفسه وهو الخلق الذي معناه التقدير والنفخ الذي هو إخراج الريح من الفم وما يتصور إضافته إلى الله تعالى أضافه إليه وهو قوله {فيكون طيرا بإذن الله وأبرئ الأكمه والأبرص} بما يكون في طوق البشر فإن الأكمة عند بعض المفسرين الأعمش وعند بعضهم الأعشى وعند بعضهم الذي يولد أعمى وإحياء الموتى من فعل الله فأضافه إليه وما في المائدة من كلام الله سبحانه وتعالى فأضاف جميع ذلك إلى صنعه إظهارا لعجز البشر ولأن فعل العبد مخلوق لله تعالى وقيل {بإذن الله} يعود إلى الأفعال الثلاثة وكذلك الثاني يعود إلى الثلاثة الأخرى"},{"id":"mutash-kirmani:59","bookId":"mutash-kirmani","type":"section","surah":3,"num":59,"title":"سورة آل عمران","page":"ج1 ص90","text":"قوله {إن الله ربي وربكم} وكذلك في مريم {ربي وربكم} وفي الزخرف في هذه القصة {إن الله هو ربي وربكم} بزيادة هو قال الشيخ إذا قلت زيد هو قائم فيحتمل أن يكون تقديره وعمر قائم فإذا قلت زيد هو القائم خصصت القيام به فهو كذلك في الآية وهذا مثاله لأن هو يذكر في مثل هذه المواضع إعلاما أن المبتدأ مقصور على هذا الخبر وهذا الخبر مقصور عليه دون غيره والذي في آل عمران وقع بعد عشر آيات من قصتها وليس كذلك ما في الزخرف فإنه ابتداء كلام منه فحسن التأكيد بقوله هو ليصير المبتدأ مقصورا على الخبر المذكور في الآية وهو إثبات الربوبية ونفى الأبوة تعالى الله عن ذلك علوا كبيرا"},{"id":"mutash-kirmani:60","bookId":"mutash-kirmani","type":"section","surah":3,"num":60,"title":"سورة آل عمران","page":"ج1 ص90","text":"قوله {بأنا مسلمون} في هذه السورة وفي المائدة {بأننا} لأن ما في المائدة أول كلام الحواريين فجاء على الأصل وما في هذه السورة تكرار لكلامهم فجاز فيه التخفيف لأن التخفيف فرع والتكرار فرع والفرع بالفرع أولى"},{"id":"mutash-kirmani:61","bookId":"mutash-kirmani","type":"section","surah":3,"num":61,"title":"سورة آل عمران","page":"ج1 ص91","text":"قوله {الحق من ربك فلا تكن} في هذه السورة وفي البقرة {فلا تكونن} لأن ما في هذه السورة جاء على الأصل ولم يكن فيها ما أوجب إدخال نون التوكيد في الكلمة بخلاف سورة البقرة فإن فيها في أول القصة {فلنولينك قبلة ترضاها} بنون التوكيد فأوجب الازدواج إدخال النون في الكلمة فيصير التقدير فلنولينك قبلة ترضاها فلا تكونن من الممترين والخطاب في الآيتين للنبي صلى الله عليه وسلم والمراد به غيره"},{"id":"mutash-kirmani:62","bookId":"mutash-kirmani","type":"section","surah":3,"num":62,"title":"سورة آل عمران","page":"ج1 ص91","text":"قوله {قل إن الهدى هدى الله} في هذه السورة وفي البقرة {قل إن هدى الله هو الهدى} لأن الهدى في هذه السورة هو الدين وقد تقدم في قوله {لمن تبع دينكم} وهدى الله الإسلام فكأنه قال بعد قولهم {ولا تؤمنوا إلا لمن تبع دينكم} قل إن الدين عند الله الإسلام كما سبق في أول السورة والذي في البقرة معناه القبلة لأن الآية نزلت في تحويل القبلة وتقديره قل إن قبلة الله هي الكعبة"},{"id":"mutash-kirmani:63","bookId":"mutash-kirmani","type":"section","surah":3,"num":63,"title":"سورة آل عمران","page":"ج1 ص91","text":"قوله {من آمن تبغونها عوجا} ليس ههنا به ولا واو العطف وفي الأعراف {من آمن به وتبغونها} بزيادة به وواو العطف لأن القياس آمن به كما في الأعراف لكنها حذفت في هذه السورة موافقة لقوله {ومن كفر} فإن القياس فيه أيضا كفر به وقوله {تبغونها عوجا} ههنا حال والواو لا تزداد مع الفعل إذا وقع حالا نحو قوله {ولا تمنن تستكثر} و {دابة الأرض تأكل منسأته} وغير ذلك وفي الأعراف عطف على الحال والحال قوله {توعدون} و {تصدون} عطف عليه وكذلك {تبغونها عوجا}"},{"id":"mutash-kirmani:64","bookId":"mutash-kirmani","type":"section","surah":3,"num":64,"title":"سورة آل عمران","page":"ج1 ص92","text":"قوله {وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به وما النصر إلا من عند الله العزيز الحكيم} ههنا بإثبات {لكم} وتأخير {به} وحذف {إن الله} وفي الأنفال 10 بحذف لكم وتقديم به وإثبات إن الله لأن البشرى هنا للمخاطبين فبين وقال لكم وفي الأنفال قد تقدم لكم في قوله {فاستجاب لكم} فاكتفى بذلك وقدم {قلوبكم} هنا وأخر {به} ازدواجا بين المخاطبين فقال {وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به} وقدم {به} في الأنفال ازدواجا بين الغائبين فقال {وما جعله الله إلا بشرى ولتطمئن به قلوبكم} وحذف {إن الله} ههنا لأن ما في الأنفال قصة بدر وهي سابقة على ما في هذه السورة فإنها في قصة أحد وأخبر هناك بأن الله عزيز حكيم وجعله في هذه السورة صفة لأن الخبر قد سبق"},{"id":"mutash-kirmani:65","bookId":"mutash-kirmani","type":"section","surah":3,"num":65,"title":"سورة آل عمران","page":"ج1 ص92","text":"قوله {ونعم أجر العاملين} بزيادة الواو لأن الاتصال بما قبلها أكثر من غيرها وتقديره ونعم أجر العاملين المغفرة والجنات والخلود"},{"id":"mutash-kirmani:66","bookId":"mutash-kirmani","type":"section","surah":3,"num":66,"title":"سورة آل عمران","page":"ج1 ص93","text":"قوله {رسولا من أنفسهم} بزيادة الأنفس وفي غيرها {رسولا منكم} لأنه سبحانه من على المؤمنين به فجعله من أنفسهم ليكون موجب المنة أظهر وكذلك قوله {لقد جاءكم رسول من أنفسكم} لما وصفه بقوله {عزيز عليه ما عنتم حريص عليكم بالمؤمنين رؤوف رحيم} جعله من أنفسهم ليكون موجب الإجابة والإيمان أظهر وأبين"},{"id":"mutash-kirmani:67","bookId":"mutash-kirmani","type":"section","surah":3,"num":67,"title":"سورة آل عمران","page":"ج1 ص93","text":"قوله {جاؤوا بالبينات والزبر والكتاب المنير} ههنا بباء واحدة إلا في قراءة ابن عامر وفي فاطر {بالبينات وبالزبر وبالكتاب} بثلاثة باءات لأنه في هذه السورة وقع في كلام مبني على الاختصار وهو إقامة لفظ الماضي في الشرط مقام لفظ المستقبل ولفظ الماضي أخف وبني الفعل للمجهول فلا يحتاج إلى ذكر الفاعل وهو قوله {فإن كذبوك فقد كذب رسل من قبلك} لذلك حذفت الباءات ليوافق الأول في الاختصار بخلاف ما في فاطر فإن الشرط فيه بلفظ المستقبل والفاعل مذكور مع الفعل وهو قوله {وإن يكذبوك فقد كذب الذين من قبلهم} ثم ذكر بعدها الباءات ليكون كله على نسق واحد"},{"id":"mutash-kirmani:68","bookId":"mutash-kirmani","type":"section","surah":3,"num":68,"title":"سورة آل عمران","page":"ج1 ص94","text":"قوله {ثم مأواهم جهنم} ههنا وفي غيرها {ومأواهم جهنم} و66 9 لأن ما قبلها في هذه السورة {لا يغرنك تقلب الذين كفروا في البلاد} {متاع قليل} أي ذلك متاع في الدنيا قليل والقليل يدل على تراخ وإن صغر وقل وثم للتراخي فكان طبقا له والله تعالى أعلم"},{"id":"mutash-kirmani:69","bookId":"mutash-kirmani","type":"section","surah":4,"num":69,"title":"سورة النساء","page":"ج1 ص94","text":"قوله في هذه السورة {والله عليم حليم} ليس غيره أي عليم بالمضارة حليم عن المضادة"},{"id":"mutash-kirmani:70","bookId":"mutash-kirmani","type":"section","surah":4,"num":70,"title":"سورة النساء","page":"ج1 ص94","text":"قوله {خالدين فيها وذلك الفوز العظيم} بالواو وفي براءة {ذلك} بغير واو لأن الجملة إذا وقعت بعد جملة أجنبية لا تحسن إلا بحرف العطف وإن كان في الجملة الثانية ما يعود إلى الأولى حسن إثبات حرف العطف وحسن الحذف اكتفاء بالعائد ولفظ {ذلك} في الآيتين يعود إلى ما قبل الجملة فحسن الحذف والإثبات فيهما ولتخصيص هذه السورة بالواو وجهان لم يكونا في براءة أحدهما موافقة لما قبلها وهي جملة مبدوءة بالواو وذلك قوله {ومن يطع الله} والثاني موافقة لما بعدها وهو قوله {وله} بعد قوله {خالدا فيها} وفي براءة {أعد الله} بغير واو ولذلك قال {ذلك} بغير واو"},{"id":"mutash-kirmani:71","bookId":"mutash-kirmani","type":"section","surah":4,"num":71,"title":"سورة النساء","page":"ج1 ص95","text":"قوله {محصنين غير مسافحين} في أول السورة وبعدها {محصنات غير مسافحات ولا متخذات أخدان} وفي المائدة {محصنين غير مسافحين ولا متخذي أخدان} لأن في هذه السورة وقع في حق الأحرار المسلمين فاقتصر على لفظ {غير مسافحين} والثانية في الجواري وما في المائدة في الكتابيات فقال {ولا متخذي أخدان} حرمة للحرائر المسلمات لأنهن إلى الصيانة أقرب ومن الخيانة أبعد ولأنهن لا يتعاطين ما يتعاطاه الإماء والكتابيات من اتخاذ الأخذان"},{"id":"mutash-kirmani:72","bookId":"mutash-kirmani","type":"section","surah":4,"num":72,"title":"سورة النساء","page":"ج1 ص95","text":"قوله {فامسحوا بوجوهكم وأيديكم} في هذه السورة وزاد في المائدة {منه} لأن المذكور في هذه بعض أحكام الوضوء والتيمم فحسن الحذف والمذكور في المائدة جميع أحكامهما فحسن الإثبات والبيان"},{"id":"mutash-kirmani:73","bookId":"mutash-kirmani","type":"section","surah":4,"num":73,"title":"سورة النساء","page":"ج1 ص95","text":"قوله {إن الله لا يغفر أن يشرك به} ختم الآية مرة بقوله {فقد افترى} ومرة بقوله {فقد ضل} لأن الأول نزل في اليهود وهم الذين افتروا على الله ما ليس في كتابهم والثاني نزل في الكفار ولم يكن لهم كتاب فكان ضلالهم أشد"},{"id":"mutash-kirmani:74","bookId":"mutash-kirmani","type":"section","surah":4,"num":74,"title":"سورة النساء","page":"ج1 ص96","text":"قوله {يا أيها الذين أوتوا الكتاب} وفي غيرها {يا أهل الكتاب} و5 19 59 الخ لأنه سبحانه استخف بهم في هذه الآية وبالغ ثم ختم بالطمس ورد الوجوه على الأدبار واللعن وبأنها كلها واقعة بهم"},{"id":"mutash-kirmani:75","bookId":"mutash-kirmani","type":"section","surah":4,"num":75,"title":"سورة النساء","page":"ج1 ص96","text":"قوله {درجة} ثم في الآيات الأخرى {درجات} و3 163 و4 96 و6 83 132 لأن الأولى في الدنيا والثاني في الجنة وقيل الأولى المنزلة والثانية المنزل وهو درجات وقيل الأولى على القاعدين بعذر والثانية على القاعدين بغير عذر"},{"id":"mutash-kirmani:76","bookId":"mutash-kirmani","type":"section","surah":4,"num":76,"title":"سورة النساء","page":"ج1 ص97","text":"قوله {ومن يشاقق الرسول} بالإظهار في هذه السورة وكذلك في الأنفال 13 وفي الحشر بالإدغام 4 لأن الثاني من المثلين إذا تحرك بحركة لازمة وجب إدغام الأول في الثاني ألا ترى أنك تقول اردد له بالإظهار ولا يجوز ارددا أو ارددوا أو ارددي لأنها تحركت بحركة لازمة الألف واللام في الله لازمتان فصارت حركة القاف لازمة وليس الألف واللام في الرسول كذلك وأما في الأنفال فلانضمام الرسول إليه في العطف ولم يدغم فيها لأن التقدير في القافات قد اتصل بهما فإن الواو توجب ذلك"},{"id":"mutash-kirmani:77","bookId":"mutash-kirmani","type":"section","surah":4,"num":77,"title":"سورة النساء","page":"ج1 ص97","text":"قوله {كونوا قوامين بالقسط شهداء لله} وفي المائدة {قوامين لله شهداء بالقسط} لأن لله في هذه السورة متصل ومتعلق بالشهادة بدليل قوله {ولو على أنفسكم أو الوالدين والأقربين} أي ولو تشهدون عليهم وفي المائدة منفصل ومتعلق بقوامين والخطاب للولاة بدليل قوله {ولا يجرمنكم شنآن قوم} الآية"},{"id":"mutash-kirmani:78","bookId":"mutash-kirmani","type":"section","surah":4,"num":78,"title":"سورة النساء","page":"ج1 ص97","text":"قوله {إن تبدوا خيرا أو تخفوه} في هذه السورة وفي الأحزاب {إن تبدوا شيئا} لأن في هذه السورة وقع الخبر في مقابلة السوء في قوله {لا يحب الله الجهر بالسوء} والمقابلة اقتضت أن يكون بإزاء السوء الخير وفي الأحزاب وقع بعدها {لئن لم ينته المنافقون والذين في قلوبهم مرض} فاقتضى العموم وأعم الأسماء شيء ثم ختم الآية بقوله {فإن الله كان بكل شيء عليما}"},{"id":"mutash-kirmani:79","bookId":"mutash-kirmani","type":"section","surah":4,"num":79,"title":"سورة النساء","page":"ج1 ص98","text":"قوله {وإن تكفروا فإن لله ما في السماوات والأرض} وسائر ما في هذه السورة {ما في السماوات وما في الأرض} لأن الله سبحانه ذكر أهل الأرض في هذه الآية تبعا لأهل السموات ولم يفردهم بالذكر لانضمام المخاطبين إليهم ودخولهم في زمرتهم وهم كفار عبدة أوثان وليسوا بمؤمنين ولا من أهل الكتب لقوله {وإن تكفروا} وليس هذا قياسا مطردا بل علامة"},{"id":"mutash-kirmani:80","bookId":"mutash-kirmani","type":"section","surah":4,"num":80,"title":"سورة النساء","page":"ج1 ص98","text":"قوله {يستفتونك} بغير واو لأن الأول لما اتصل بما بعده وهو قوله {في النساء} وصله بما قبله بواو العطف والعائد جميعا والثاني لما انفصل عما بعده اقتصر من الاتصال على العائد وهو ضمير المستفتين وفي الآية متصل بقوله {يفتيكم} وليس بمتصل بقوله {يستفتونك} لأن ذلك يستدعي {قل الله يفتيكم في الكلالة} والذي يتصل يستفتونك محذوف يحتمل أن يكون في الكلالة ويحتمل أن يكون فيما بدا لهم من الوقائع"},{"id":"mutash-kirmani:81","bookId":"mutash-kirmani","type":"section","surah":5,"num":81,"title":"سورة المائدة","page":"ج1 ص99","text":"قوله {واخشون اليوم} بحذف الياء وكذلك {واخشون ولا تشتروا} وفي البقرة وغيرها {واخشوني} بالإثبات لأن الإثبات هو الأصل وحذفت الياء من {واخشون اليوم} من الخط لما حذفت من اللفظ وحذفت من {واخشون ولا تشتروا} موافقة لما قبلها"},{"id":"mutash-kirmani:82","bookId":"mutash-kirmani","type":"section","surah":5,"num":82,"title":"سورة المائدة","page":"ج1 ص99","text":"قوله {واتقوا الله إن الله عليم بذات الصدور} ثم أعاد فقال {واتقوا الله إن الله خبير بما تعملون} لأن الأول وقع على النية وهي بذات الصدور والثاني على العمل وعن ابن كثير أن الأولى نزلت في اليهود وليس بتكرار"},{"id":"mutash-kirmani:83","bookId":"mutash-kirmani","type":"section","surah":5,"num":83,"title":"سورة المائدة","page":"ج1 ص100","text":"قوله {وعد الله الذين آمنوا وعملوا الصالحات لهم مغفرة وأجر عظيم} وقال في الفتح {وعد الله الذين آمنوا وعملوا الصالحات منهم مغفرة وأجرا عظيما} رفع ما في هذه السورة موافقة لفواصل الآي ونصب ما في فتح موافقة للفواصل أيضا ولأنه في الفتح مفعول وعد وفي مفعول وعد في هذه السورة أقوال أحدها محذوف دل عليه وعد خلاف ما دل عليه أو أوعد أي خيرا وقوله {لهم مغفرة} يفسره وقيل {لهم مغفرة} جملة وقعت موقع المفرد ومحلها نصب كما قال الشاعر ... وجدنا الصالحين لهم جزاء ... وجنات وعينا سلسبيلا ... فعطف جنات على محل لهم جزاء وقيل رفع على الحكاية لأن الوعد قول وتقديره قال الله لهم مغفرة وقيل تقديره إن لهم مغفرة فحذف إن فارتفع ما بعده"},{"id":"mutash-kirmani:84","bookId":"mutash-kirmani","type":"section","surah":5,"num":84,"title":"سورة المائدة","page":"ج1 ص100","text":"قوله {يحرفون الكلم عن مواضعه} وبعده {يحرفون الكلم من بعد مواضعه} لأن الأولى في أوائل اليهود والثانية فيمن كانوا في زمن النبي صلى الله عليه وسلم أي حرفوها بعد أن وضعها الله مواضعها وعرفوها وعملوا بها زمانا"},{"id":"mutash-kirmani:85","bookId":"mutash-kirmani","type":"section","surah":5,"num":85,"title":"سورة المائدة","page":"ج1 ص100","text":"قوله {ونسوا حظا مما ذكروا به} كرر لأن الأولى في اليهود والثانية في حق النصارى والمعنى لم ينالو منه نصيبا وقيل معناه ونسوا نصيبا وقيل معناه تركوا بعض ما أمروا به"},{"id":"mutash-kirmani:86","bookId":"mutash-kirmani","type":"section","surah":5,"num":86,"title":"سورة المائدة","page":"ج1 ص101","text":"قوله {يا أهل الكتاب قد جاءكم رسولنا يبين لكم} ثم كررها فقال {يا أهل الكتاب} لأن الأولى نزلت في اليهود حين كتموا صفة محمد صلى الله عليه وسلم وآية الرجم من التوراة والنصارى حين كتموا بشارة عيسى بمحمد صلى الله عليه وسلم في الإنجيل وهو قوله {يبين لكم كثيرا مما كنتم تخفون من الكتاب} ثم كرر فقال {وقالت اليهود والنصارى نحن أبناء الله وأحباؤه} فكرر {يا أهل الكتاب قد جاءكم رسولنا يبين لكم} أي شرائعكم فإنكم على ضلال لا يرضاه الله على {فترة من الرسل} على انقطاع منهم ودروس مما جاءوا به والله أعلم"},{"id":"mutash-kirmani:87","bookId":"mutash-kirmani","type":"section","surah":5,"num":87,"title":"سورة المائدة","page":"ج1 ص102","text":"قوله {ولله ملك السماوات والأرض وما بينهما يخلق ما يشاء} ثم كرر فقال {ولله ملك السماوات والأرض وما بينهما وإليه المصير} كرر لأن الأولى نزلت في النصارى حين قالوا {إن الله هو المسيح ابن مريم} فقال {ولله ملك السماوات والأرض وما بينهما} ليس فيهما معه شريك ولو كان عيسى إلها لاقتضى أن يكون معه شريكا ثم من يذب عن المسيح وأمه وعمن في الأرض جميعا إن أراد إهلاكهم فإنهم كلهم مخلوقون له وإن قدرته شاملة عليهم وعلى كل ما يريد بهم والثانية نزلت في اليهود والنصارى حين قالوا {نحن أبناء الله وأحباؤه} فقال {ولله ملك السماوات والأرض وما بينهما} والأب لا يملك ابنه ولا يهلكه ولا يعذبه وأنتم مصيركم إليه فيعذب من يشاء منكم ويغفر لمن يشاء"},{"id":"mutash-kirmani:88","bookId":"mutash-kirmani","type":"section","surah":5,"num":88,"title":"سورة المائدة","page":"ج1 ص102","text":"قوله {وإذ قال موسى لقومه يا قوم اذكروا} وقال في سورة إبراهيم {وإذ قال موسى لقومه اذكروا} لأن تصريح اسم المخاطب مع حرف الخطاب يدل على تعظيم المخاطب به ولما كان ما في هذه السورة نعما جساما ما عليها من مزيد وهو قوله {جعل فيكم أنبياء وجعلكم ملوكا وآتاكم ما لم يؤت أحدا من العالمين} صرح فقال يا قوم ولموافقته ما قبله وما بعده من النداء وهو قوله {يا قوم ادخلوا} {يا موسى إنا} ولم يكن ما في إبراهيم بهذه المنزلة فاقتصر على حرف الخطاب"},{"id":"mutash-kirmani:89","bookId":"mutash-kirmani","type":"section","surah":5,"num":89,"title":"سورة المائدة","page":"ج1 ص102","text":"قوله {ومن لم يحكم بما أنزل الله} كرره ثلاث مرات وختم الأولى بقوله {فأولئك هم الكافرون} والثانية بقوله {فأولئك هم الظالمون} والثالثة بقوله {فأولئك هم الفاسقون} قيل لأن الأولى نزلت في حكام المسلمين والثانية في حكام اليهود والثالثة في حكام النصارى وقيل الكافر والفاسق والظالم كلها بمعنى واحد وهو الكفر عبر عنه بألفاظ مختلفة لزيادة الفائدة واجتناب سورة التكرار وقيل ومن لم يحكم بما أنزل الله إنكارا له فهو كافر ومن لم يحكم بالحق مع اعتقاده حقا وحكم بضده فهو ظالم ومن لم يحكم بالحق جهلا وحكم بضده فهو فاسق وقيل ومن لم يحكم بما أنزل الله فهو كافر بنعمه الله ظالم في حكمه فاسق في فعله"},{"id":"mutash-kirmani:90","bookId":"mutash-kirmani","type":"section","surah":5,"num":90,"title":"سورة المائدة","page":"ج1 ص103","text":"قوله {لقد كفر الذين قالوا إن الله ثالث ثلاثة} كرر لأن النصارى اختلفت أقوالهم فقالت اليعقوبية إن الله تعالى ربما تجلى في بعض الأزمان في شخص فتجلى يومئذ في شخص عيسى فظهرت منه المعجزات وقالت الملكية إن الله اسم يجمع أبا وابنا وروح القدس اختلفت بالأقانيم والذات واحدة فأخبر الله عز وجل أنهم كلهم كفار"},{"id":"mutash-kirmani:91","bookId":"mutash-kirmani","type":"section","surah":5,"num":91,"title":"سورة المائدة","page":"ج1 ص103","text":"قوله {لهم جنات تجري من تحتها الأنهار خالدين فيها أبدا رضي الله عنهم ورضوا عنه ذلك الفوز العظيم} ذكر في هذه السورة هذه الخلال جملة ثم فصل لأنها أول ما ذكرت"},{"id":"mutash-kirmani:92","bookId":"mutash-kirmani","type":"section","surah":6,"num":92,"title":"سورة الأنعام","page":"ج1 ص103","text":"قوله {فقد كذبوا بالحق لما جاءهم فسوف يأتيهم} وفي الشعراء {فقد كذبوا فسيأتيهم} لأن سورة الأنعام متقدمة فقيد التكذيب بقوله {بالحق لما جاءهم} ثم قال {فسوف يأتيهم} على التمام وذكر في الشعراء {فقد كذبوا} مطلقا لأن تقييده في هذه السورة يدل عليه ثم اقتصر على السين هنا بدل سوف ليتفق اللفظان فيه على الاختصار"},{"id":"mutash-kirmani:93","bookId":"mutash-kirmani","type":"section","surah":6,"num":93,"title":"سورة الأنعام","page":"ج1 ص104","text":"قوله {ألم يروا كم أهلكنا} في بعض المواضع بغير واو كما في هذه السورة وفي بعضها بالواو وفي بعضها بالفاء هذه الكلمة تأتي في القرآن على وجهين أحدهما متصل بما كان الاعتبار فيه بالمشاهدة فذكره بالألف والواو لتدل الألف على الاستفهام والواو على عطف جملة على جملة قبلها وكذا الفاء لكنها أشد اتصالا بما قبلها والوجه الثاني متصل بما الاعتبار فيه بالاستدلال فاقتصر على الألف دون الواو والفاء لتجري مجرى الاستئناف ولا ينقض هذا الأصل قوله {أولم يروا إلى الطير} في النحل لاتصالها بقوله {والله أخرجكم من بطون أمهاتكم} وسبيله الاعتبار بالاستدلال فبنى عليه {أولم يروا إلى الطير}"},{"id":"mutash-kirmani:94","bookId":"mutash-kirmani","type":"section","surah":6,"num":94,"title":"سورة الأنعام","page":"ج1 ص104","text":"قوله {قل سيروا في الأرض ثم انظروا} في هذه السورة فحسب وفي غيرها {سيروا في الأرض فانظروا} و16 36 و27 69 و30 42 لأن ثم للتراخي والفاء للتعقيب وفي هذه السورة تقدم ذكر القرون في قوله {كم أهلكنا من قبلهم من قرن} ثم قال {وأنشأنا من بعدهم قرنا آخرين} فأمروا باستقراء الديار وتأمل الآثار وفيها كثرة فيقع ذلك سيرا بعد سير وزمانا بعد زمان فخصت بثم الدالة على التراخي بين الفعلين ليعلم أن السير مأمور به على حدة والنظر مأمور به على حدة ولم يتقدم في سائر السور مثله فخصت بالفاء الدالة على التعقيب"},{"id":"mutash-kirmani:95","bookId":"mutash-kirmani","type":"section","surah":6,"num":95,"title":"سورة الأنعام","page":"ج1 ص105","text":"قوله {الذين خسروا أنفسهم فهم لا يؤمنون} ليس بتكرار لأن الأول في حق الكفار والثاني في حق أهل الكتاب"},{"id":"mutash-kirmani:96","bookId":"mutash-kirmani","type":"section","surah":6,"num":96,"title":"سورة الأنعام","page":"ج1 ص105","text":"قوله {ومن أظلم ممن افترى على الله كذبا أو كذب بآياته إنه لا يفلح الظالمون} وقال في يونس {فمن أظلم} وختم الآية بقوله {إنه لا يفلح المجرمون} لأن الآيات التي تقدمت في هذه السورة عطف بعضها على بعض بالواو وهو قوله {وأوحي إلي هذا القرآن لأنذركم به ومن بلغ} إلى {وإنني بريء مما تشركون} ثم قال {ومن أظلم} وختم الآية بقوله {الظالمون} ليكون آخر الآية لفقا لأول الأولى وأما في سورة يونس فالآيات التي تقدمت عطف بعضها على بعض بالفاء وهو قوله {فقد لبثت فيكم عمرا من قبله أفلا تعقلون} ثم قال {فمن أظلم} بالفاء وختم الآية بقوله {المجرمون} أيضا موافقة لما قبلها وهو {كذلك نجزي القوم المجرمين} فوصفهم بأنهم مجرمون وقال بعده {ثم جعلناكم خلائف في الأرض من بعدهم} فختم الآية بقوله {المجرمون} ليعلم أن سبيل هؤلاء سبيل من تقدمهم"},{"id":"mutash-kirmani:97","bookId":"mutash-kirmani","type":"section","surah":6,"num":97,"title":"سورة الأنعام","page":"ج1 ص106","text":"قوله {ومنهم من يستمع إليك} وفي يونس {يستمعون} لأن ما في هذه السورة نزل في أبي سفيان والنضر بن الحارث وعتبة وشيبة وأمية وأبي بن خلف فلم يكثروا كثرة من في يونس لأن المراد بهم في يونس جميع الكفار فحمل ههنا مرة على لفظ من فوحد لقلتهم ومرة على المعنى فجمع لأنهم وإن قلوا كانوا جماعة وجمع ما في يونس ليوافق اللفظ المعنى وأما قوله في يونس {ومنهم من ينظر إليك} فسيأتي في موضعه إن شاء الله"},{"id":"mutash-kirmani:98","bookId":"mutash-kirmani","type":"section","surah":6,"num":98,"title":"سورة الأنعام","page":"ج1 ص106","text":"قوله {ولو ترى إذ وقفوا على النار} ثم أعاد فقال {ولو ترى إذ وقفوا على ربهم} لأنهم أنكروا النار في القيامة وأنكروا جزاء الله ونكاله فقال في الأولى {إذ وقفوا على النار} وفي الثانية {وقفوا على ربهم} أي على جزاء ربهم ونكاله في النار وختم بقوله {فذوقوا العذاب بما كنتم تكفرون}"},{"id":"mutash-kirmani:99","bookId":"mutash-kirmani","type":"section","surah":6,"num":99,"title":"سورة الأنعام","page":"ج1 ص106","text":"قوله {إن هي إلا حياتنا الدنيا وما نحن بمبعوثين} ليس غيره وفي غيرها بزيادة {نموت ونحيا} و45 24 لأن ما في هذه السورة عند كثير من المفسرين متصل بقوله {ولو ردوا لعادوا لما نهوا عنه وإنهم لكاذبون} {وقالوا إن هي إلا حياتنا الدنيا وما نحن بمبعوثين}"},{"id":"mutash-kirmani:100","bookId":"mutash-kirmani","type":"section","surah":6,"num":100,"title":"سورة الأنعام","page":"ج1 ص106","text":"ولم يقولوا ذلك أي {نموت ونحيا} بخلاف ما في سائر السور فإنهم قالوا ذلك فحكى الله عنهم ذلك"},{"id":"mutash-kirmani:101","bookId":"mutash-kirmani","type":"section","surah":6,"num":101,"title":"سورة الأنعام","page":"ج1 ص107","text":"قوله {وما الحياة الدنيا إلا لعب ولهو} قدم اللعب على اللهو في هذه السورة في موضعين وكذلك في سورتي القتال 36 والحديد 20 وقدم اللهو على اللعب في الأعراف والعنكبوت وإنما قدم اللعب في الأكثر لأن اللعب زمانه الصبا واللهو زمانه الشباب وزمان الصبا مقدم على زمان الشباب يبينه ما ذكر في الحديد {اعلموا أنما الحياة الدنيا لعب} كلعب الصبيان ولهو كلهو الشبان وزينة كزينة النسوان وتفاخر كتفاخر الإخوان وتكاثر كتكاثر السلطان وقريب من هذا في تقديم لفظ اللعب على اللهو قوله تعالى {وما بينهما لاعبين} {لو أردنا أن نتخذ لهوا لاتخذناه من لدنا} وقدم اللهو في الأعراف لأن ذلك في القيامة فذكر على ترتيب ما انقضى وبدأ بما به الإنسان انتهى من الحالتين وأما العنكبوت فالمراد بذكرها زمان الدنيا وأنه سريع الانقضاء قليل البقاء {وإن الدار الآخرة لهي الحيوان}"},{"id":"mutash-kirmani:102","bookId":"mutash-kirmani","type":"section","surah":6,"num":102,"title":"سورة الأنعام","page":"ج1 ص107","text":"أي الحياة التي لا أمد لها ولا نهاية لأبدها بدأ بذكر اللهو لأنه في زمان الشباب وهو أكثر من زمان اللعب وهو زمان الصبا"},{"id":"mutash-kirmani:103","bookId":"mutash-kirmani","type":"section","surah":6,"num":103,"title":"سورة الأنعام","page":"ج1 ص108","text":"قوله {أرأيتكم إن أتاكم عذاب الله أو أتتكم الساعة} ثم قال {قل أرأيتكم إن أتاكم عذاب الله بغتة} وليس لهما ثالث وقال فيما بينهما {قل أرأيتم} وكذلك في غيرها وليس لهذه الجملة في العربية نظير لأنه جمع بين علامتي خطاب وهما التاء والكاف والتاء اسم بالإجماع والكاف حرف عند البصريين يفيد الخطاب فحسب والجمع بينهما يدل على أن ذلك تنبيه على شيء ما عليه من مزيد وهو ذكر الاستئصال بالهلاك وليس فيما سواهما ما يدل على ذلك فاكتفى بخطاب واحد والعلم عند الله"},{"id":"mutash-kirmani:104","bookId":"mutash-kirmani","type":"section","surah":6,"num":104,"title":"سورة الأنعام","page":"ج1 ص108","text":"قوله {لعلهم يتضرعون} في هذه السورة وفي الأعراف {يضرعون} بالإدغام لأن ههنا وافق ما بعده وهو قوله {جاءهم بأسنا تضرعوا} ومستقبل تضرعوا يتضرعون لا غير"},{"id":"mutash-kirmani:105","bookId":"mutash-kirmani","type":"section","surah":6,"num":105,"title":"سورة الأنعام","page":"ج1 ص108","text":"قوله {انظر كيف نصرف الآيات} مكرر لأن التقدير انظر كيف نصرف الآيات ثم هم يصدفون عنها فلا تعرض عنهم بل تكررها لهم لعلهم يفقهون"},{"id":"mutash-kirmani:106","bookId":"mutash-kirmani","type":"section","surah":6,"num":106,"title":"سورة الأنعام","page":"ج1 ص109","text":"قوله {قل لا أقول لكم عندي خزائن الله ولا أعلم الغيب ولا أقول لكم إني ملك} فكرر لكم وقال في هود {ولا أقول إني ملك} فلم يكرر لكم لأن في هود تقدم {إني لكم نذير} وعقبه {وما نرى لكم} وبعده {أن أنصح لكم} فلما تكرر لكم في القصة أربع مرات اكتفى بذلك"},{"id":"mutash-kirmani:107","bookId":"mutash-kirmani","type":"section","surah":6,"num":107,"title":"سورة الأنعام","page":"ج1 ص109","text":"قوله {إن هو إلا ذكرى للعالمين} في هذه السورة وفي سورة يوسف عليه السلام {إن هو إلا ذكر للعالمين} منون لأن في هذه السورة تقدم {بعد الذكرى} {ولكن ذكرى} فكان الذكرى أليق بها"},{"id":"mutash-kirmani:108","bookId":"mutash-kirmani","type":"section","surah":6,"num":108,"title":"سورة الأنعام","page":"ج1 ص110","text":"قوله {إن الله فالق الحب والنوى يخرج الحي من الميت ومخرج الميت من الحي} في هذه السورة وفي آل عمران {وتخرج الحي من الميت وتخرج الميت من الحي} وكذلك في الروم 19 ويونس 31 {يخرج الحي من الميت ويخرج الميت من الحي} لأن ما في هذه السورة وقعت بين أسماء الفاعلين وهو {فالق الحب والنوى} {فالق الإصباح وجعل الليل سكنا} واسم الفاعل يشبه الاسم من وجه فيدخله الألف واللام والتنوين والجر وغير ذلك ويشبه الفعل من وجه فيعمل عمل الفعل ولا يثنى ولا يجمع إذا عمل وغير ذلك ولهذا جاز العطف عليه بالفعل نحو قوله {إن المصدقين والمصدقات وأقرضوا الله قرضا حسنا} وجاز عطفه على الفعل نحو قوله {سواء عليكم أدعوتموهم أم أنتم صامتون} فلما وقع بينهما ذكر {يخرج الحي من الميت} لفظ الفعل { ومخرج الميت من الحي} بلفظ الاسم عملا بالشبهين وأخر لفظ الاسم لأن الواقع بعده اسمان والمتقدم اسم واحد بخلاف ما في آل عمران لأن ما قبله وما بعده أفعال فتأمل فيه فإنه من معجزات القرآن"},{"id":"mutash-kirmani:109","bookId":"mutash-kirmani","type":"section","surah":6,"num":109,"title":"سورة الأنعام","page":"ج1 ص110","text":"قوله {قد فصلنا الآيات لقوم يعلمون} ثم قال {قد فصلنا الآيات لقوم يفقهون} وقال بعدهما {إن في ذلك لآيات لقوم يؤمنون}"},{"id":"mutash-kirmani:110","bookId":"mutash-kirmani","type":"section","surah":6,"num":110,"title":"سورة الأنعام","page":"ج1 ص110","text":"لأن من أحاط علما بما في الآية الأولى صار عالما لأنه أشرف العلوم فختم الآية بقوله {يعلمون} والآية الثانية مشتملة على ما يستدعي تأملا وتدبرا والفقه علم يحصل بالتدبر والتأمل والتفكر ولهذا لا يوصف به الله سبحانه وتعالى فختم الآية بقوله {يفقهون} ومن أقر بما في الآية الثالثة صار مؤمنا حقا فختم الآية بقوله {يؤمنون} حكاه أبو مسلم عن الخطيب وقوله {إن في ذلكم لآيات} في هذه السورة بحضور الجماعات وظهور الآيات عم الخطاب وجمع الآيات"},{"id":"mutash-kirmani:111","bookId":"mutash-kirmani","type":"section","surah":6,"num":111,"title":"سورة الأنعام","page":"ج1 ص111","text":"قوله {أنشأكم} وفي غيرها {خلقكم} و4 1 و6 2 و7 189 الخ لموافقة ما قبلها وهو {وأنشأنا من بعدهم} وما بعدها {وهو الذي أنشأ جنات معروشات}"},{"id":"mutash-kirmani:112","bookId":"mutash-kirmani","type":"section","surah":6,"num":112,"title":"سورة الأنعام","page":"ج1 ص111","text":"قوله {مشتبها وغير متشابه} وفي الآية الأخرى {متشابها وغير متشابه} لأن أكثر ما جاء في القرآن من هاتين الكلمتين جاء بلفظ التشابه نحو قوله {وأتوا به متشابها} {إن البقر تشابه علينا} {تشابهت قلوبهم} {وأخر متشابهات} فجاء قوله {مشتبها وغير متشابه} في الآية الأولى و {متشابها وغير متشابه} في الآية الأخرى على تلك القاعدة ثم كان لقوله تشابه معنيان أحدهما التبس والثاني تساوى وما في البقرة معناه التبس فحسب فبين بقوله {متشابها} ومعناه ملتبسا لأن ما بعده من باب التساوي والله أعلم"},{"id":"mutash-kirmani:113","bookId":"mutash-kirmani","type":"section","surah":6,"num":113,"title":"سورة الأنعام","page":"ج1 ص112","text":"قوله {ذلكم الله ربكم لا إله إلا هو خالق كل شيء} في هذه السورة وفي المؤمن {خالق كل شيء لا إله إلا هو} لأن فيها قبله ذكر الشركاء والبنين والبنات فدفع قول قائله بقوله {لا إله إلا هو} ثم قال {خالق كل شيء} وفي المؤمن قبله ذكرالخلق وهو {لخلق السماوات والأرض أكبر من خلق الناس} فخرج الكلام على إثبات خلق الناس لا على نفي الشريك فقدم في كل سورة ما يقتضيه ما قبله من الآيات"},{"id":"mutash-kirmani:114","bookId":"mutash-kirmani","type":"section","surah":6,"num":114,"title":"سورة الأنعام","page":"ج1 ص112","text":"قوله {ولو شاء ربك ما فعلوه فذرهم وما يفترون} وقال في الآية الأخرى من هذه السورة {ولو شاء الله ما فعلوه فذرهم وما يفترون} لأن قوله {ولو شاء ربك} وقع عقيب آيات فيها ذكر الرب مرات ومنها {جاءكم بصائر من ربكم} فختم بذكر الرب ليوافق آخرها أولها وقوله {ولو شاء الله ما فعلوه} وقع بعد قوله {وجعلوا لله مما ذرأ} فختم بما بدأ فيه"},{"id":"mutash-kirmani:115","bookId":"mutash-kirmani","type":"section","surah":6,"num":115,"title":"سورة الأنعام","page":"ج1 ص112","text":"قوله {إن ربك هو أعلم من يضل عن سبيله} وفي {ن والقلم} {إن ربك هو أعلم بمن ضل عن سبيله} بزيادة الباء ولفظ الماضي لأن إثبات الباء هو الأصل كما في {ن والقلم} وغيرها من السور لأن المعنى لا يعمل في المفعول به فنوى الباء وحيث حذفت أضمر فعل يعمل فيما بعده وخصت هذه السورة بالحذف موافقة لقوله {الله أعلم حيث يجعل رسالته} وعدل هنا إلى لفظ المستقبل لأن الباء لما حذفت التبس اللفظ بالإضافة تعالى الله عن ذلك فنبه بلفظ المستقبل على قطع الإضافة لأن أكثر ما يستعمل لفظ أفعل من يستعمله مع الماضي نحو أعلم من دب ودرج وأحسن من قام وقعد وأفضل من حج واعتمر فتنبه فإنه من أسرار القرآن لأنه لو قال أعلم من ضل بدون الياء مع الماضي لكان المعنى أعلم الضالين"},{"id":"mutash-kirmani:116","bookId":"mutash-kirmani","type":"section","surah":6,"num":116,"title":"سورة الأنعام","page":"ج1 ص113","text":"قوله {اعملوا على مكانتكم إني عامل فسوف تعلمون} بالفاء حيث وقع وفي هود {سوف تعلمون} بغير فاء لأنه تقدم في هذه السورة وغيرها {قل} فأمرهم أمر وعيد بقوله {اعملوا} أي اعملوا فستجزون ولم يكن في هود {قل} فصار استئنافا وقيل سوف تعلمون في سورة هود صفة لعامل أي إني عامل سوف تعلمون فحذف الفاء"},{"id":"mutash-kirmani:117","bookId":"mutash-kirmani","type":"section","surah":6,"num":117,"title":"سورة الأنعام","page":"ج1 ص113","text":"قوله {سيقول الذين أشركوا لو شاء الله ما أشركنا ولا آباؤنا ولا حرمنا من شيء} وقال في النحل {وقال الذين أشركوا لو شاء الله ما عبدنا من دونه من شيء نحن ولا آباؤنا ولا حرمنا من دونه من شيء} فزاد من {دونه} مرتين وزاد {نحن} لأن لفظ الإشراك يدل على إثبات شريك لا يجوز إثباته ودل على تحريم أشياء وتحليل أشياء من دون الله فلم يحتج إلى لفظ {من دونه} بخلاف لفظ العبادة فإنها غير مستنكرة وإنما المستنكر عبادة شيء مع الله سبحانه وتعالى ولا يدل على تحريم شيء كما يدل عليه أشرك فلم يكن لله هنا من يعتبره بقوله {من دونه} ولما حذف {من دونه} مرتين حذف معه {نحن} لتطرد الآية في حكم التخفيف"},{"id":"mutash-kirmani:118","bookId":"mutash-kirmani","type":"section","surah":6,"num":118,"title":"سورة الأنعام","page":"ج1 ص113","text":"قوله {نحن نرزقكم وإياهم} وقال في سبحان {نحن نرزقهم وإياكم} على الضد لأن التقدير من إملاق بكم نحن نرزقكم وإياهم وفي سبحان خشية إملاق يقع بهم نحن نرزقهم وإياكم"},{"id":"mutash-kirmani:119","bookId":"mutash-kirmani","type":"section","surah":6,"num":119,"title":"سورة الأنعام","page":"ج1 ص114","text":"قوله {ذلكم وصاكم به لعلكم تعقلون} وفي الثانية {لعلكم تذكرون} وفي الثالثة {لعلكم تتقون} لأن الآية الأولى مشتملة على خمسة أشياء كلها عظام جسام فكانت الوصية بها من أبلغ الوصايا فختم الآية الأولى بما في الإنسان من أشرف السجايا وهو العقل الذي امتاز به الإنسان عن سائر الحيوان والآية الثانية مشتملة على خمسة أشياء يقبح تعاطي ضدها وارتكابها وكانت الوصية بها تجري مجرى الزجر والوعظ فختم الآية بقوله {تذكرون} أي تتعظون بمواعظ الله والآية الثالثة مشتملة على ذكر الصراط المستقيم والتحريض على اتباعه واجتناب مناهيه فختم الآية بالتقوى التي هي ملاك العمل وخير الزاد"},{"id":"mutash-kirmani:120","bookId":"mutash-kirmani","type":"section","surah":6,"num":120,"title":"سورة الأنعام","page":"ج1 ص114","text":"قوله {جعلكم خلائف الأرض} في هذه السورة وفي يونس والملائكة {جعلكم خلائف في الأرض} لأن في هذا العشر تكرر ذكر المخاطبين كرات فعرفهم بالإضافة وقد جاء في السورتين على الأصل وهو {جاعل في الأرض خليفة} {جعلكم مستخلفين}"},{"id":"mutash-kirmani:121","bookId":"mutash-kirmani","type":"section","surah":6,"num":121,"title":"سورة الأنعام","page":"ج1 ص115","text":"قوله {إن ربك سريع العقاب وإنه لغفور رحيم} وقال في الأعراف {إن ربك لسريع العقاب وإنه لغفور رحيم} لأن ما في هذه السورة وقع بعد قوله {من جاء بالحسنة فله عشر أمثالها} وقوله {وهو الذي جعلكم خلائف الأرض} فقيد قوله {غفور رحيم} باللام ترجيحا للغفران على العقاب ووقع ما في الأعراف بعد قوله {وأخذنا الذين ظلموا بعذاب بئيس} وقوله {كونوا قردة خاسئين} فقيد رحمة منه للعباد لئلا يرجح جانب الخوف على الرجاء وقدم سريع العقاب في الآيتين مراعاة لفواصل الآي"},{"id":"mutash-kirmani:122","bookId":"mutash-kirmani","type":"section","surah":7,"num":122,"title":"سورة الأعراف","page":"ج1 ص115","text":"قوله {قال ما منعك} في هذه السورة وفي ص {قال يا إبليس ما منعك} وفي الحجر {قال يا إبليس ما لك} بزيادة {يا إبليس} في السورتين لأن خطابه قرب من ذكره في هذه السورة وهو قوله {إلا إبليس لم يكن من الساجدين} {قال ما منعك} فحسن حذف حرف النداء والمنادى ولم يقرب في ص قربه منه في هذه السورة لأن في ص {إلا إبليس استكبر وكان من الكافرين} بزيادة {استكبر} فزاد حرف النداء والمنادى فقال {يا إبليس} وكذلك في الحجر فإن فيها {إلا إبليس أبى أن يكون مع الساجدين}"},{"id":"mutash-kirmani:123","bookId":"mutash-kirmani","type":"section","surah":7,"num":123,"title":"سورة الأعراف","page":"ج1 ص115","text":"بزيادة أبى فزاد حرف النداء والمنادى فقال {يا إبليس ما لك}"},{"id":"mutash-kirmani:124","bookId":"mutash-kirmani","type":"section","surah":7,"num":124,"title":"سورة الأعراف","page":"ج1 ص116","text":"قوله {ألا تسجد} وفي ص {أن تسجد} وفي الحجر {ما لك ألا تكون} فزاد في هذه السورة {لا} وللمفسرين في {لا} أقوال قال بعضهم {لا} صلة كما في قوله {لئلا يعلم} وقال بعضهم الممنوع من الشيء مضطر إلى ما منع وقال بعضهم معناه ما الذي جعلك في منعة من عذابي وقال بعضهم معناه من قال لك ألا تسجد وقد ذكرت ذلك وأخبرت بالصواب في كتابي (لباب التفسير) والذي يليق بهذا الكتاب أن نذكر ما السبب الذي خص هذه السورة بزيادة {لا} دون السورتين قلت لما حذف منها {يا إبليس} واقتصر على الخطاب جمع بين لفظ المنع ولفظ {لا} زيادة في النفي وإعلاما أن المخاطب به إبليس خلافا للسورتين فإنه صرح فيهما باسمه وإن شئت قلت جمع في هذه السورة بين ما في ص وما في الحجر فقال ما منعك أن تسجد مالك ألا تسجد فحذف {أن تسجد} وحذف {مالك} لدلالة الحال ودلالة السورتين عليه فبقي {ما منعك ألا تسجد} وهذه لطيفة فاحفظها"},{"id":"mutash-kirmani:125","bookId":"mutash-kirmani","type":"section","surah":7,"num":125,"title":"سورة الأعراف","page":"ج1 ص117","text":"قوله {أنظرني إلى يوم يبعثون} وفي الحجر وص {رب فأنظرني} لأنه سبحانه لما اقتصر في السؤال على الخطاب دون صريح الاسم في هذه السورة اقتصر في الجواب أيضا على الخطاب دون ذكر المنادى وأما زيادة الفاء في السورتين دون هذه السورة فلأن داعية الفاء ما تضمنه النداء من أدعو أو أنادى نحو {ربنا فاغفر لنا} أي أدعوك وكذلك داعية الواو في قوله {ربنا وآتنا} فحذف المنادى في هذه السورة فلما حذفه انحذفت الفاء"},{"id":"mutash-kirmani:126","bookId":"mutash-kirmani","type":"section","surah":7,"num":126,"title":"سورة الأعراف","page":"ج1 ص117","text":"قوله {إنك من المنظرين} في هذه السورة وفي السورتين {قال فإنك} لأن الجواب يبنى على السؤال ولما خلا في هذه السورة عن الفاء خلا الجواب عنه ولما ثبتت الفاء في السؤال في السورتين ثبتت في الجواب والجواب في السور الثلاث إجابة وليس باستجابة"},{"id":"mutash-kirmani:127","bookId":"mutash-kirmani","type":"section","surah":7,"num":127,"title":"سورة الأعراف","page":"ج1 ص118","text":"قوله {فبما أغويتني} في هذه السورة وفي ص {فبعزتك لأغوينهم} وفي الحجر {رب بما أغويتني} لأن ما في هذه السورة موافق لما قبله في الاقتصار على الخطاب دون النداء وما في الحجر موافق لما قبله في مطابقة النداء وزاد في هذه السورة الفاء التي هي للعطف ليكون الثاني مربوطا بالأول ولم تدخل في الحجر فاكتفى بمطابقة النداء لامتناع النداء منه لأنه ليس بالذي يستدعيه النداء فإن ذلك يقع مع السؤال والطلب وهذا قسم عند أكثرهم بدليل ما في ص وخبر عند بعضهم والذي في ص على قياس ما في الأعراف دون الحجر لأن موافقتهما أكثر على ما سبق فقال {فبعزتك} والله أعلم وهذا الفصل في هذه السورة برهان لامع وسأل الخطيب نفسه عن هذه المسائل فأجاب عنها وقال إن اقتصاص ما مضى إذا لم يقصد به أداء الألفاظ بأعيانها كان اختلافها واتفاقها سواء إذا أدى المعنى المقصود وهذا جواب حسن إن رضيت به كفيت مؤنة السهر إلى السحر"},{"id":"mutash-kirmani:128","bookId":"mutash-kirmani","type":"section","surah":7,"num":128,"title":"سورة الأعراف","page":"ج1 ص118","text":"قوله {قال اخرج منها مذؤوما مدحورا} ليس في القرآن غيره لأنه سبحانه لما بالغ في الحكاية عنه بقوله {لأقعدن لهم} الآية بالغ في ذمه فقال {اخرج منها مذؤوما مدحورا} والذأم أشد الذم"},{"id":"mutash-kirmani:129","bookId":"mutash-kirmani","type":"section","surah":7,"num":129,"title":"سورة الأعراف","page":"ج1 ص118","text":"قوله {ولكل أمة أجل فإذا جاء أجلهم} بالفاء حيث وقع إلا في يونس فإنه هنا جملة عطفت على جملة بينهما اتصال وتعقب فكان الموضع موضع الفاء وما في يونس يأتي في موضعه"},{"id":"mutash-kirmani:130","bookId":"mutash-kirmani","type":"section","surah":7,"num":130,"title":"سورة الأعراف","page":"ج1 ص118","text":"قوله {وهم بالآخرة كافرون} ما في هذه السورة جاء على القياس وتقديره وهم كافرون بالآخرة فقدم بالآخرة تصحيحا لفواصل الآي وفي هود لما تقدم {هؤلاء الذين كذبوا على ربهم} ثم قال {ألا لعنة الله على الظالمين} ولم يقل عليهم والقياس ذلك ولو قال لالتبس أنهم هم أم غيرهم فكرر وقال {وهم بالآخرة هم كافرون} ليعلم أنهم هم المذكورون لا غيرهم وليس {هم} ههنا للتوكيد كما زعم بعضهم لأن ذلك يزاد مع الألف واللام ملفوظا أو مقدرا"},{"id":"mutash-kirmani:131","bookId":"mutash-kirmani","type":"section","surah":7,"num":131,"title":"سورة الأعراف","page":"ج1 ص119","text":"قوله {وهو الذي يرسل الرياح} في هذه السورة وفي الروم بلفظ المستقبل وفي الفرقان وفاطر بلفظ الماضي لأن ما قبلها في هذه السورة ذكر الخوف والطمع وهو قوله {وادعوه خوفا وطمعا} وهما يكونان في المستقبل لا غير فكان {يرسل} بلفظ المستقبل أشبه بما قبله وفي الروم قبله {ومن آياته أن يرسل الرياح مبشرات وليذيقكم من رحمته ولتجري الفلك بأمره} فجاء بلفظ المستقبل لفقا لما قبله وأما في الفرقان فإن قبله {كيف مد الظل} الآية وبعد الآية {وهو الذي جعل لكم} و {مرج} و {خلق} فكان الماضي أليق به وفي فاطر مبني على أول السورة {الحمد لله فاطر السماوات والأرض جاعل الملائكة رسلا أولي أجنحة} وهما بمعنى الماضي لا غير فبنى على ذلك فقال {أرسل} بلفظ الماضي ليكون الكل على مقتضى اللفظ الذي خص به"},{"id":"mutash-kirmani:132","bookId":"mutash-kirmani","type":"section","surah":7,"num":132,"title":"سورة الأعراف","page":"ج1 ص120","text":"قوله {لقد أرسلنا نوحا} في هذه السورة بغير واو وفي هود 25 والمؤمنين 23 ولقد بالواو لأنه لم يتقدم في هذه السورة ذكر رسول فيكون هذا عطفا عليه بل هو استئناف كلام وفي هود تقدم ذكر الرسول مرات وفي المؤمنين تقدم ذكر نوح ضمنا في قوله {وعلى الفلك} لأنه أول من صنع الفلك فعطف في السورتين بالواو"},{"id":"mutash-kirmani:133","bookId":"mutash-kirmani","type":"section","surah":7,"num":133,"title":"سورة الأعراف","page":"ج1 ص120","text":"قوله {أرسلنا نوحا إلى قومه فقال} بالفاء في هذه السورة وكذلك في المؤمنين في قصة نوح {فقال} وفي هود في قصة نوح {إني لكم} بغير {قال} وفي هذه السورة في قصة عاد بغير فاء لأن إثبات الفاء هو الأصل وتقديره أرسلنا نوحا فجاء فقال فكان في هذه السورة والمؤمنين على ما يوجبه اللفظ وأما في هود فالتقدير فقال إني فأضمر قال وأضمر معه الفاء وهذا كما قلنا في قوله تعالى {فأما الذين اسودت وجوههم أكفرتم} أي فيقال لهم أكفرتم فأضمر الفاء والقول معا وأما قصة عاد فالتقدير وأرسلنا إلى عاد أخاهم هودا فقال فأضمر {أرسلنا} وأضمر الفاء لأن داعي الفاء أرسلنا"},{"id":"mutash-kirmani:134","bookId":"mutash-kirmani","type":"section","surah":7,"num":134,"title":"سورة الأعراف","page":"ج1 ص120","text":"قوله {قال الملأ} بغير فاء في قصة نوح وهود في هذه السورة وفي سورة هود والمؤمنين فقال بالفاء لأن ما في هذه السورة في السورتين لا يليق بالجواب وهو قولهم لنوح {إنا لنراك في ضلال مبين} وقولهم لهود {إنا لنراك في سفاهة وإنا لنظنك من الكاذبين} بخلاف السورتين فإنهم أجابوا فيهما بما زعموا أنه جواب"},{"id":"mutash-kirmani:135","bookId":"mutash-kirmani","type":"section","surah":7,"num":135,"title":"سورة الأعراف","page":"ج1 ص121","text":"قوله {أبلغكم رسالات ربي وأنصح لكم} في قصة نوح وقال في قصة هود {وأنا لكم ناصح أمين} لأن ما في هذه الآية {أبلغكم} بلفظ المستقبل فعطف عليه {أنصح لكم} كما في الآية الأخرى {لقد أبلغتكم رسالات ربي ونصحت لكم} فعطف الماضي لكن في قصة هود قابل باسم الفاعل على قولهم له {وإنا لنظنك من الكاذبين} ليقابل الاسم بالاسم"},{"id":"mutash-kirmani:136","bookId":"mutash-kirmani","type":"section","surah":7,"num":136,"title":"سورة الأعراف","page":"ج1 ص121","text":"قوله {أبلغكم} في قصة نوح وهود بلفظ المستقبل وفي قصة صالح وشعيب {أبلغتكم} بلفظ الماضي لأن في قصة نوح وهود وقع في ابتداء الرسالة وفي قصة صالح وشعيب وقع في آخر الرسالة ودنو العذاب ألا تسمع قوله {فتولى عنهم} في القصتين"},{"id":"mutash-kirmani:137","bookId":"mutash-kirmani","type":"section","surah":7,"num":137,"title":"سورة الأعراف","page":"ج1 ص121","text":"قوله {رسالات ربي} في جميع القصص إلا في قصة صالح فإن فيها {رسالة} على الواحدة لأنه سبحانه حكى عنهم بعد الإيمان بالله والتقوى أشياء أمروا قومهم بها إلا في قصة صالح فإن فيها ذكر الناقة فصار كأنها رسالة واحدة وقوله {برسالاتي وبكلامي} مختلف فيها"},{"id":"mutash-kirmani:138","bookId":"mutash-kirmani","type":"section","surah":7,"num":138,"title":"سورة الأعراف","page":"ج1 ص122","text":"قوله {فكذبوه فأنجيناه والذين معه في الفلك وأغرقنا الذين كذبوا بآياتنا} وفي يونس {فكذبوه فنجيناه ومن معه في الفلك} لأن أنجينا ونجينا للتعدي لكن التشديد يدل على الكثرة والمبالغة فكان في يونس {ومن معه} ولفظ {من} يقع على كثرة مما يقع عليه {الذين} لأن من يصلح للواحد والتثنية والجمع والمذكر والمؤنث بخلاف الذين فإنه لجمع المذكر فحسب فكان التشديد مع من أليق"},{"id":"mutash-kirmani:139","bookId":"mutash-kirmani","type":"section","surah":7,"num":139,"title":"سورة الأعراف","page":"ج1 ص122","text":"قوله في هذه السورة {ولا تمسوها بسوء فيأخذكم عذاب أليم} وفي هود {ولا تمسوها بسوء فيأخذكم عذاب قريب} وفي الشعراء {ولا تمسوها بسوء فيأخذكم عذاب يوم عظيم} لأنه في هذه السورة بالغ في الوعظ فبالغ في الوعيد فقال {عذاب أليم} وفي هود لما اتصل بقوله {تمتعوا في داركم ثلاثة أيام} وصفه بالقرب فقال {عذاب قريب} وزاد في الشعراء ذكر اليوم لأن قبله {لها شرب ولكم شرب يوم معلوم} فالتقدير لها شرب يوم معلوم فختم الآية بذكر اليوم فقال {عذاب يوم عظيم}"},{"id":"mutash-kirmani:140","bookId":"mutash-kirmani","type":"section","surah":7,"num":140,"title":"سورة الأعراف","page":"ج1 ص122","text":"قوله {فأخذتهم الرجفة فأصبحوا في دارهم جاثمين} على الوحدة وقال {وأخذت الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين} حيث ذكر الرجفة وهي الزلزلة وحد الدار وحيث ذكر الصيحة جمع لأن الصيحة كانت من السماء فبلوغها أكثر وأبلغ من الزلزلة فاتصل كل واحد بما هو لائق به"},{"id":"mutash-kirmani:141","bookId":"mutash-kirmani","type":"section","surah":7,"num":141,"title":"سورة الأعراف","page":"ج1 ص122","text":"قوله {ما نزل الله بها من سلطان} في هذه السورة {نزل} وفي غيرها {أنزل} لأن أفعل كما ذكرت آنفا للتعدي وفعل للتعدي والتكثير فذكر في الموضع الأول بلفظ المبالغة ليجري مجري ذكر الجملة والتفصيل وذكر الجنس والنوع فيكون الأول كالجنس وما سواه كالنوع"},{"id":"mutash-kirmani:142","bookId":"mutash-kirmani","type":"section","surah":7,"num":142,"title":"سورة الأعراف","page":"ج1 ص123","text":"قوله {وتنحتون الجبال بيوتا} في هذه السورة وفي غيرها {من الجبال} لأن في هذه السورة تقدمه {من سهولها قصورا} فاكتفى بذلك"},{"id":"mutash-kirmani:143","bookId":"mutash-kirmani","type":"section","surah":7,"num":143,"title":"سورة الأعراف","page":"ج1 ص123","text":"قوله {وأمطرنا عليهم مطرا فانظر كيف كان عاقبة المجرمين} في هذه السورة وفي غيرها {فساء مطر المنذرين} لأن في هذه السورة وافق ما بعده وهو قوله {فانظر كيف كان عاقبة المفسدين}"},{"id":"mutash-kirmani:144","bookId":"mutash-kirmani","type":"section","surah":7,"num":144,"title":"سورة الأعراف","page":"ج1 ص123","text":"قوله {ولوطا إذ قال لقومه أتأتون الفاحشة} بالاستفهام وهو استفهام تقريع وتوبيخ وإنكار وقال بعده {إنكم لتأتون الرجال} فزاد مع الاستفهام {إن} لأن التقريع والتوبيخ والإنكار في الثاني أكثر ومثله في النمل {أتأتون} وبعده {أئنكم لتأتون الرجال}"},{"id":"mutash-kirmani:145","bookId":"mutash-kirmani","type":"section","surah":7,"num":145,"title":"سورة الأعراف","page":"ج1 ص123","text":"فجمع بين إن وأئن وذلك لموافقة آخر القصة فإن في الآخر {إنا منجوك} {إنا منزلون} فتأمل فيه فإنه صعب المستخرج"},{"id":"mutash-kirmani:146","bookId":"mutash-kirmani","type":"section","surah":7,"num":146,"title":"سورة الأعراف","page":"ج1 ص124","text":"قوله {بل أنتم قوم مسرفون} في هذه السورة بلفظ الاسم وفي النمل {قوم تجهلون} بلفظ الفعل لأن كل إسراف جهل وكل جهل إسراف ثم ختم الآية بلفظ الاسم موافقة لرءوس الآيات التي تقدمت وكلها أسماء {العالمين} {الناصحين} {جاثمين} {المرسلين} {كافرون} {مؤمنون} {مفسدين} وفي النمل وافق ما قبلها من الآيات وكلها أفعال {يبصرون} {يتقون} {تعلمون}"},{"id":"mutash-kirmani:147","bookId":"mutash-kirmani","type":"section","surah":7,"num":147,"title":"سورة الأعراف","page":"ج1 ص124","text":"قوله {وما كان جواب قومه} بالواو في هذه السورة وفي غيرها {فما} بالفاء لأن ما قبله اسم والفاء للتعقيب والتعقيب يكون مع الأفعال فقال في النمل {تجهلون} {فما كان} وكذلك في العنكبوت في هذه القصة {وتأتون في ناديكم المنكر فما كان} وفي هذه السورة {مسرفون} {وما كان} وفي هذه السورة {أخرجوهم} وفي النمل {أخرجوا آل لوط} لأن ما في هذه السورة كناية فسرها في السورة التي بعدها وفي النمل قال الخطيب سورة النمل نزلت قبل هذه السورة فصرح في الأولى وكنى في الثانية"},{"id":"mutash-kirmani:148","bookId":"mutash-kirmani","type":"section","surah":7,"num":148,"title":"سورة الأعراف","page":"ج1 ص124","text":"قوله {كانت من الغابرين} في هذه السورة وفي النمل {قدرناها من الغابرين} أي كانت في علم الله من الغابرين فقدرناها من الغابرين وعلى وزن قول الخطيب قدرناها من الغابرين فصارت من الغابرين وكان بمعنى صار وقد فسر {كان من الجن} بالوجهين"},{"id":"mutash-kirmani:149","bookId":"mutash-kirmani","type":"section","surah":7,"num":149,"title":"سورة الأعراف","page":"ج1 ص125","text":"قوله {بما كذبوا من قبل} في هذه السورة وفي يونس {بما كذبوا به} لأن أول القصة في هذه السورة {ولو أن أهل القرى آمنوا} وفي الآية {ولكن كذبوا فأخذناهم} وليس بعدها الباء فختم القصة بمثل ما بدأ به وكذلك في يونس وافق ما قبله {فكذبوه فنجيناه} {كذبوا بآياتنا} فختم بمثل ذلك فقال {بما كذبوا به} وذهب بعض أهل العلم إلى أن ما في حق العقلاء من التكذيب فبغير الباء نحو قوله {فكذبوا رسلي} و {كذبوه} وغيره وما في حق غيرهم ب باء نحو {كذبوا بآياتنا} وغيرها وعند المحققين تقديره فكذبوا رسلنا برد آياتنا حيث وقع"},{"id":"mutash-kirmani:150","bookId":"mutash-kirmani","type":"section","surah":7,"num":150,"title":"سورة الأعراف","page":"ج1 ص125","text":"قوله {كذلك يطبع الله} ههنا وفي يونس {نطبع} بالنون لأن في هذه السورة قدم ذكر الله سبحانه بالصريح والكناية فجمع بينهما فقال {ونطبع على قلوبهم} بالنون وختم الآية بالصريح فقال {كذلك يطبع الله} وأما في يونس فمبني على ما قبله من قوله {فنجيناه} وجعلناهم 73 ثم بعثنا 74 بلفظ الجمع فختم بمثله فقال {كذلك نطبع على قلوب المعتدين}"},{"id":"mutash-kirmani:151","bookId":"mutash-kirmani","type":"section","surah":7,"num":151,"title":"سورة الأعراف","page":"ج1 ص126","text":"قوله {قال الملأ من قوم فرعون إن هذا لساحر عليم} وفي الشعراء {قال للملإ حوله} لأن التقدير في هذه الآية قال الملأ من قوم فرعون وفرعون بعض لبعض فحذف فرعون لاشتمال الملأ من آل فرعون على اسمه كما قال {وأغرقنا آل فرعون} أي آل فرعون وفرعون فحذف فرعون لأن آل فرعون اشتمل على اسمه فالقائل هو فرعون وحده بدليل الجواب وهو {قالوا أرجه وأخاه} بلفظ التوحيد والملأ هم المقول لهم إذ ليس في الآية مخاطبون بقوله {يخرجكم من أرضكم} غيرهم فتأمل فيه فإنه برهان للقرآن شاف"},{"id":"mutash-kirmani:152","bookId":"mutash-kirmani","type":"section","surah":7,"num":152,"title":"سورة الأعراف","page":"ج1 ص126","text":"قوله {يريد أن يخرجكم من أرضكم فماذا تأمرون} وفي الشعراء {من أرضكم بسحره} لأن الآية الأولى في هذه السورة بنيت على الاقتصار وكذلك الآية الثانية ولأن لفظ الساحر يدل على السحر"},{"id":"mutash-kirmani:153","bookId":"mutash-kirmani","type":"section","surah":7,"num":153,"title":"سورة الأعراف","page":"ج1 ص126","text":"قوله {وأرسل} وفي الشعراء {وابعث} لأن الإرسال يفيد معنى البعث ويتضمن نوعا من العلو لأنه يكون من فوق فخصت هذه السورة به لما التبس ليعلم أن المخاطب به فرعون دون غيره"},{"id":"mutash-kirmani:154","bookId":"mutash-kirmani","type":"section","surah":7,"num":154,"title":"سورة الأعراف","page":"ج1 ص126","text":"قوله {بكل ساحر عليم} وفي الشعراء {بكل سحار} لأنه راعى ما قبله في هذه السورة وهو قوله {إن هذا لساحر عليم} وراعى في الشعراء الإمام فإنه فيه {بكل سحار} بالألف وقرئ في هذه السورة {سحار} أيضا طلبا للمبالغة وموافقة لما في الشعراء"},{"id":"mutash-kirmani:155","bookId":"mutash-kirmani","type":"section","surah":7,"num":155,"title":"سورة الأعراف","page":"ج1 ص126","text":"قوله {وجاء السحرة فرعون قالوا} وفي الشعراء {فلما جاء السحرة قالوا لفرعون} لأن القياس في هذه السورة فلما جاء السحرة فرعون قالوا أو فقالوا لا بد من ذلك لكن أضمر فيه {فلما} فحسن حذف الفاء وخص هذه السورة بإضمار فلما لأن ما في هذه السورة وقع على الاختصار والاقتصار على ما سبق وأما تقديم فرعون وتأخيره في الشعراء فلأن التقدير فيهما فلما جاء السحرة فرعون قالوا لفرعون فأظهر الأول في هذه السورة لأنها الأولى وأضمر الثاني في الشعراء لأنها الثانية"},{"id":"mutash-kirmani:156","bookId":"mutash-kirmani","type":"section","surah":7,"num":156,"title":"سورة الأعراف","page":"ج1 ص127","text":"قوله {قال نعم وإنكم لمن المقربين} وفي الشعراء {إذا لمن المقربين} لأن إذا في هذه السورة مضمرة مقدرة لأن إذا جزاء ومعناه إن غلبتم قربتكم ورفعت منزلتكم وخص هذه السورة بالإضمار اختصارا"},{"id":"mutash-kirmani:157","bookId":"mutash-kirmani","type":"section","surah":7,"num":157,"title":"سورة الأعراف","page":"ج1 ص127","text":"قوله {إما أن تلقي وإما أن نكون نحن الملقين} وفي طه {إما أن تلقي وإما أن نكون أول من ألقى} راعى في السورتين أو أخر الآي ومثله {فألقي السحرة ساجدين} في السورتين وفي طه {سجدا} وفي السورتين أيضا {آمنا برب العالمين} وليس في طه {رب العالمين} وفي السورتين {رب موسى وهارون} وفي هذه {فسوف تعلمون} {لأقطعن} وفي الشعراء {فلسوف تعلمون} {لأقطعن} وفي طه {فلأقطعن} وفي السورتين {لأصلبنكم أجمعين} وفي طه {ولأصلبنكم في جذوع النخل} وهذا كله مراعاة لفواصل الآي لأنها مرعية تنبنى عليها مسائل كثيرة"},{"id":"mutash-kirmani:158","bookId":"mutash-kirmani","type":"section","surah":7,"num":158,"title":"سورة الأعراف","page":"ج1 ص128","text":"قوله في هذه السورة {آمنتم به} وفي السورتين {آمنتم له} لأن الضمير هنا يعود إلى رب العالمين وهو المؤمن به سبحانه وفي السورتين يعود إلى موسى وهو المؤمن له لقوله {إنه لكبيركم} وقيل آمنتم به وآمنتم له واحد"},{"id":"mutash-kirmani:159","bookId":"mutash-kirmani","type":"section","surah":7,"num":159,"title":"سورة الأعراف","page":"ج1 ص128","text":"قوله {قال فرعون} وفي السورتين {قال آمنتم} لأن هذه السورة متعقبة على السورتين فصرح في الأولى وكنى في الأخريين وهو القياس قال الخطيب لأن في هذه السورة بعد عن ذكر فرعون بآيات فصرح وقرب في السورتين من ذكره فكنى"},{"id":"mutash-kirmani:160","bookId":"mutash-kirmani","type":"section","surah":7,"num":160,"title":"سورة الأعراف","page":"ج1 ص128","text":"قوله {ثم لأصلبنكم} وفي السورتين {ولأصلبنكم} لأن ثم تدل على أن الصلب يقع بعد التقطيع وإذا دل في الأولى علم في غيرها ولأن موضع الواو تصلح له ثم"},{"id":"mutash-kirmani:161","bookId":"mutash-kirmani","type":"section","surah":7,"num":161,"title":"سورة الأعراف","page":"ج1 ص128","text":"قوله {إنا إلى ربنا منقلبون} وفي الشعراء {لا ضير إنا إلى ربنا منقلبون} بزيادة {لا ضير} لأن هذه السورة اختصرت فيها هذه القصة وأشبعت في الشعراء وذكر فيها أول أحوال موسى مع فرعون إلى آخرها فبدأ بقوله {ألم نربك فينا وليدا} وختم بقوله {ثم أغرقنا الآخرين} فلهذا وقع فيها زوائد لم تقع في الأعراف وطه فتأمل وتدبر تعرف إعجاز القرآن"},{"id":"mutash-kirmani:162","bookId":"mutash-kirmani","type":"section","surah":7,"num":162,"title":"سورة الأعراف","page":"ج1 ص128","text":"قوله 6 {يسومونكم سوء العذاب يقتلون} بغير واو على البدل وقد سبق"},{"id":"mutash-kirmani:163","bookId":"mutash-kirmani","type":"section","surah":7,"num":163,"title":"سورة الأعراف","page":"ج1 ص129","text":"قوله {من يهد الله فهو المهتدي} بإثبات الياء على الأصل وفي غيرها بغير ياء على التخفيف"},{"id":"mutash-kirmani:164","bookId":"mutash-kirmani","type":"section","surah":7,"num":164,"title":"سورة الأعراف","page":"ج1 ص130","text":"قوله {قل لا أملك لنفسي نفعا ولا ضرا إلا ما شاء الله} في هذه السورة وفي يونس {قل لا أملك لنفسي ضرا ولا نفعا إلا ما شاء الله} لأن أكثر ما جاء في القرآن من لفظي الضر والنفع معا جاء بتقديم لفظ الضر على النفع لأن العابد يعبد معبوده خوفا من عقابه أولا ثم طمعا في ثوابه ثانيا يقويه قوله {يدعون ربهم خوفا وطمعا} وحيث تقدم النفع على الضر تقدم لسابقة لفظ تضمن نفعا وذلك في ثمانية مواضع ثلاثة منها بلفظ الاسم وهي ههنا والرعد وسبأ وخمسة بلفظ الفعل وهي في الأنعام {ينفعنا ولا يضرنا} وآخر في يونس {ما لا ينفعك ولا يضرك} وفي الأنبياء {ما لا ينفعكم شيئا ولا يضركم} والفرقان {ما لا ينفعهم ولا يضرهم} وفي الشعراء {ينفعونكم أو يضرون} أما في هذه السورة فقد تقدمه {من يهد الله فهو المهتدي ومن يضلل} فقدم الهداية على الضلالة وبعد ذلك {لاستكثرت من الخير وما مسني السوء} فقدم الخير على السوء فلذلك قدم النفع على الضر وفي الرعد {طوعا وكرها} فقدم الطوع وفي سبأ {يبسط الرزق لمن يشاء ويقدر} فقدم البسط وفي يونس قدم الضر على الأصل ولموافقة ما قبلها {ما لا يضرهم ولا ينفعهم} وفيها {وإذا مس الإنسان الضر} فيكون في الآية ثلاث مرات وكذلك ما جاء بلفظ الفعل فلسابقة معنى يتضمن فعلا أما سورة الأنعام ففيها {ليس لها من دون الله ولي ولا شفيع وإن تعدل كل عدل لا يؤخذ منها} ثم وصلها بقوله {قل أندعو من دون الله ما لا ينفعنا ولا يضرنا} وفي يونس تقدمه قوله {ثم ننجي رسلنا والذين آمنوا كذلك حقا علينا ننج المؤمنين} ثم قال {ولا تدع من دون الله ما لا ينفعك ولا يضرك} وفي الأنبياء تقدم قول الكفار لإبراهيم في المجادلة {لقد علمت ما هؤلاء ينطقون} {قال أفتعبدون من دون الله ما لا ينفعكم شيئا ولا يضركم} وفي الفرقان تقدمه قوله {ألم تر إلى ربك كيف مد الظل} وعد نعما جمة في الآيات ثم قال {ويعبدون من دون الله ما لا ينفعهم ولا يضرهم} فتأمل فإنه برهان القرآن"},{"id":"mutash-kirmani:165","bookId":"mutash-kirmani","type":"section","surah":7,"num":165,"title":"سورة الأعراف","page":"ج1 ص130","text":"قوله {وخيفة} ذكرت في المتشابه وليست منه لأنها من الخوف {وخفية} من قوله تعالى {تدعونه تضرعا وخفية} من خفي الشيء إذا استتر"},{"id":"mutash-kirmani:166","bookId":"mutash-kirmani","type":"section","surah":8,"num":166,"title":"سورة الأنفال","page":"ج1 ص131","text":"قوله {وما جعله الله إلا بشرى} وقوله {ومن يشاقق الله} وقوله {ويكون الدين كله لله} وقد سبق"},{"id":"mutash-kirmani:167","bookId":"mutash-kirmani","type":"section","surah":8,"num":167,"title":"سورة الأنفال","page":"ج1 ص131","text":"قوله {كدأب آل فرعون والذين من قبلهم كفروا بآيات الله} ثم قال بعد آية {كدأب آل فرعون والذين من قبلهم كذبوا بآيات ربهم} قال الخطيب قد أجاب فيها بعض أهل النظر بأن قال ذكر في الآية الأولى عقوبته إياهم عند الموت كما فعله بآل فرعون ومن قبلهم من الكفار وذكر في الثانية ما يفعل بهم بعد الموت كما فعله بآل فرعون ومن قبلهم فلم يكن تكرارا قال الخطيب والجواب عندي أن الأول إخبار عن عذاب لم يمكن الله أحدا من فعله وهو ضرب الملائكة وجوههم وأدبارهم عند نزع أرواحهم والثاني إخبار عن عذاب مكن الناس من فعل مثله وهو الإهلاك والإغراق قلت وله وجهان آخران محتملان أحدهما كدأب آل فرعون فيما فعلوا والثاني كدأب آل فرعون فيما فعل بهم فهم فاعلون على الأول ومفعولون في الثاني والوجه الآخر أن المراد بالأول كفرهم بالله وبالثاني تكذيبهم بالأنبياء لأن تقدير الآية كذبوا الرسل بردهم آيات الله وله وجه آخر وهو أن يجعل الضمير في {كفروا} لكفار قريش على تقدير كفروا بآيات الله كدأب آل فرعون وكذلك الثاني كذبوا بآيات ربهم كدأب آل فرعون"},{"id":"mutash-kirmani:168","bookId":"mutash-kirmani","type":"section","surah":8,"num":168,"title":"سورة الأنفال","page":"ج1 ص132","text":"قوله {الذين آمنوا وهاجروا وجاهدوا بأموالهم وأنفسهم في سبيل الله} في هذه السورة بتقديم {بأموالهم وأنفسهم} وفي براءة بتقديم {في سبيل الله} لأن في هذه السورة تقدم ذكر المال والفداء والغنيمة في قوله {تريدون عرض الدنيا} {لولا كتاب من الله سبق لمسكم فيما أخذتم} أي من الفداء {فكلوا مما غنمتم} فقدم ذكر المال وفي براءة تقدم ذكر الجهاد وهو قوله {ولما يعلم الله الذين جاهدوا منكم} وقوله {كمن آمن بالله واليوم الآخر وجاهد في سبيل الله} فقدم ذكر الجهاد في هذه الآي في هذه السورة ثلاث مرات فأورد في الأولى {بأموالهم وأنفسهم في سبيل الله} وحذف من الثانية {بأموالهم وأنفسهم} اكتفاء بما في الأولى وحذف من الثالثة {بأموالهم وأنفسهم} وزاد حذف {في سبيل الله} اكتفاء بما في الآيتين قبلها"},{"id":"mutash-kirmani:169","bookId":"mutash-kirmani","type":"section","surah":9,"num":169,"title":"سورة التوبة","page":"ج1 ص132","text":"قوله {واعلموا أنكم غير معجزي الله} ليس بتكرار لأن الأول للمكان والثاني للزمان وقد تقدم ذكرهما في قوله {فسيحوا في الأرض أربعة أشهر}"},{"id":"mutash-kirmani:170","bookId":"mutash-kirmani","type":"section","surah":9,"num":170,"title":"سورة التوبة","page":"ج1 ص132","text":"قوله {فإن تابوا وأقاموا الصلاة وآتوا الزكاة} ليس بتكرار لأن الأول في الكفار والثاني في اليهود فيمن حمل قوله {اشتروا بآيات الله ثمنا قليلا} على التوراة وقيل هما في الكفار وجزاء الأول تخلية سبيلهم وجزاء الثاني إثبات الأخوة لهم والمعنى بإثبات الله القرآن"},{"id":"mutash-kirmani:171","bookId":"mutash-kirmani","type":"section","surah":9,"num":171,"title":"سورة التوبة","page":"ج1 ص133","text":"قوله {كيف يكون للمشركين عهد عند الله وعند رسوله} ثم ذكر بعده {كيف وإن يظهروا عليكم لا يرقبوا فيكم إلا ولا ذمة} واقتصر عليه فذهب بعضهم إلى أنه تكرار للتأكيد واكتفى بذكر {كيف} عن الجملة بعده لدلالة الأولى عليه وقيل تقديره كيف لا تقتلونهم فلا يكون من التكرار في شيء"},{"id":"mutash-kirmani:172","bookId":"mutash-kirmani","type":"section","surah":9,"num":172,"title":"سورة التوبة","page":"ج1 ص133","text":"قوله {لا يرقبوا فيكم إلا ولا ذمة} وقوله {لا يرقبون في مؤمن إلا ولا ذمة} الأول للكفار والثاني لليهود وقيل ذكر الأول وجعل جزاء للشرط ثم أعاد ذلك تقبيحا لهم فقال {ساء ما كانوا يعملون} {لا يرقبون في مؤمن إلا ولا ذمة} فلا يكون تكرار محصنا"},{"id":"mutash-kirmani:173","bookId":"mutash-kirmani","type":"section","surah":9,"num":173,"title":"سورة التوبة","page":"ج1 ص133","text":"قوله {الذين آمنوا وهاجروا وجاهدوا في سبيل الله بأموالهم وأنفسهم} إنما قدم في سبيل الله في هذه السورة لموافقة قوله قبله {وجاهدوا في سبيل الله} وقد سبق ذكره في الأنفال وقد جاء بعده في موضعين {بأموالهم وأنفسهم في سبيل الله} ليعلم أن الأصل ذلك وإنما قدم ههنا لموافقة ما قبله فحسب"},{"id":"mutash-kirmani:174","bookId":"mutash-kirmani","type":"section","surah":9,"num":174,"title":"سورة التوبة","page":"ج1 ص133","text":"قوله {كفروا بالله وبرسوله ولا يأتون} بزيادة باء وبعده {إنهم كفروا بالله ورسوله وماتوا} بغير باء فيهما لأن الكلام في الآية الأولى إيجاب بعد نفي وهو الغاية في باب التأكيد وهو قولهم {وما منعهم أن تقبل منهم نفقاتهم إلا أنهم كفروا بالله} فأكد المعطوف أيضا فالباء ليكون الكل في التأكيد على منهاج واحد وليس كذلك الآيتان بعده فإنهما خلتا من التأكيد"},{"id":"mutash-kirmani:175","bookId":"mutash-kirmani","type":"section","surah":9,"num":175,"title":"سورة التوبة","page":"ج1 ص134","text":"قوله {فلا تعجبك أموالهم} بالفاء وقال في الآية الأخرى {ولا تعجبك أموالهم} بالواو لأن الفاء تتضمن معنى الجزاء والفعل الذي قبله مستقبل يتضمن معنى الشرط وهو قوله {ولا يأتون الصلاة إلا وهم كسالى ولا ينفقون إلا وهم كارهون} أي إن يكن منهم ذلك فما ذكر جزاؤهم فكان الفاء ههنا أحسن موقعا من الواو والتي بعدها جاء قبلها {كفروا بالله ورسوله وماتوا} بلفظ الماضي وبمعناه والماضي لا يتضمن معنى الشرط ولا يقع من الميت فعل فكان الواو أحسن"},{"id":"mutash-kirmani:176","bookId":"mutash-kirmani","type":"section","surah":9,"num":176,"title":"سورة التوبة","page":"ج1 ص134","text":"قوله {ولا أولادهم} بزيادة {لا} وقال في الأخرى {وأولادهم} بغير لا لأنه لما أكد الكلام الأول بالإيجاب بعد النفي وهو الغاية وعلق الثاني بالأول تعليق الجزاء بالشرط اقتضى الكلام الثاني من التوكيد ما اقتضاه الأول فأكد معنى النهي بتكرار {لا} في المعطوف"},{"id":"mutash-kirmani:177","bookId":"mutash-kirmani","type":"section","surah":9,"num":177,"title":"سورة التوبة","page":"ج1 ص134","text":"قوله {إنما يريد الله ليعذبهم} وقال في الأخرى {أن يعذبهم} لأن {إن} في هذه الآية مقدرة وهي الناصبة للفعل فصار في الكلام ههنا زيادة كزيادة الباء ولا في الآية"},{"id":"mutash-kirmani:178","bookId":"mutash-kirmani","type":"section","surah":9,"num":178,"title":"سورة التوبة","page":"ج1 ص135","text":"قوله {في الحياة الدنيا} وفي الآية الأخرى {في الدنيا} لأن الدنيا صفة الحياة في الآيتين فأثبت الموصوف والصفة في الأولى وحذف بذكره في الأولى وليس الآيتان مكررتين لأن الأولى في قوم والثانية في آخرين وقيل الأولى في اليهود والثانية في المنافقين وجواب آخر وهو أن المفعول في هذه الآية محذوف أي أن يزيد في نعمائهم بالأموال والأولاد ليعذبهم بها في الحياة الدنيا والآية الأخرى إخبار عن قوم ماتوا على الكفر فتعلقت الإرادة بنا هم فيه وهو العذاب"},{"id":"mutash-kirmani:179","bookId":"mutash-kirmani","type":"section","surah":9,"num":179,"title":"سورة التوبة","page":"ج1 ص135","text":"قوله {يريدون أن يطفئوا نور الله} وفي الصف {ليطفئوا} هذه الآية تشبه قوله {إنما يريد الله أن يعذبهم} و {ليعذبهم} حذف اللام من الآية الأولى لأن مرادهم إطفاء نور الله بأفواههم والمراد الذي هو المفعول به في الصف مضمر تقديره ومن أظلم ممن افترى على الله الكذب ليطفئوا نور الله واللام لام العلة وذهب بعض النحاة إلى أن الفعل محمول على المصدر أي إرادتهم لإطفاء نور الله"},{"id":"mutash-kirmani:180","bookId":"mutash-kirmani","type":"section","surah":9,"num":180,"title":"سورة التوبة","page":"ج1 ص136","text":"قوله {ورضوان من الله أكبر ذلك هو الفوز العظيم} هذه الكلمات تقع على وجهين أحدهما {ذلك الفوز} بغير {هو} وهو في القرآن في ستة مواضع في براءة موضعان وفي يونس والمؤمن والدخان والحديد وما في براءة أحدهما بزيادة الواو وهو قوله {فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم} وكذلك ما في المؤمن بزيادة الواو والجملة إذا جاءت بعد جملة من غير تراخ بنزول جاءت مربوطة بما قبلها إما بواو العطف وإما بكناية تعود من الثانية إلى الأولى وإما بإشارة فيها إليها وربما يجمع بين الإثنين منها والثلاثة للدلالة على مبالغة فيها ففي براءة {خالدين فيها ذلك الفوز} {خالدين فيها أبدا ذلك الفوز} وفيها أيضا {ورضوان من الله أكبر ذلك هو الفوز} فجمع بين اثنين وبعدها {فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم} فجمع بين الثلاثة تنبيها على أن الاستبشار من الله تعالى يتضمن رضوانه والرضوان يتضمن الخلود في الجنان قلت ويحتمل أن ذلك لما تقدمه من قوله {وعدا عليه حقا في التوراة والإنجيل والقرآن}"},{"id":"mutash-kirmani:181","bookId":"mutash-kirmani","type":"section","surah":9,"num":181,"title":"سورة التوبة","page":"ج1 ص136","text":"ويكون كل واحد منها في مقابلة واحد وكذلك في المؤمن تقدمه {فاغفر} {وقهم} {وأدخلهم} فوقعت في مقابلة الثلاثة"},{"id":"mutash-kirmani:182","bookId":"mutash-kirmani","type":"section","surah":9,"num":182,"title":"سورة التوبة","page":"ج1 ص136","text":"قوله {وطبع على قلوبهم} ثم قال بعده {وطبع الله} لأن قوله {وطبع} محمول على رأس المائة وهو قوله {وإذا أنزلت سورة} مبني للمجهول والثاني محمول على ما تقدم من ذكر الله تعالى مرات فكان اللائق {وطبع الله} ثم ختم كل آية بما يليق بها فقال في الأولى {لا يفقهون} وفي الثانية {لا يعلمون} لأن العلم فوق الفقه والفعل المسند إلى الله فوق المسند إلى المجهول"},{"id":"mutash-kirmani:183","bookId":"mutash-kirmani","type":"section","surah":9,"num":183,"title":"سورة التوبة","page":"ج1 ص137","text":"قوله {وسيرى الله عملكم ورسوله ثم تردون} وقال في الأخرى {فسيرى الله عملكم ورسوله والمؤمنون وستردون} لأن الأولى في المنافقين ولا يطلع على ضمائرهم إلا الله تعالى ثم رسوله بإطلاع الله إياه عليها كقوله {قد نبأنا الله من أخباركم} والثانية في المؤمنين وطاعات المؤمنين وعباداتهم ظاهرة لله ورسوله والمؤمنين سقط وختم آية المؤمنين بقوله {وستردون} لأن وعد فبناه على قوله {فسيرى الله}"},{"id":"mutash-kirmani:184","bookId":"mutash-kirmani","type":"section","surah":9,"num":184,"title":"سورة التوبة","page":"ج1 ص137","text":"قوله {إلا كتب لهم به عمل صالح} وفي الأخرى {إلا كتب لهم} لأن الآية الأولى مشتملة على ما هو من عملهم وهو قوله {ولا يطؤون موطئا يغيظ الكفار ولا ينالون من عدو نيلا} وعلى ما ليس من عملهم وهو الظمأ والنصب والمخمصة والله سبحانه وتعالى بفضله أجرى ذلك مجرى عملهم في الثواب فقال {إلا كتب لهم به عمل صالح} أي جزاء عمل صالح والثانية مشتملة على المشاق وقطع المسافات فكتب لهم ذلك بعينه وكذلك ختم الآية بقوله {ليجزيهم الله أحسن ما كانوا يعملون} لكن الكل من عملهم فوعدهم أحسن الجزاء عليه وختم الآية بقوله {إن الله لا يضيع أجر المحسنين} حتى ألحق ما ليس من عملهم بما هو من عملهم ثم جازاهم على الكل أحسن الجزاء"},{"id":"mutash-kirmani:185","bookId":"mutash-kirmani","type":"section","surah":10,"num":185,"title":"سورة يونس","page":"ج1 ص138","text":"قوله تعالى {إليه مرجعكم} وفي هود {إلى الله مرجعكم} لأن ما في هذه السورة خطاب للمؤمنين والكافرين جميعا يدل عليه قوله بعده {ليجزي الذين آمنوا وعملوا الصالحات بالقسط والذين كفروا} الآية وكذلك ما في المائدة {مرجعكم جميعا} لأنه خطاب للمؤمنين والكافرين بدليل قوله {فيه مختلفون} وما في هود خطاب للكفار يدل عليه {وإن تولوا فإني أخاف عليكم عذاب يوم كبير}"},{"id":"mutash-kirmani:186","bookId":"mutash-kirmani","type":"section","surah":10,"num":186,"title":"سورة يونس","page":"ج1 ص138","text":"قوله {وإذا مس الإنسان الضر} بالألف واللام لأنه إشارة إلى ما تقدم من الشر في قوله {ولو يعجل الله للناس الشر} فإن الضر والشر واحد وجاء الضر في هذه السورة بالألف واللام وبالإضافة وبالتنوين"},{"id":"mutash-kirmani:187","bookId":"mutash-kirmani","type":"section","surah":10,"num":187,"title":"سورة يونس","page":"ج1 ص138","text":"قوله {وما كانوا ليؤمنوا} بالواو لأنه معطوف على قوله {ظلموا} من قوله {لما ظلموا وجاءتهم رسلهم بالبينات} وفي غيرها بالفاء للتعقيب"},{"id":"mutash-kirmani:188","bookId":"mutash-kirmani","type":"section","surah":10,"num":188,"title":"سورة يونس","page":"ج1 ص138","text":"قوله {فمن أظلم} بالفاء لموافقة ما قبلها وقد سبق في الأنعام"},{"id":"mutash-kirmani:189","bookId":"mutash-kirmani","type":"section","surah":10,"num":189,"title":"سورة يونس","page":"ج1 ص138","text":"قوله {ما لا يضرهم ولا ينفعهم} سبق في الأعراف"},{"id":"mutash-kirmani:190","bookId":"mutash-kirmani","type":"section","surah":10,"num":190,"title":"سورة يونس","page":"ج1 ص138","text":"قوله {فيما فيه يختلفون} في هذه السورة وفي غيرها {فيما هم فيه يختلفون} بزيادة {هم} لأن في هذه السورة تقدم {فاختلفوا} فاكتفى به عن إعادة الضمير"},{"id":"mutash-kirmani:191","bookId":"mutash-kirmani","type":"section","surah":10,"num":191,"title":"سورة يونس","page":"ج1 ص139","text":"وفي الآية {بما لا يعلم في السماوات ولا في الأرض} بزيادة {لا} وتكرار {في} لأن تكرار {لا} مع النفي كثير حسن فلما كرر {لا} كرر {في} تحسينا للفظ بالألف لأنه وقع في مقابلة {أنجيتنا} ومثله في سبأ في موضعين والملائكة"},{"id":"mutash-kirmani:192","bookId":"mutash-kirmani","type":"section","surah":10,"num":192,"title":"سورة يونس","page":"ج1 ص139","text":"قوله {فلما أنجاهم} بالألف لأنه في مقابلة {أنجيتنا}"},{"id":"mutash-kirmani:193","bookId":"mutash-kirmani","type":"section","surah":10,"num":193,"title":"سورة يونس","page":"ج1 ص139","text":"قوله {فأتوا بسورة مثله} وفي هود {بعشر سور مثله} لأن ما في هذه السورة تقديره سورة مثل سورة يونس فالمضاف محذوف في السورتين وما في هود إشارة إلى ما تقدمها من أول الفاتحة إلى سورة هود وهو عشر سور"},{"id":"mutash-kirmani:194","bookId":"mutash-kirmani","type":"section","surah":10,"num":194,"title":"سورة يونس","page":"ج1 ص139","text":"قوله {وادعوا من استطعتم} في هذه السورة وكذلك في هود 13 وفي البقرة {شهداءكم} لأنه لما زاد في هود السور زاد في المدعوين ولهذا قال في سبحان {قل لئن اجتمعت الإنس والجن} مقترنا بقوله {بمثل هذا القرآن} والمراد به كله"},{"id":"mutash-kirmani:195","bookId":"mutash-kirmani","type":"section","surah":10,"num":195,"title":"سورة يونس","page":"ج1 ص139","text":"قوله {ومنهم من يستمعون إليك} بلفظ الجمع وبعده {ومنهم من ينظر إليك} بلفظ المفرد لأن المستمع إلى القرآن كالمستمع إلى النبي صلى الله عليه وسلم بخلاف النظر فكان في المستمعين كثرة فجمع ليطابق اللفظ المعنى ووحد {ينظر} حملا على اللفظ إذا لم يكثر كثرتهم"},{"id":"mutash-kirmani:196","bookId":"mutash-kirmani","type":"section","surah":10,"num":196,"title":"سورة يونس","page":"ج1 ص139","text":"قوله {ويوم يحشرهم كأن لم يلبثوا} في هذه الآية فحسب لأن قوله قبله {ويوم نحشرهم جميعا} وقوله {إليه مرجعكم جميعا} يدلان على ذلك فاكتفى به"},{"id":"mutash-kirmani:197","bookId":"mutash-kirmani","type":"section","surah":10,"num":197,"title":"سورة يونس","page":"ج1 ص140","text":"قوله {لكل أمة أجل إذا جاء أجلهم فلا يستأخرون ساعة} لأن التقدير فيها لكل أمة أجل فلا يستأخرون ساعة إذا جاء أجلهم فكان هذا فيمن قتل ببدر والمعنى لم يستأخروا"},{"id":"mutash-kirmani:198","bookId":"mutash-kirmani","type":"section","surah":10,"num":198,"title":"سورة يونس","page":"ج1 ص140","text":"قوله {ألا إن لله ما في السماوات والأرض} ذكر بلفظ {ما} في هذه الآية ولم يكرره لأن معنى {ما} ههنا المال فذكر بلفظ {ما} دون {من} ولم يكررها اكتفاء بقوله قبله {ولو أن لكل نفس ظلمت ما في الأرض}"},{"id":"mutash-kirmani:199","bookId":"mutash-kirmani","type":"section","surah":10,"num":199,"title":"سورة يونس","page":"ج1 ص140","text":"قوله {ألا إن لله من في السماوات ومن في الأرض} ذكر بلفظ {من} وكرر لأن هذه الآية نزلت في قوم آذوا رسول الله صلى الله عليه وسلم فنزل فيهم {ولا يحزنك قولهم} فاقتضى لفظ {من} وكرر لأن المراد من في الأرض ههنا لكونهم فيها لكن قدم ذكر {من في السماوات} تعظيما ثم عطف {من في الأرض} على ذلك"},{"id":"mutash-kirmani:200","bookId":"mutash-kirmani","type":"section","surah":10,"num":200,"title":"سورة يونس","page":"ج1 ص140","text":"قوله {ما في السماوات وما في الأرض} ذكر بلفظ {ما} وكرر لأن بعض الكفار قالوا {اتخذ الله ولدا} فقال سبحانه {له ما في السماوات وما في الأرض} فكان الموضع موضع {ما} وموضع التكرار للتأكيد والتخصيص"},{"id":"mutash-kirmani:201","bookId":"mutash-kirmani","type":"section","surah":10,"num":201,"title":"سورة يونس","page":"ج1 ص140","text":"قوله {ولكن أكثرهم لا يشكرون} ومثله في النمل وفي البقرة ويوسف والمؤمن {ولكن أكثر الناس لا يشكرون} لأن في هذه السورة تقدم {ولكن أكثرهم لا يعلمون} فوافقه وفي غيرها جاء بلفظ الصريح"},{"id":"mutash-kirmani:202","bookId":"mutash-kirmani","type":"section","surah":10,"num":202,"title":"سورة يونس","page":"ج1 ص141","text":"وفيها أيضا قوله {في الأرض ولا في السماء} فقدم الأرض لكون المخاطبين فيها ومثله في آل عمران وإبراهيم وطه والعنكبوت"},{"id":"mutash-kirmani:203","bookId":"mutash-kirmani","type":"section","surah":10,"num":203,"title":"سورة يونس","page":"ج1 ص141","text":"وفيها {إن في ذلك لآيات لقوم يسمعون} بناء على قوله {ومنهم من يستمعون إليك} ومثله في الروم {إن في ذلك لآيات لقوم يسمعون}"},{"id":"mutash-kirmani:204","bookId":"mutash-kirmani","type":"section","surah":10,"num":204,"title":"سورة يونس","page":"ج1 ص141","text":"قوله {قالوا اتخذ الله ولدا} بغير واو ولو لأنه اكتفى بالفاء عن الواو العاطف ومثله في البقرة على قراءة ابن عامر {قالوا اتخذ الله ولدا}"},{"id":"mutash-kirmani:205","bookId":"mutash-kirmani","type":"section","surah":10,"num":205,"title":"سورة يونس","page":"ج1 ص141","text":"قوله {فنجيناه} سبق ومثله في الأنبياء والشعراء"},{"id":"mutash-kirmani:206","bookId":"mutash-kirmani","type":"section","surah":10,"num":206,"title":"سورة يونس","page":"ج1 ص141","text":"قوله {كذبوا} سبق وقوله {نطبع على} قد سبق"},{"id":"mutash-kirmani:207","bookId":"mutash-kirmani","type":"section","surah":10,"num":207,"title":"سورة يونس","page":"ج1 ص141","text":"قوله {من فرعون وملئهم} بالجمع وفي غيرها {ملئه} لأن الضمير في هذه السورة يعود إلى الذرية وقيل يعود إلى القوم وفي غيرها يعود إلى فرعون"},{"id":"mutash-kirmani:208","bookId":"mutash-kirmani","type":"section","surah":10,"num":208,"title":"سورة يونس","page":"ج1 ص142","text":"قوله {وأمرت أن أكون من المؤمنين} وفي النمل {من المسلمين} لأن ما قبله في هذه السورة {المؤمنين} فوافقه وفي النمل وافق ما قبله وهو قوله {فهم مسلمون} وقد تقدم في يونس {وأمرت أن أكون من المسلمين}"},{"id":"mutash-kirmani:209","bookId":"mutash-kirmani","type":"section","surah":11,"num":209,"title":"سورة هود","page":"ج1 ص142","text":"قوله تعالى {فإن لم يستجيبوا لكم فاعلموا} بحذف النون والجمع وفي القصص {فإن لم} بإثبات النون {لك فاعلم} على الواحد عدت هذه الآية من المتشابه في فصلين أحدهما حذف النون من {فإن لم} في هذه السورة وإثباتها في غيرها وهذا من فعل الخط وقد ذكرته في كتابة المصاحف والثاني جمع الخطاب ههنا وتوحيده في القصص لأن ما في هذه السورة خطاب للكفار والفعل يعود لمن استطعتم وما في القصص خطاب للنبي صلى الله عليه وسلم والفعل للكفار"},{"id":"mutash-kirmani:210","bookId":"mutash-kirmani","type":"section","surah":11,"num":210,"title":"سورة هود","page":"ج1 ص143","text":"قوله {لا جرم أنهم في الآخرة هم الأخسرون} وفي النحل {هم الخاسرون} لأن هؤلاء صدوا عن سبيل الله وصدوا غيرهم فضلوا فهم الأخسرون يضاعف لهم العذاب وفي النحل صدوا فهم الخاسرون قال الخطيب لأن ما قبلها في هذه السورة {يبصرون} {يفترون} لا يعتمدان على ألف بينهما وفي النحل {الكافرون} و {الغافلون} فللموافقة بين الفواصل جاء في هذه السورة { الأخسرون} وفي النحل {الخاسرون}"},{"id":"mutash-kirmani:211","bookId":"mutash-kirmani","type":"section","surah":11,"num":211,"title":"سورة هود","page":"ج1 ص143","text":"قوله {ولقد أرسلنا نوحا إلى قومه إني لكم نذير} بالفاء وبعده {فقال الملأ} بالفاء وهو القياس وقد سبق"},{"id":"mutash-kirmani:212","bookId":"mutash-kirmani","type":"section","surah":11,"num":212,"title":"سورة هود","page":"ج1 ص143","text":"قوله {وآتاني رحمة من عنده} وبعده {وآتاني منه رحمة}"},{"id":"mutash-kirmani:213","bookId":"mutash-kirmani","type":"section","surah":11,"num":213,"title":"سورة هود","page":"ج1 ص143","text":"وبعدهما {ورزقني منه رزقا حسنا} لأن {عنده} وإن كان ظرفا فهو اسم فذكر الأولى بالصريح والثانية والثالثة بالكناية لتقدم ذكره فلما كنى عنه قدمه لأن الكناية يتقدم عليها الظاهر نحو ضرب زيد عمرا فإن كنيت عن عمر قدمته نحو عمرو ضرب زيد وكذلك زيد أعطاني درهما من ماله فإن كنيت عن المال قلت المال زيد أعطاني منه درهما قال الخطيب لما وقع {وآتاني رحمة} في جواب كلام فيه ثلاثة أفعال كلها متعد إلى مفعولين ليس بينهما حائل بجار ومجرور وهو قوله {ما نراك إلا بشرا مثلنا} {وما نراك اتبعك} {بل نظنكم كاذبين} أجرى الجواب مجراه فجمع بين المفعولين من غير حائل وأما الثاني فقد وقع في جواب كلام قد حيل بينهما بجار ومجرور وهو قوله {قد كنت فينا مرجوا} لأن خبر كان بمنزلة المفعول كذلك حيل في الجواب بين المفعولين بالجار والمجرور"},{"id":"mutash-kirmani:214","bookId":"mutash-kirmani","type":"section","surah":11,"num":214,"title":"سورة هود","page":"ج1 ص144","text":"قوله {ويا قوم لا أسألكم عليه مالا إن أجري إلا على الله} في قصة نوح وفي غيرها {أجرا إن أجري} لأن في قصة نوح وقع بعدها {خزائن} ولفظ المال بالخزائن أليق"},{"id":"mutash-kirmani:215","bookId":"mutash-kirmani","type":"section","surah":11,"num":215,"title":"سورة هود","page":"ج1 ص144","text":"قوله {ولا أقول إني ملك} وفي الأنعام {ولا أقول لكم إني ملك} لأن في الأنعام آخر الكلام فيه جاء بالخطاب وختم به وليس في هذه السورة آخر الكلام بل آخره {تزدري أعينكم} فبدأ بالخطاب وختم به في السورتين"},{"id":"mutash-kirmani:216","bookId":"mutash-kirmani","type":"section","surah":11,"num":216,"title":"سورة هود","page":"ج1 ص144","text":"قوله {ولا تضرونه شيئا} وفي التوبة {ولا تضروه شيئا} ذكر هذا في المتشابه وليس منه لأن قوله {ولا تضرونه شيئا} عطف على قوله {ويستخلف ربي} فهو مرفوع وفي التوبة معطوف على {يعذبكم} {يستبدل} وهما مجزومان فهو مجزوم"},{"id":"mutash-kirmani:217","bookId":"mutash-kirmani","type":"section","surah":11,"num":217,"title":"سورة هود","page":"ج1 ص144","text":"قوله {ولما جاء أمرنا نجينا هودا} في قصة هود وشعيب بالواو وفي قصة صالح ولوط {فلما} بالفاء لأن العذاب في قصة هود وشعيب تأخر عن وقت الوعيد فإن في قصة هود {فإن تولوا فقد أبلغتكم ما أرسلت به إليكم ويستخلف ربي قوما غيركم} وفي قصة شعيب {سوف تعلمون} والتخويف قارنه التسويف فجاء بالواو المهملة وفي قصة صالح ولوط وقع العذاب عقيب الوعيد فإن في قصة صالح {تمتعوا في داركم ثلاثة أيام} وفي قصة لوط {أليس الصبح بقريب} فجاء الفاء للتعجيل والتعقيب"},{"id":"mutash-kirmani:218","bookId":"mutash-kirmani","type":"section","surah":11,"num":218,"title":"سورة هود","page":"ج1 ص145","text":"قوله {وأتبعوا في هذه الدنيا لعنة} وفي قصة موسى {في هذه لعنة} لأنه لما ذكر في الآية الأولى الصفة والموصوف اقتصر في الثانية على الموصوف للعلم والاكتفاء بما قبله"},{"id":"mutash-kirmani:219","bookId":"mutash-kirmani","type":"section","surah":11,"num":219,"title":"سورة هود","page":"ج1 ص145","text":"قوله {إن ربي قريب مجيب} وبعده {إن ربي رحيم ودود} لموافقة الفواصل ومثله {لحليم أواه منيب} وفي التوبة {لأواه حليم} للروي في السورتين"},{"id":"mutash-kirmani:220","bookId":"mutash-kirmani","type":"section","surah":11,"num":220,"title":"سورة هود","page":"ج1 ص145","text":"قوله {وإننا لفي شك مما تدعونا إليه مريب} وفي إبراهيم {وإنا لفي شك مما تدعوننا إليه مريب} لأنه في السورتين جاء على الأصل وتدعونا خطاب مفرد وفي إبراهيم لما وقع بعده {تدعوننا} بنونين لأنه خطاب جمع حذف منه النون استثقالا للجمع بين النونات ولأن في إبراهيم اقترن بضمير قد غير ما قبله بحذف الحركة وهو الضمير المرفوع في قوله {كفرنا} فغير ما قبله في إننا بحذف النون وفي هود اقترن بضمير لم يغير ما قبله وهو الضمير المنصوب والضمير المجرور في قوله {فينا مرجوا قبل هذا أتنهانا أن نعبد ما يعبد آباؤنا} فصح كما صح"},{"id":"mutash-kirmani:221","bookId":"mutash-kirmani","type":"section","surah":11,"num":221,"title":"سورة هود","page":"ج1 ص145","text":"قوله {وأخذ الذين ظلموا الصيحة} ثم قال {وأخذت الذين ظلموا} التذكير والتأنيث حسنان لكن التذكير أخف في الأولى بحذف حرف منه وفي الأخرى وافق ما بعدها وهو {كما بعدت ثمود} قال الخطيب لما جاءت في قصة شعيب مرة {الرجفة} ومرة {الظلة} ومرة {الصيحة} ازاداد التأنيث حسنا"},{"id":"mutash-kirmani:222","bookId":"mutash-kirmani","type":"section","surah":11,"num":222,"title":"سورة هود","page":"ج1 ص146","text":"قوله {في ديارهم} في موضعين في هذه السورة لأنه اتصل بالصيحة وكانت من السماء فازدادت على الرجفة لأنها الزلزلة وهي تختص بجزء من الأرض فجمعت مع الصيحة وأفردت مع الرجفة"},{"id":"mutash-kirmani:223","bookId":"mutash-kirmani","type":"section","surah":11,"num":223,"title":"سورة هود","page":"ج1 ص146","text":"قوله {إن ثمود} بالتنوين ذكر في المتشابه فقلت ثمود من الثمد وهو الماء القليل جعل اسم قبيلة فهو منصرف من وجه وغير منصرف من وجه فصرفوه في حال النصب لأنه أخف أحوال الاسم ولم يصرفوه في حال الرفع لأنه أثقل أحوال الاسم وجاز الوجهان في الجر لأنه واسطة بين الخفة والثقل"},{"id":"mutash-kirmani:224","bookId":"mutash-kirmani","type":"section","surah":11,"num":224,"title":"سورة هود","page":"ج1 ص146","text":"قوله {وما كان ربك ليهلك القرى بظلم وأهلها مصلحون} وفي القصص {مهلك القرى} لأن الله تعالى نفى الظلم عن نفسه بأبلغ لفظ يستعمل في النفي لأن هذه اللام لام الجحود وتظهر بعدها أن ولا يقع بعدها المصدر وتختص بكان معناه ما فعلت فيما مضى ولا أفعل في الحال ولا أفعل في المستقبل فكان الغاية في النفي وما في القصص لم يكن صريح ظلم فاكتفى بذكر اسم الفاعل وهو أحد الأزمنة غير معين ثم نفاه"},{"id":"mutash-kirmani:225","bookId":"mutash-kirmani","type":"section","surah":11,"num":225,"title":"سورة هود","page":"ج1 ص147","text":"قوله {فأسر بأهلك بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك} وفي الحجر {بقطع من الليل واتبع أدبارهم ولا يلتفت منكم أحد} استثنى في هذه السورة من الأهل قوله {إلا امرأتك} ولم يستثن في الحجر اكتفاء بما قبله وهو قوله {إلى قوم مجرمين} {إلا آل لوط إنا لمنجوهم أجمعين} {إلا امرأته} فهذا الاستثناء الذي تفردت به سورة الحجر قام مقام الاستثناء من قوله {فأسر بأهلك بقطع من الليل} وزاد في الحجر {واتبع أدبارهم} لأنه إذا ساقهم وكان من ورائهم علم بنجاتهم ولا يخفى عليه حالهم"},{"id":"mutash-kirmani:226","bookId":"mutash-kirmani","type":"section","surah":12,"num":226,"title":"سورة يوسف","page":"ج1 ص147","text":"قوله تعالى {إن ربك عليم حكيم} ليس في القرآن غيره أي عليم علمك تأويل الأحاديث حكيم باجتنابك للرسالة"},{"id":"mutash-kirmani:227","bookId":"mutash-kirmani","type":"section","surah":12,"num":227,"title":"سورة يوسف","page":"ج1 ص147","text":"قوله {بل سولت لكم أنفسكم أمرا فصبر جميل} في هذه السورة في موضعين ليس بتكرار لأنه ذكر الأول حين نعى إليه يوسف والثاني لما رفع إليه ما جرى على بنيامين"},{"id":"mutash-kirmani:228","bookId":"mutash-kirmani","type":"section","surah":12,"num":228,"title":"سورة يوسف","page":"ج1 ص147","text":"قوله {ولما بلغ أشده آتيناه حكما وعلما} ومثلها في القصص في قصة موسى وزاد فيها {واستوى} لأن يوسف عليه السلام أوحى إليه وهو في البئر وموسى عليه السلام أوحى إليه بعد أربعين سنة وقوله {واستوى} إشارة إلى تلك الزيادة ومثله {وبلغ أربعين سنة} بعد قوله {حتى إذا بلغ أشده} والخلاف في أشده قد ذكر في موضعه"},{"id":"mutash-kirmani:229","bookId":"mutash-kirmani","type":"section","surah":12,"num":229,"title":"سورة يوسف","page":"ج1 ص147","text":"قوله {معاذ الله} في هذه السورة في موضعين ليس بتكرار لأن الأول ذكر حين دعته إلى المواقعة والثاني حين دعى إلى تغيير حكم السرقة فليس بتكرار"},{"id":"mutash-kirmani:230","bookId":"mutash-kirmani","type":"section","surah":12,"num":230,"title":"سورة يوسف","page":"ج1 ص148","text":"قوله {قلن حاش لله} في الموضعين أحدهما في حضرة يوسف عليه السلام حين نفين عنه البشرية بزعمهن والثاني بظهر الغيب حين نفين عنه السوء فليس بتكرار"},{"id":"mutash-kirmani:231","bookId":"mutash-kirmani","type":"section","surah":12,"num":231,"title":"سورة يوسف","page":"ج1 ص148","text":"قوله {إنا نراك من المحسنين} في موضعين ليس بتكرار لأن الأول من كلام صاحبي السجن ليوسف عليه السلام والثاني من كلام إخوة يوسف ليوسف"},{"id":"mutash-kirmani:232","bookId":"mutash-kirmani","type":"section","surah":12,"num":232,"title":"سورة يوسف","page":"ج1 ص148","text":"قوله {يا صاحبي السجن} في موضعين الأول منهما ذكره يوسف حين عدل عن جوابهما إلى دعائهما إلى الإيمان والثاني حين دعياه إلى تعبير الرؤيا لهما تنبيها على أن الكلام الأول قد تم"},{"id":"mutash-kirmani:233","bookId":"mutash-kirmani","type":"section","surah":12,"num":233,"title":"سورة يوسف","page":"ج1 ص148","text":"قوله {لعلي أرجع إلى الناس لعلهم يعلمون} كرر لعل رعاية لفواصل الآي إذ لو جاء بمقتضى الكلام لقال لعلي أرجع فيعلموا بحذف النون على الجواب ومثله في هذه السورة سواء قوله {لعلهم يعرفونها إذا انقلبوا إلى أهلهم لعلهم يرجعون} فمقتضى الكلام لعلهم يعرفونها فيرجعوا"},{"id":"mutash-kirmani:234","bookId":"mutash-kirmani","type":"section","surah":12,"num":234,"title":"سورة يوسف","page":"ج1 ص149","text":"قوله {تالله} في أربعة مواضع الأول يمين منهم أنهم ليسوا سارقين وأن أهل مصر بذلك عالمون والثاني يمين منهم أنك لو واظبت على الحزن تصير حرضا أو تكون من الهالكين والثالث يمين منهم أن الله فضله عليهم وإنهم كانوا خاطئين والرابع ما ذكره وهو قوله {قالوا تالله إنك لفي ضلالك القديم} وهو يمين من أولاده على أنه لم يزل على محبة يوسف"},{"id":"mutash-kirmani:235","bookId":"mutash-kirmani","type":"section","surah":12,"num":235,"title":"سورة يوسف","page":"ج1 ص149","text":"قوله {وما أرسلنا من قبلك} وفي الأنبياء {وما أرسلنا قبلك} بغير {من} لأن {قبل} اسم للزمان السابق على ما أضيف إليه و {من} تفيد استيعاب الطرفين وما في هذه السورة للاستيعاب وقد يقع {قبل} على بعض ما تقدم كما في الأنبياء في قوله {ما آمنت قبلهم من قرية} ثم وقع عقيبها {وما أرسلنا قبلك} بحذف {من} لأنه بعينه {قوله} {أفلم يسيروا في الأرض} بالفاء وفي الروم 9 والملائكة 44 بالواو لأن الفاء تدل على الاتصال والعطف والواو تدل على العطف المجرد وفي السورة قد اتصلت بالأول لقوله {وما أرسلنا من قبلك إلا رجالا نوحي إليهم من أهل القرى أفلم يسيروا في الأرض فينظروا} حال من كذبهم وما نزل بهم من العذاب وليس كذلك في الروم والملائكة"},{"id":"mutash-kirmani:236","bookId":"mutash-kirmani","type":"section","surah":12,"num":236,"title":"سورة يوسف","page":"ج1 ص150","text":"قوله {ولدار الآخرة خير} وفي الأعراف {والدار الآخرة خير} على الصفة لأن في هذه السورة تقدم ذكر الساعة وصار التقدير ولدار الساعة الآخرة فحذف الموصوف وفي الأعراف تقدم قوله {عرض هذا الأدنى} أي المنزل الأدنى فجعله وصفا للمنزل والدار الدنيا والدار الآخرة بمعناه فأجرى مجراه تأمل في هذه السورة فإن فيها برهانا لأحسن القصص"},{"id":"mutash-kirmani:237","bookId":"mutash-kirmani","type":"section","surah":13,"num":237,"title":"سورة الرعد","page":"ج1 ص150","text":"قوله تعالى {كل يجري لأجل مسمى} وفي سورة لقمان {إلى أجل} لا ثاني له لأنك تقول في الزمان جرى ليوم كذا وإلى يوم كذا والأكثر اللام كما في هذه السورة وسورة الملائكة 13 وكذلك في يس {تجري لمستقر لها} لأنه بمنزلة التاريخ تقول لبثت لثلاث بقين من الشهر وآتيك لخمس تبقى من الشهر وأما في لقمان فوافق ما قبلها وهو قوله {ومن يسلم وجهه إلى الله} والقياس لله كما في قوله {أسلمت وجهي لله} لكنه حمل على المعنى أي يقصد بطاعته إلى الله وكذلك {يجري إلى أجل مسمى} أي يجري إلى وقته المسمى له"},{"id":"mutash-kirmani:238","bookId":"mutash-kirmani","type":"section","surah":13,"num":238,"title":"سورة الرعد","page":"ج1 ص150","text":"قوله {إن في ذلك لآيات لقوم يتفكرون} وبعدها {إن في ذلك لآيات لقوم يعقلون} لأن بالتفكر في الآيات يعقل ما جعلت الآيات دليلا عليه فهو الأول المؤدي إلى الثاني"},{"id":"mutash-kirmani:239","bookId":"mutash-kirmani","type":"section","surah":13,"num":239,"title":"سورة الرعد","page":"ج1 ص151","text":"قوله {ويقول الذين كفروا لولا أنزل عليه آية من ربه} في هذه السورة في موضعين وزعموا أنه لا ثالث لهما ليس بتكرار محض لأن المراد بالأول آية مما اقترحوا نحو ما في قوله {لن نؤمن لك حتى تفجر لنا من الأرض ينبوعا} والمراد بالثاني آية ما لأنهم لم يهتدوا إلى أن القرآن آية فوق كل آية وأنكروا سائر آياته صلى الله عليه وسلم"},{"id":"mutash-kirmani:240","bookId":"mutash-kirmani","type":"section","surah":13,"num":240,"title":"سورة الرعد","page":"ج1 ص151","text":"قوله {ولله يسجد من في السماوات والأرض} وفي النحل {ولله يسجد ما في السماوات وما في الأرض من دابة والملائكة} وفي الحج {ألم تر أن الله يسجد له من في السماوات ومن في الأرض والشمس والقمر والنجوم} لأن {ما} في هذه السورة تقدم آية السجدة ذكر العلويات من البرق والسحاب والصواعق ثم ذكر الملائكة وتسبيحهم وذكر بآخرة الأصنام والكفار فبدأ في آية السجدة بذكر من في السموات لذلك وذكر الأرض تبعا ولم يذكر {من} فيها استخفافا بالكفار والأصنام وأما ما في الحج فقد تقدم ذكر المؤمنين وسائر الأديان فقدم ذكر من في السموات تعظيما لهم ولها وذكر من في الأرض لأنهم هم الذين تقدم ذكرهم وأما في النحل فقد تقدم ذكر ما خلق الله على العموم ولم يكن فيه ذكر الملائكة ولا الإنس بالصريح فاقتضت الآية {ما في السماوات} فقال في كل آية ما لاق بها"},{"id":"mutash-kirmani:241","bookId":"mutash-kirmani","type":"section","surah":13,"num":241,"title":"سورة الرعد","page":"ج1 ص151","text":"قوله {كذلك يضرب الله الحق والباطل} ليس بتكرار لأن التقدير كذلك يضرب الله الحق والباطل الأمثال فلما اعترض بينهما {فأما} {وأما} وأطال الكلام أعاد فقال {كذلك يضرب الله الأمثال}"},{"id":"mutash-kirmani:242","bookId":"mutash-kirmani","type":"section","surah":13,"num":242,"title":"سورة الرعد","page":"ج1 ص152","text":"قوله {لو أن لهم ما في الأرض جميعا ومثله معه لافتدوا به} وفي المائدة {ليفتدوا به} لأن لو وجوابها يتصلان بالماضي فقال في هذه السورة {لافتدوا به} وجوابه في المائدة {ما تقبل منهم} وهو بلفظ الماضي وقوله {ليفتدوا به} علة وليس بجواب"},{"id":"mutash-kirmani:243","bookId":"mutash-kirmani","type":"section","surah":13,"num":243,"title":"سورة الرعد","page":"ج1 ص152","text":"قوله {ما أمر الله به أن يوصل} في موضعين من هذه السورة ليس بتكرار لأن الأول متصل بقوله {يصلون} وعطف عليه {ويخشون} والثاني متصل بقوله {يقطعون} وعطف عليه {ويفسدون}"},{"id":"mutash-kirmani:244","bookId":"mutash-kirmani","type":"section","surah":13,"num":244,"title":"سورة الرعد","page":"ج1 ص152","text":"قوله {ولقد أرسلنا رسلا من قبلك} ومثله في المؤمن 78 ليس بتكرار قال ابن عباس عيروا رسول الله صلى الله عليه وسلم باشتغاله بالنكاح والتكثر منه فأنزل الله تعالى {ولقد أرسلنا رسلا من قبلك وجعلنا لهم أزواجا وذرية} بخلاف ما في المؤمن فإن المراد منه لست ببدع من الرسل {ولقد أرسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك}"},{"id":"mutash-kirmani:245","bookId":"mutash-kirmani","type":"section","surah":13,"num":245,"title":"سورة الرعد","page":"ج1 ص152","text":"قوله {وإما نرينك} مقطوع وفي سائر القرآن {وأما} موصل وهو من اللهجات وقد ذكر في موضعه"},{"id":"mutash-kirmani:246","bookId":"mutash-kirmani","type":"section","surah":14,"num":246,"title":"سورة إبراهيم","page":"ج1 ص152","text":"قوله {ويذبحون} بواو العطف قد سبق والله أعلم"},{"id":"mutash-kirmani:247","bookId":"mutash-kirmani","type":"section","surah":14,"num":247,"title":"سورة إبراهيم","page":"ج1 ص153","text":"قوله {وإنا} بنون واحدة و {تدعوننا} بنونين على القياس وقد سبق في هود"},{"id":"mutash-kirmani:248","bookId":"mutash-kirmani","type":"section","surah":14,"num":248,"title":"سورة إبراهيم","page":"ج1 ص153","text":"قوله {فليتوكل المؤمنون} وبعده {فليتوكل المتوكلون} لأن الإيمان سابق على التوكل لأن على من صفة القدرة ولأن {مما كسبوا} صفة لشيء وإنما قدم مما كسبوا في هذه السورة لأن الكسب هو المقصود بالذكر فإن المثل ضرب للعمل يدل عليه ما قبله {أعمالهم كرماد اشتدت به الريح في يوم عاصف لا يقدرون مما كسبوا على شيء}"},{"id":"mutash-kirmani:249","bookId":"mutash-kirmani","type":"section","surah":14,"num":249,"title":"سورة إبراهيم","page":"ج1 ص153","text":"قوله تعالى {لا يقدرون مما كسبوا على شيء} وقال في البقرة {لا يقدرون على شيء مما كسبوا} لأن الأصل ما في البقرة"},{"id":"mutash-kirmani:250","bookId":"mutash-kirmani","type":"section","surah":14,"num":250,"title":"سورة إبراهيم","page":"ج1 ص153","text":"قوله {أنزل من السماء ماء} وفي النمل {وأنزل لكم من السماء ماء} بزيادة لكم لأن {لكم} في هذه السورة مذكور في آخر الآية فاكتفى بذكره ولم يكن في النمل في آخرها فذكر في أولها وليس قوله {ما كان لكم} يكفى عن ذكره لأنه نفى ولا يفيد معنى الأول"},{"id":"mutash-kirmani:251","bookId":"mutash-kirmani","type":"section","surah":15,"num":251,"title":"سورة الحجر","page":"ج1 ص153","text":"قوله {لو ما تأتينا} وفي غيرها {لولا} لأن {لولا} تأتي على وجهين أحدهما امتناع الشيء لوجود غيره وهو الأكثر والثاني بمعنى هلا وهو للتحضيض ويختص بالفعل ولولا بمعناه وخصت هذه السورة بلوما موافقة لقوله تعالى {ربما يود} فإنها أيضا مما خصت به هذه السورة"},{"id":"mutash-kirmani:252","bookId":"mutash-kirmani","type":"section","surah":15,"num":252,"title":"سورة الحجر","page":"ج1 ص154","text":"قوله {وإذ قال ربك للملائكة إني خالق بشرا} هنا وفي ص 71 وفي البقرة {وإذ قال ربك للملائكة إني جاعل} ولا ثالث لهما لأن جعل إذا كان بمعنى خلق يستعمل في الشيء يتجدد ويتكرر كقوله {خلق السماوات والأرض وجعل الظلمات والنور} لأنهما يتجددان زمانا بعد زمان وكذلك الخليفة يدل لفظه على أن بعضهم يخلف بعضا إلى يوم القيامة وخصت هذه السورة بقوله {إني خالق بشرا} إذ ليس في لفظ البشر ما يدل على التجدد والتكرار فجاء في كل واحدة من السورتين ما اقتضاه ما بعده من الألفاظ"},{"id":"mutash-kirmani:253","bookId":"mutash-kirmani","type":"section","surah":15,"num":253,"title":"سورة الحجر","page":"ج1 ص154","text":"قوله {فسجد الملائكة كلهم أجمعون} في هذه وفي ص 73 لأنه لما بالغ في السورتين في الأمر بالسجود وهو قوله {فقعوا له ساجدين} في السورتين بالغ في الامتثال فيهما فقال {فسجد الملائكة كلهم أجمعون} لتقع الموافقة بين أولاها وأخراها وباقي قصة آدم وإبليس سبق"},{"id":"mutash-kirmani:254","bookId":"mutash-kirmani","type":"section","surah":15,"num":254,"title":"سورة الحجر","page":"ج1 ص154","text":"قوله في هذه السورة لإبليس {وإن عليك اللعنة} بالألف واللام وفي ص {وإن عليك لعنتي} بالإضافة لأن الكلام في هذه السورة جرى على الجنس من أول القصة في قوله {ولقد خلقنا الإنسان} {والجان خلقناه} {فسجد الملائكة كلهم} كذلك قال {عليك اللعنة} وفي ص تقدم {لما خلقت بيدي} فختم بقوله {عليك لعنتي}"},{"id":"mutash-kirmani:255","bookId":"mutash-kirmani","type":"section","surah":15,"num":255,"title":"سورة الحجر","page":"ج1 ص155","text":"قوله {ونزعنا ما في صدورهم من غل} وزاد في هذه السورة {إخوانا} لأنها نزلت في أصحاب رسول الله صلى الله عليه وسلم وما سواها عام في المؤمنين"},{"id":"mutash-kirmani:256","bookId":"mutash-kirmani","type":"section","surah":15,"num":256,"title":"سورة الحجر","page":"ج1 ص155","text":"قوله في قصة إبراهيم {فقالوا سلاما قال إنا منكم وجلون} لأن هذه السورة متأخرة فاكتفى بها عما في هود لأن التقدير فقالوا سلاما قال سلام فما لبث أن جاء بعجل حنيذ فلما رأى أيديهم لا تصل إليه نكرهم وأوجس منهم خيفة قال إنا منكم وجلون فحذف للدلالة عليه"},{"id":"mutash-kirmani:257","bookId":"mutash-kirmani","type":"section","surah":15,"num":257,"title":"سورة الحجر","page":"ج1 ص155","text":"قوله {وأمطرنا عليهم} وفي غيرها {وأمطرنا عليها} قال بعض المفسرين عليهم أي على أهلها وقال بعضهم على من شذ من القرية منهم قلت وليس في القولين ما يوجب تخصيص هذه السورة بقوله {عليهم} بل هو يعود على أول القصة وهو {إنا أرسلنا إلى قوم مجرمين} ثم قال {وأمطرنا عليهم حجارة من سجيل} فهذه لطيفة فاحفظها"},{"id":"mutash-kirmani:258","bookId":"mutash-kirmani","type":"section","surah":15,"num":258,"title":"سورة الحجر","page":"ج1 ص156","text":"قوله {إن في ذلك لآيات للمتوسمين} بالجمع وبعدها {لآية للمؤمنين} على التوحيد قال الخطيب الأولى إشارة إلى ما تقدم من قصة لوط وضيف إبراهيم وتعرض قوم لوط لهم طمعا فيهم وقلب القرية على من فيها وإمطار الحجارة عليها وعلى من غاب منهم فختم بقوله {لآيات للمتوسمين} أي لمن تدبر السمة وهي ما وسم الله به قوم لوط وغيرهم قال والثانية تعود إلى القرية وإنها لسبيل مقيم وهي واحدة فوحد الآية قلت ما جاء من الآيات فلجمع الدلائل وما جاء من الآية فلوحدانية المدلول عليه فلما ذكر عقيبه المؤمنون وهم المقرون بوحدانية الله تعالى وحد الآية وليس لها نظير في القرآن إلا في العنكبوت وهو قوله تعالى {خلق الله السماوات والأرض بالحق إن في ذلك لآية للمؤمنين} فوحد بعد ذكر الجمع لما ذكرت والله أعلم"},{"id":"mutash-kirmani:259","bookId":"mutash-kirmani","type":"section","surah":16,"num":259,"title":"سورة النحل","page":"ج1 ص157","text":"قوله فيها في موضعين {إن في ذلك لآيات} بالجمع وفي خمس مواضع {إن في ذلك لآية} على الوحدة أما الجمع فلموافقة قوله {مسخرات} في الآيتين لتقع الموافقة في اللفظ والمعنى وأما التوحيد فلتوحيد المدلول عليه ومن الخمس قوله {إن في ذلك لآية لقوم يذكرون} وليس له نظير وخص الذكر لاتصاله بقوله {وما ذرأ لكم في الأرض مختلفا ألوانه} فإن اختلاف ألوان الشيء وتغير أحواله يدل على صانع حكيم فما يشبهه شيء فمن تأمل فيها تذكر ومن الخمس {إن في ذلك لآية لقوم يتفكرون} في موضعين وليس لهما نظير وخصتا بالتفكر لأن الأولى متصلة بقوله {ينبت لكم به الزرع والزيتون والنخيل والأعناب ومن كل الثمرات} وأكثرها للأكل وبه قوام البدن فيستدعى تفكرا وتأملا ليعرف به المنعم عليه فيشكر والثانية متصلة بذكر النحل وفيها أعجوبة من انقيادها لأميرها واتخاذها البيوت على أشكال يعجز عنها الحاذق ثم تتبعها الزهر والطل من الأشجار ثم خروج ذلك من بطونها لعابا هو شفاء فاقتضى ذلك ذكرا بليغا فختم الآية بالتفكير"},{"id":"mutash-kirmani:260","bookId":"mutash-kirmani","type":"section","surah":16,"num":260,"title":"سورة النحل","page":"ج1 ص157","text":"قوله {وترى الفلك مواخر فيه ولتبتغوا} ما في هذه السورة جاء على القياس فإن الفلك المفعول الأول لترى ومواخر المفعول الثاني وفيه ظروف وحقه التأخر والواو في {ولتبتغوا} للعطف على لام العلة في قوله {لتأكلوا منه} وأما في الملائكة فقدم {فيه} موافقة لما قبله وهو قوله {ومن كل تأكلون لحما طريا} فوافق تقديم الجار والمجرور على الفعل والفاعل ولم يزد الواو على {لتبتغوا} لأن اللام في لتبتغوا هنا لام العلة وليس بعطف على شيء قبله ثم إن قوله {وترى الفلك مواخر فيه} في هذه السورة {فيه مواخر} في فاطر اعتراض في السورتين يجري مجرى المثل ولهذا وحد الخطاب فيه وهو قوله {وترى} وقبله وبعده جمع وهو قوله {لتأكلوا} {وتستخرجوا} ولتبتغوا {والملائكة} {تأكلون} {تستخرجون} ومثله في القرآن كثير {كمثل غيث أعجب الكفار نباته ثم يهيج فتراه مصفرا} وكذلك {تراهم ركعا سجدا} {وترى الملائكة حافين من حول العرش} وأمثاله أي لو حصرت أيها المخاطب لرأيته بهذه الصفة كما تقول أيها الرجل وكلكم ذلك الرجل فتأمل فإن فيه دقيقة"},{"id":"mutash-kirmani:261","bookId":"mutash-kirmani","type":"section","surah":16,"num":261,"title":"سورة النحل","page":"ج1 ص158","text":"قوله {وإذا قيل لهم ماذا أنزل ربكم قالوا أساطير الأولين} وبعده {وقيل للذين اتقوا ماذا أنزل ربكم قالوا خيرا} إنما رفع الأول لأنهم أنكروا إنزال القرآن فعدلوا عن الجواب فقالوا {أساطير الأولين} والثاني من كلام المتقين وهم مقرون بالوحى والإنزال فقالوا {خيرا} أي أنزل خيرا فيكون الجواب مطابقا وخيرا نصب بأنزل وإن شئت جعلت خيرا مفعول القول أي قالوا خيرا ولم يقولوا شرا كما قالت الكفار وإن شئت جعلت خيرا صفة مصدر محذوف أي قالوا قولا خيرا وقد ذكرت مثله ما زاد في موضعها"},{"id":"mutash-kirmani:262","bookId":"mutash-kirmani","type":"section","surah":16,"num":262,"title":"سورة النحل","page":"ج1 ص158","text":"قوله {فلبئس مثوى المتكبرين} ليس له في القرآن نظير الفاء للعطف على فاء التعقيب في قوله {فادخلوا أبواب جهنم} واللام للتأكيد يجري مجرى القسم موافقة لقوله {ولنعم دار المتقين} وليس له نظير وبينهما {ولدار الآخرة خير}"},{"id":"mutash-kirmani:263","bookId":"mutash-kirmani","type":"section","surah":16,"num":263,"title":"سورة النحل","page":"ج1 ص159","text":"قوله {فأصابهم سيئات ما عملوا} هنا وفي الجاثية 33 وفي غيرهما {ما كسبوا} لأن العمل أعم من الكسب ولهذا قال {فمن يعمل مثقال ذرة خيرا يره} {ومن يعمل مثقال ذرة شرا يره} وخصت هذه السورة لموافقة ما قبله وهو قوله {ما كنا نعمل من سوء بلى إن الله عليم بما كنتم تعملون} ولموافقة ما بعده وهو قوله {وتوفى كل نفس ما عملت} وفي الزمر 70 وليس لها نظير"},{"id":"mutash-kirmani:264","bookId":"mutash-kirmani","type":"section","surah":16,"num":264,"title":"سورة النحل","page":"ج1 ص159","text":"قوله {لو شاء الله ما عبدنا من دونه من شيء} قد سبق"},{"id":"mutash-kirmani:265","bookId":"mutash-kirmani","type":"section","surah":16,"num":265,"title":"سورة النحل","page":"ج1 ص159","text":"قوله {ولله يسجد من في السماوات} قد سبق أيضا"},{"id":"mutash-kirmani:266","bookId":"mutash-kirmani","type":"section","surah":16,"num":266,"title":"سورة النحل","page":"ج1 ص159","text":"قوله {ليكفروا بما آتيناهم فتمتعوا فسوف تعلمون} ومثله في الروم 34 وفي العنكبوت {وليتمتعوا فسوف يعلمون} باللام والياء أما التاء في السورتين فبإضمار القول أي قل لهم تمتعوا كما في قوله {قل تمتعوا فإن مصيركم إلى النار} وكذلك {قل تمتع بكفرك قليلا} وخصت هذه بالخطاب لقوله {إذا فريق منكم} وألحق ما في الروم به وأما في العنكبوت فعلى القياس عطف على اللام قبله وهي للغائب"},{"id":"mutash-kirmani:267","bookId":"mutash-kirmani","type":"section","surah":16,"num":267,"title":"سورة النحل","page":"ج1 ص160","text":"قوله {ولو يؤاخذ الله الناس بظلمهم ما ترك عليها من دابة} وفي الملائكة {بما كسبوا ما ترك على ظهرها} الهاء في هذه السورة كناية عن الأرض ولم يتقدم ذكرها والعرب تجوز ذلك في كلمات منها الأرض تقول فلان أفضل من عليها ومنها السماء تقول فلان أكرم من تحتها ومنها الغداء {تقول} إنها اليوم لباردة ومنها الأصابع تقول والذي شقهن خمسا من واحدة يعني الأصابع من اليد وإنما جوزوا ذلك لحصولها بين يدي كل متكلم وسامع ولما كان كناية عن غير مذكور ولم يزد معه الظهر لئلا يلتبس بالدابة لأن الظهر أكثر ما يستعمل في الدابة قال عليه الصلاة والسلام إن المنبت لا أرضا قطع ولا ظهرا أبقى وأما في الملائكة فقد تقدم ذكر الأرض في قوله {أو لم يسيروا في الأرض} وبعدها {ولا في الأرض} فكان كناية عن مذكور سابق فذكر الظهر حيث لا يلتبس قال الخطيب لما قال في النحل {بظلمهم} لم يقل على ظهرها احترازا عن الجمع بين الظاءين لأنها تقل في الكلام وليست لأمة من الأمم سوى العرب قال ولم يجئ في هذه السورة إلا في سبعة أحرف نحو الظلم والنظر والظل وظل وجهه والظهر والعظم والوعظ فلم يجمع بينهما في جملتين معقودتين عقد كلام واحد وهو لو وجوا به"},{"id":"mutash-kirmani:268","bookId":"mutash-kirmani","type":"section","surah":16,"num":268,"title":"سورة النحل","page":"ج1 ص161","text":"م قوله {فأحيا به الأرض بعد موتها} وفي العنكبوت {من بعد موتها} وكذلك حذف من قوله {لكيلا يعلم من بعد علم شيئا} وفي الحج {من بعد علم شيئا} لأنه أجمل الكلام في هذه السورة وفصل في الحج فقال {فإنا خلقناكم من تراب ثم من نطفة ثم من علقة ثم من مضغة} إلى قوله {ومنكم من يتوفى} فاقتضى الإجمال الحذف والتفصيل الإثبات فجاء في كل سورة بما اقتضاه الحال"},{"id":"mutash-kirmani:269","bookId":"mutash-kirmani","type":"section","surah":16,"num":269,"title":"سورة النحل","page":"ج1 ص161","text":"قوله {نسقيكم مما في بطونه} وفي المؤمنين {في بطونها} لأن الضمير في هذه السورة يعود إلى البعض وهو الإناث لأن اللبن لا يكون للكل فصار تقدير الآية وإن لكم في بعض الأنعام بخلاف ما في المؤمنين فإنه عطف عليه ما يعود على الكل ولا يقتصر على البعض وهو قوله {ولكم فيها منافع كثيرة ومنها تأكلون} {وعليها} ثم يحتمل أن يكون المراد البعض فأنث حملا على الأنعام وما قيل من أن الأنعام ههنا بمعنى النعم لأن الألف واللام تلحق الآحاد بالجمع وفي إلحاق الجمع بالآحاد حسن لكن الكلام وقع في التخصيص والوجه ما ذكرت والله أعلم"},{"id":"mutash-kirmani:270","bookId":"mutash-kirmani","type":"section","surah":16,"num":270,"title":"سورة النحل","page":"ج1 ص161","text":"قوله {وبنعمة الله هم يكفرون} وفي العنكبوت {يكفرون} بغير {هم} لأن في هذه السورة اتصل {والله جعل لكم من أنفسكم أزواجا وجعل لكم من أزواجكم بنين وحفدة ورزقكم من الطيبات} ثم عاد إلى الغيبة فقال {أفبالباطل يؤمنون وبنعمة الله هم يكفرون} فلا بد من تقييده بهم لئلا تلتبس الغيبة بالخطاب والتاء بالباء وما في العنكبوت اتصل بآيات استمرت على الغيبة فيها كلها فلم يحتج إلى تقييده بالضمير"},{"id":"mutash-kirmani:271","bookId":"mutash-kirmani","type":"section","surah":16,"num":271,"title":"سورة النحل","page":"ج1 ص162","text":"قوله {ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا إن ربك من بعدها لغفور رحيم} كرر {إن} وكذلك في الآية الأخرى {ثم إن ربك} لأن الكلام لما طال بصلته أعاد إن واسمها وثم وذكر الخبر ومثله {أيعدكم أنكم إذا متم وكنتم ترابا وعظاما أنكم مخرجون} أعاد أن واسمها لما طال الكلام"},{"id":"mutash-kirmani:272","bookId":"mutash-kirmani","type":"section","surah":16,"num":272,"title":"سورة النحل","page":"ج1 ص162","text":"قوله {ولا تك في ضيق مما} وفي النمل {ولا تكن} بإثبات النون هذه الكلمة كثر دورها في الكلام فحذف النون منها تخفيفا من غير قياس بل تشبيها بحروف العلة ويأتي ذلك في القرآن في بضع عشرة موضعا تسعة منها بالتاء وثمانية بالياء وموضعان بالنون وموضع بالهمزة وخصت هذه السورة بالحذف دون النمل موافقة لما قبلها وهو قوله {ولم يك من المشركين} والثاني إن هذه الآية نزلت تسلية للنبي صلى الله عليه وسلم حين قتل عمه حمزة ومثل به فقال عليه الصلاة والسلام لأفعلن بهم ولأصنعن فأنزل الله تعالى {ولئن صبرتم لهو خير للصابرين} {واصبر وما صبرك إلا بالله ولا تحزن عليهم ولا تك في ضيق مما يمكرون} فبالغ في الحذف ليكون ذلك مبالغة في التسلي وجاء في النمل على القياس ولأن الحزن هنا دون الحزن هناك"},{"id":"mutash-kirmani:273","bookId":"mutash-kirmani","type":"section","surah":17,"num":273,"title":"سورة الإسراء","page":"ج1 ص162","text":"قوله تعالى {ويبشر المؤمنين الذين يعملون الصالحات أن لهم أجرا كبيرا} وخصت"},{"id":"mutash-kirmani:274","bookId":"mutash-kirmani","type":"section","surah":18,"num":274,"title":"سورة الكهف","page":"ج1 ص163","text":"بقوله {أجرا حسنا} لأن الأجر في السورتين الجنة والكبير والحسن من أوصافها لكن خصت هذه السورة بالكبير موافقة لفواصل الآي قبلها وبعدها وهي {حصيرا} أليما 10 عجولا 11 وجلها وقع قبل آخرها مدة وكذلك في سورة الكهف جاء على ما تقتضيه الآيات قبلها وبعدها وهي {عوجا} {أبدا} {ولدا} وجلها قبل آخرها متحرك وأما رفع {يبشر} في سبحان ونصبها في الكهف فليس من المتشابه"},{"id":"mutash-kirmani:275","bookId":"mutash-kirmani","type":"section","surah":18,"num":275,"title":"سورة الكهف","page":"ج1 ص163","text":"قوله {لا تجعل مع الله إلها آخر فتقعد مذموما مخذولا} وقوله {ولا تجعل يدك مغلولة إلى عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا} وقوله {ولا تجعل مع الله إلها آخر فتلقى في جهنم ملوما مدحورا} فيها بعض المتشابه ويشبه التكرار وليس بتكرار لأن الأولى في الدنيا والثالثة في العقبى الثانية الخطاب فيها للنبي صلى الله عليه وسلم والمراد به غيره وذلك أن امرأة بعثت صبيا لها إليه مرة بعد أخرى تسأله قميصا ولم يكن عليه ولا له صلى الله عليه وسلم قميص غيره فنزعه ودفعه إليه فدخل وقت الصلاة فلم يخرج حياء فدخل عليه أصحابه فوجدوه على تلك الحالة فلاموه على ذلك فأنزل الله تعالى {فتقعد ملوما} يلومك الناس محسورا مكشوفا هذا هو الأظهر من تفسيره"},{"id":"mutash-kirmani:276","bookId":"mutash-kirmani","type":"section","surah":18,"num":276,"title":"سورة الكهف","page":"ج1 ص164","text":"قوله {ولقد صرفنا في هذا القرآن ليذكروا} وفي آخر السورة {ولقد صرفنا للناس في هذا القرآن} إنما لم يذكر في أول سبحان {للناس} لتقدم ذكرهم في السورة وذكرهم في آخر السورة 89 وذكرهم في الكهف إذ لم يجر ذكرهم لأن ذكر الإنس والجن جرى معا فذكر الناس كراهة الالتباس وقدمه على قوله {في هذا القرآن} كما قدمه في قوله {قل لئن اجتمعت الإنس والجن على أن يأتوا بمثل هذا القرآن لا يأتون بمثله} ثم قال {ولقد صرفنا للناس في هذا القرآن} وأما في الكهف فقدم {في هذا القرآن} لأن ذكره جل الغرض وذلك أن اليهود سألته عن قصة أصحاب الكهف وقصة ذي القرنين فأوحى الله إليه في القرآن فكان تقديمه في هذا الموضع أجدر والعناية بذكره أحرى"},{"id":"mutash-kirmani:277","bookId":"mutash-kirmani","type":"section","surah":18,"num":277,"title":"سورة الكهف","page":"ج1 ص164","text":"قوله {وقالوا أئذا كنا عظاما ورفاتا أئنا لمبعوثون خلقا جديدا}"},{"id":"mutash-kirmani:278","bookId":"mutash-kirmani","type":"section","surah":18,"num":278,"title":"سورة الكهف","page":"ج1 ص164","text":"ثم أعادها في أخر السورة بعينها من غير زيادة ولا نقصان 98 لأن هذا ليس بتكرار فإن الأول من كلامهم في الدنيا حين جادلوا الرسول وأنكروا البعث والثاني من كلام الله تعالى حين جازاهم على كفرهم وقولهم وإنكارهم البعث فقال {مأواهم جهنم كلما خبت زدناهم سعيرا} {ذلك جزاؤهم بأنهم كفروا بآياتنا وقالوا أئذا كنا عظاما ورفاتا أئنا لمبعوثون خلقا جديدا}"},{"id":"mutash-kirmani:279","bookId":"mutash-kirmani","type":"section","surah":18,"num":279,"title":"سورة الكهف","page":"ج1 ص165","text":"قوله {ذلك جزاؤهم بأنهم كفروا بآياتنا} وفي الكهف {ذلك جزاؤهم جهنم بما كفروا} اقتصر في هذه السورة على الإشارة لتقدم ذكر جهنم ولم يقتصر في الكهف على الإشارة دون العبارة لما اقترن بقوله { جنات} فقال {جزاؤهم جهنم بما كفروا} الآية ثم قال {إن الذين آمنوا وعملوا الصالحات كانت لهم جنات الفردوس نزلا} ليكون الوعد والوعيد كلاهما ظاهرين للمستمعين"},{"id":"mutash-kirmani:280","bookId":"mutash-kirmani","type":"section","surah":18,"num":280,"title":"سورة الكهف","page":"ج1 ص165","text":"قوله {قل ادعوا الذين زعمتم من دونه} وفي سبأ {ادعوا الذين زعمتم من دون الله} لأنه يعود إلى الرب في هذه السورة وقد تقدم ذكره في الآية الأولى وهو قوله {وربك أعلم} وفي سبأ لو ذكر بالكناية لكان يعود إلى الله كما صرح فعاد إليه وبينه وبين ذكره سبحانه صريحا أربع عشرة آية فلما طالت الآيات صرح ولم يكن"},{"id":"mutash-kirmani:281","bookId":"mutash-kirmani","type":"section","surah":18,"num":281,"title":"سورة الكهف","page":"ج1 ص165","text":"قوله {أرأيتك هذا الذي} وفي غيرها {أرأيت} لأن ترادف الخطاب يدل على أن المخاطب به أمر عظيم وخطب فظيع وهكذا هو في هذه السورة لأنه لعنه الله ضمن أخطال ذرية بني آدم عن آخرهم لا قليلا ومثل هذا {أرأيتكم} في الأنعام في موضعين وقد سبق"},{"id":"mutash-kirmani:282","bookId":"mutash-kirmani","type":"section","surah":18,"num":282,"title":"سورة الكهف","page":"ج1 ص166","text":"قوله {وما منع الناس أن يؤمنوا إذ جاءهم الهدى} وفي الكهف بزيادة {ويستغفروا ربهم} لأن ما في هذه السورة معناه ما منعهم عن الإيمان بمحمد صلى الله عليه وسلم إلا قولهم {أبعث الله بشرا رسولا} هلا بعث ملكا وجهلوا أن التجانس يورث التآنس والتغاير يورث التنافر وما في الكهف معناه ما منعهم عن الإيمان والاستغفار إلا إتيان سنة الأولين قال الزجاج إلا طلب سنة الأولين وهو قوله {إن كان هذا هو الحق من عندك فأمطر علينا حجارة} فزاد {ويستغفروا ربهم} لاتصاله بقوله {سنة الأولين} وهم قوم نوح وهود وصالح وشعيب كلهم أمروا بالاستغفار فنوح يقول {ويا قوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارا} وصالح يقول {فاستغفروه ثم توبوا إليه إن ربي قريب} وشعيب يقول {واستغفروا ربكم ثم توبوا إليه إن ربي رحيم ودود} فلما خوفهم سنة الأولين أجرى المخاطبين مجراهم"},{"id":"mutash-kirmani:283","bookId":"mutash-kirmani","type":"section","surah":18,"num":283,"title":"سورة الكهف","page":"ج1 ص166","text":"قوله {قل كفى بالله شهيدا بيني وبينكم} وفي العنكبوت {قل كفى بالله بيني وبينكم شهيدا} كما في الفتح {وكفى بالله شهيدا}"},{"id":"mutash-kirmani:284","bookId":"mutash-kirmani","type":"section","surah":18,"num":284,"title":"سورة الكهف","page":"ج1 ص166","text":"والرعد {قل كفى بالله شهيدا} ومثله {وكفى بالله نصيرا} {وكفى بالله حسيبا} فجاء في الرعد وسبحان على الأصل وفي العنكبوت أخر {شهيدا} لأنه لما وصفه بقوله {يعلم ما في السماوات والأرض} طال فلم يجز الفصل به"},{"id":"mutash-kirmani:285","bookId":"mutash-kirmani","type":"section","surah":18,"num":285,"title":"سورة الكهف","page":"ج1 ص167","text":"قوله {أولم يروا أن الله الذي خلق السماوات والأرض قادر} وفي الأحقاف {بقادر} وفي يس 81 لأن ما في هذه السورة خبر أن وما في يس خبر ليس فدخل الباء الخبر وكان القياس ألا يدخل في {حم} الأحقاف ولكنه شابه ليس لما ترادف النفي وهو قوله {أو لم يروا} { ولم يعي} وفي هذه السورة نفى واحد وأكثر أحكام المتشابه في العربية ثبت من وجهين قياسا على باب ما لا ينصرف وغيره"},{"id":"mutash-kirmani:286","bookId":"mutash-kirmani","type":"section","surah":18,"num":286,"title":"سورة الكهف","page":"ج1 ص167","text":"قوله {إني لأظنك يا موسى مسحورا} قابل موسى عليه السلام كل كلمة من فرعون بكلمة من نفسه فقال {وإني لأظنك يا فرعون مثبورا}"},{"id":"mutash-kirmani:287","bookId":"mutash-kirmani","type":"section","surah":18,"num":287,"title":"سورة الكهف","page":"ج1 ص168","text":"قوله تعالى {سيقولون ثلاثة رابعهم كلبهم ويقولون خمسة سادسهم كلبهم} بغير واو {ويقولون سبعة وثامنهم كلبهم} بزيادة واو في هذه الواو أقوال إحداها أن الأول والثاني وصفان لما قبلها أي هم ثلاثة وكذلك الثاني أي هم خمسة سادسهم كلبهم والثالث عطف على ما قبله أي هم سبعة عطف عليه {وثامنهم كلبهم} وقيل كل واحد من الثلاثة جملة وقعت بعدها جملة وكل جملة وقعت بعدها جملة فيها عائد يعود منها إليها فأنت في إلحاق واو العطف وحذفها بالخيار وليس في هذين القولين ما يوجب تخصيص الثالث بالواو وقال بعض النحويين السبعة نهاية العدد ولهذا كثر ذكرها في القرآن والأخبار والثمانية تجري مجرى استئناف كلام ومن هنا لقبه جماعة من المفسرين بواو الثمانية واستدلوا بقوله سبحانه {التائبون العابدون الحامدون} إلى {والناهون عن المنكر} الآية وبقوله {مسلمات مؤمنات قانتات} إلى {ثيبات وأبكارا} الآية وبقوله {وفتحت أبوابها} وزعموا أن هذه الواو تدل على أن أبوابها ثمانية ولكل واحد من هذه الآيات وجوه ذكرتها في موضعها وقيل إن الله حكى القولين الأولين ولم يرضهما وحكى القول الثالث فارتضاه وهو قوله {ويقولون سبعة} ثم استأنف فقال {وثامنهم كلبهم} ولهذا عقب الأول والثاني بقوله {رجما بالغيب} ولم يقل في الثالث فإن قيل وقد قال في الثالث {قل ربي أعلم بعدتهم} فالجواب تقديره قل ربي أعلم بعدتهم وقد أخبركم أنهم سبعة وثامنهم كلبهم بدليل قوله {ما يعلمهم إلا قليل} ولهذا قال ابن عباس أنا من ذلك القليل فعد أسماءهم وقال بعضهم الواو في قوله {ويقولون سبعة} يعود إلى الله تعالى فذكر بلفظ الجمع كقوله {أما} وأمثاله هذا على الاختصار"},{"id":"mutash-kirmani:288","bookId":"mutash-kirmani","type":"section","surah":18,"num":288,"title":"سورة الكهف","page":"ج1 ص168","text":"قوله {ولئن رددت إلى ربي} وفي حم فصلت {ولئن رجعت إلى ربي} لأن الرد عن الشيء يتضمن كراهة المردود ولما كان في الكهف تقديره ولئن رددت عن جنتي هذه التي أظن ألا تبيد أبدا إلى ربي كان لفظ الرد الذي يتضمن الكراهة أولى وليس في حم ما يدل على الكراهة فذكر بلفظ الرجع ليقع في كل سورة ما يليق بها"},{"id":"mutash-kirmani:289","bookId":"mutash-kirmani","type":"section","surah":18,"num":289,"title":"سورة الكهف","page":"ج1 ص169","text":"قوله {ومن أظلم ممن ذكر بآيات ربه فأعرض عنها} وفي السجدة {ثم أعرض عنها} لأن الفاء للتعقيب وثم للتراخي وما في هذه السورة في الأحياء من الكفار إذ ذكروا فأعرضوا عقيب ما ذكروا ونسوا ذنوبهم وهم بعد متوقع منهم أن يؤمنوا وما في السجدة في الأموات من الكفار بدليل قوله {ولو ترى إذ المجرمون ناكسو رؤوسهم عند ربهم} أي ذكروا مرة بعد أخرى وزمانا بعد زمان ثم أعرضوا عنها بالموت فلم يؤمنوا وانقطع رجاء إيمانهم"},{"id":"mutash-kirmani:290","bookId":"mutash-kirmani","type":"section","surah":18,"num":290,"title":"سورة الكهف","page":"ج1 ص169","text":"قوله {نسيا حوتهما فاتخذ سبيله} وفي الآية الثالثة {واتخذ سبيله} لأن الفاء للتعقيب والعطف فكان اتخاذ الحوت للسبيل عقيب النسيان فذكر بالفاء وفي الآية الأخرى لما حيل بينهما بقوله {وما أنسانيه إلا الشيطان أن أذكره} زال معنى التعقيب وبقي العطف المجرد وحرفه الواو"},{"id":"mutash-kirmani:291","bookId":"mutash-kirmani","type":"section","surah":18,"num":291,"title":"سورة الكهف","page":"ج1 ص169","text":"قوله {لقد جئت شيئا إمرا} وبعده {لقد جئت شيئا نكرا}"},{"id":"mutash-kirmani:292","bookId":"mutash-kirmani","type":"section","surah":18,"num":292,"title":"سورة الكهف","page":"ج1 ص169","text":"لأن الأمر العجب والمعجب والعجب يستعمل في الخير والشر بخلاف النكر لأن ما ينكره العقل فهو شر وخرق السفينة لم يكن معه غرق فكان أسهل من قتل الغلام وإهلاكه فصار لكل واحد معنى يخصه"},{"id":"mutash-kirmani:293","bookId":"mutash-kirmani","type":"section","surah":18,"num":293,"title":"سورة الكهف","page":"ج1 ص169","text":"قوله {ألم أقل إنك} وبعده {ألم أقل لك إنك} لأن الإنكار في الثانية أكثر وقيل أكد التقدير الثاني بقوله لك كما تقول لمن توبخه لك أقول وإياك أعني وقيل بين في الثاني المقول له لما لم يبين في الأول"},{"id":"mutash-kirmani:294","bookId":"mutash-kirmani","type":"section","surah":18,"num":294,"title":"سورة الكهف","page":"ج1 ص170","text":"قوله في الأول {فأردت أن أعيبها} وفي الثاني {فأردنا أن يبدلهما ربهما} وفي الثالث {فأراد ربك أن يبلغا أشدهما} لأن الأول في الظاهر إفساد فأسنده إلى نفسه والثالث إنعام محض فأسنده إلى الله عز وجل والثاني إفساد من حيث القتل إنعام من حيث التأويل فأسنده إلى نفسه وإلى الله عز وجل وقيل القتل كان منه وإزهاق الروح كان من الله سبحانه قوله {ما لم تسطع عليه صبرا} جاء في الأول على الأصل وفي الثاني {تستطع عليه صبرا} على التخفيف لأنه الفرع"},{"id":"mutash-kirmani:295","bookId":"mutash-kirmani","type":"section","surah":18,"num":295,"title":"سورة الكهف","page":"ج1 ص170","text":"قوله {فما اسطاعوا أن يظهروه وما استطاعوا له نقبا} اختار التخفيف في الأول لأن مفعوله حرف وفعل وفاعل ومفعول فاختار فيه الحذف والثاني مفعوله اسم واحد وهو قوله {نقبا} وقرأ حمزة بالتشديد وأدعم التاء في الطاء في الشواذ فما استطاعوا بفتح الهمزة وزنه استفعلوا ومثلها استخذ فلان أرضا أي أخذ أرضا وزنه استفعل ومن أهراق ووزنه استفعل وقيل استعمل من وجهين وقيل السين بدل التاء ووزنه افتعل"},{"id":"mutash-kirmani:296","bookId":"mutash-kirmani","type":"section","surah":19,"num":296,"title":"سورة مريم","page":"ج1 ص171","text":"قوله {ولم يكن جبارا عصيا} وبعده {ولم يجعلني جبارا شقيا} لأن الأول في حق يحيى وجاء في الخبر عن النبي صلى الله عليه وسلم ما من أحد من بني آدم إلا أذنب أو هم بذنب إلا يحيى ابن زكريا عليهما السلام فنفى عنه العصيان والثاني في عيسى عليه السلام فنفى عنه الشقاوة وأثبت له السعادة والأنبياء عندنا معصومون عن الكبائر غير معصومين عن الصغائر"},{"id":"mutash-kirmani:297","bookId":"mutash-kirmani","type":"section","surah":19,"num":297,"title":"سورة مريم","page":"ج1 ص172","text":"قوله {وسلام عليه يوم ولد} في قصة يحيى {والسلام علي} في قصة عيسى فنكر في الأول وعرف في الثاني لأن الأول من الله تعالى والقليل منه كثير كما قال الشاعر قليل منك يكفيني ولكن قليل لا يقال له قليل ولهذا قرأ الحسن {اهدنا صراطا مستقيما} أي نحن راضون منك بالقليل ومثل هذا في الشعر كثير قال وأني لراض منك يا هند بالذي لو أبصره الواشي لقرت بلابله ... بلا وبأن لا أستطيع وبالمى وبالوعد حتى يسأم الوعد آمله والثاني من عيسى عليه السلام والألف واللام لاستغراق الجنس ولو أدخل عليه التسعة والعشرين والفروع المستحسنة والمستقبحة لم تبلغ عشر معشار سلام الله عليه ويجوز أن يكون ذلك وحيا من الله عز وجل فيقرب من سلام يحيى وقيل إنما دخل الألف واللام لأن النكرة إذا تكررت تعرفت وقيل نكرة الجنس ومعرفته سواء تقول لا أشرب ماء ولا أشرب الماء فهما سواء"},{"id":"mutash-kirmani:298","bookId":"mutash-kirmani","type":"section","surah":19,"num":298,"title":"سورة مريم","page":"ج1 ص172","text":"قوله {فاختلف الأحزاب من بينهم فويل للذين كفروا} وفي حم الزخرف {فويل للذين ظلموا} لأن الكفر أبلغ من الظلم وقصة عيسى في هذه السورة مشروحة وفيها ذكر نسبتهم إياه إلى الله تعالى حين قال {ما كان لله أن يتخذ من ولد} فذكر بلفظ الكفر وقصته في الزخرف مجملة فوصفهم بلفظ دونه وهو الظلم"},{"id":"mutash-kirmani:299","bookId":"mutash-kirmani","type":"section","surah":19,"num":299,"title":"سورة مريم","page":"ج1 ص172","text":"قوله {وعمل صالحا} وفي الفرقان {وعمل عملا صالحا} لأن في هذه السورة أوجز في ذكر المعاصي فأوجز في التوبة وأطال هناك فأطال"},{"id":"mutash-kirmani:300","bookId":"mutash-kirmani","type":"section","surah":20,"num":300,"title":"سورة طه","page":"ج1 ص173","text":"قوله تبارك وتعالى {وهل أتاك حديث موسى} {إذ رأى نارا فقال لأهله امكثوا إني آنست نارا لعلي آتيكم منها بقبس أو أجد على النار هدى} وفي النمل {إذ قال موسى لأهله إني آنست نارا سآتيكم منها بخبر أو آتيكم بشهاب قبس لعلكم تصطلون} وفي القصص {فلما قضى موسى الأجل وسار بأهله آنس من جانب الطور نارا قال لأهله امكثوا إني آنست نارا لعلي آتيكم منها بخبر أو جذوة من النار لعلكم تصطلون} هذه الآيات تشتمل على ذكر رؤية موسى النار وأمره أهله بالمكث وإخباره إياهم أنه آنس نارا وإطماعهم أن يأتيهم بنار يصطلون بها أو بخبر يهتدون به إلى الطريق التي ضلوا عنها لكنه نقص في النمل ذكر رؤيته النار وأمر أهله بالمكث اكتفاء بما تقدم وزاد في القصص قضاء موسى الأجل المضروب وسيره بأهله إلى مصر لأن الشيء قد يجمل ثم يفصل وقد يفصل ثم يجمل وفي طه فصل وأجمل في النمل ثم فصل في القصص وبالغ فيه وقوله في طه {أو أجد على النار هدى} أي من يخبرني بالطريق فيهديني إليه وإنما أخر ذكر المخبر فيهما وقدمه فيهما مرات لفواصل الآي وكرر {لعلي} في القصص لفظا وفيهما معنى لأن أو في قوله {أو أجد على النار هدى} نائب عن {لعلي} {آتيكم} تتضمن معنى لعلي وفي القصص {أو جذوة من النار} وفي النمل {بشهاب قبس} وفي طه {بقبس} لأن الجذوة من النار خشية في رأسها قبس لها شهاب فهي في السور الثلاث عبارة عن معبر واحد"},{"id":"mutash-kirmani:301","bookId":"mutash-kirmani","type":"section","surah":20,"num":301,"title":"سورة طه","page":"ج1 ص173","text":"قوله {فلما أتاها} هنا وفي النمل {فلما جاءها} وفي القصص {أتاها} لأن أتى وجاء بمعنى واحد لكن كثر دور الإتيان في طه نحو {فأتياه} {فلنأتينك} {ثم أتى} {ثم ائتوا} {حيث أتى} ولفظ {جاء} في النمل أكثر نحو {فلما جاءتهم} {وجئتك} {فلما جاء سليمان} وألحق القصص بطه لقرب ما بينهما"},{"id":"mutash-kirmani:302","bookId":"mutash-kirmani","type":"section","surah":20,"num":302,"title":"سورة طه","page":"ج1 ص174","text":"قوله {فرجعناك إلى أمك} وفي القصص {فرددناه} لأن الرجع إلى الشيء والرد إليه بمعنى والرد على الشيء يقتضي كراهة المردود ولفظ الرجع ألطف فخص بطه وخص القصص بقوله {فرددناه} تصديقا لقوله {إنا رادوه إليك}"},{"id":"mutash-kirmani:303","bookId":"mutash-kirmani","type":"section","surah":20,"num":303,"title":"سورة طه","page":"ج1 ص174","text":"قوله {وسلك لكم فيها سبلا} وفي الزخرف {وجعل} لأن لفظ السلوك مع السبيل أكثر استعمالا به فخص به طه وخص الزخرف بجعل ازدواجا للكلام وموافقة لما قبلها وما بعدها"},{"id":"mutash-kirmani:304","bookId":"mutash-kirmani","type":"section","surah":20,"num":304,"title":"سورة طه","page":"ج1 ص174","text":"قوله {إلى فرعون} وفي الشعراء {أن ائت القوم الظالمين} {قوم فرعون ألا يتقون} وفي القصص {فذانك برهانان من ربك إلى فرعون وملئه} لأن طه هي السابقة وفرعون هو الأصل المبعوث إليه وقومه تبع له وهو كالمذكورين معه وفي الشعراء {قوم فرعون} أي قوم فرعون وفرعون فاكتفى بذكره في الإضافة عن ذكره مفردا ومثله {وأغرقنا آل فرعون} أي آل فرعون وفرعون وفي القصص {إلى فرعون وملئه} فجمع بين الآيتين فصار كذكر الجملة بعد التفصيل"},{"id":"mutash-kirmani:305","bookId":"mutash-kirmani","type":"section","surah":20,"num":305,"title":"سورة طه","page":"ج1 ص175","text":"قوله {واحلل عقدة من لساني} صرح بالعقدة في هذه السورة لأنها السابقة وفي الشعراء {ولا ينطلق لساني} كناية عن العقدة بما يقرب من التصريح وفي القصص {وأخي هارون هو أفصح مني لسانا} فكنى عن العقدة كناية مبهمة لأن الأول يدل على ذلك"},{"id":"mutash-kirmani:306","bookId":"mutash-kirmani","type":"section","surah":20,"num":306,"title":"سورة طه","page":"ج1 ص175","text":"قوله في الشعراء {ولهم علي ذنب فأخاف أن يقتلون} وفي القصص {إني قتلت منهم نفسا فأخاف أن يقتلون} وليس له في طه ذكره لأن قوله {ويسر لي أمري} مشتمل على ذلك وغيره لأن الله عز وجل إذا يسر له أمره فلن يخاف القتل"},{"id":"mutash-kirmani:307","bookId":"mutash-kirmani","type":"section","surah":20,"num":307,"title":"سورة طه","page":"ج1 ص175","text":"قوله {واجعل لي وزيرا من أهلي} {هارون أخي} صرح بالوزير لأنها الأولى في الذكر وكنى عنه في الشعراء حيث قال {فأرسل إلى هارون} ليأتيني فيكون لي وزيرا وفي القصص {فأرسله معي ردءا يصدقني} أي اجعله لي وزيرا فكنى عنه بقوله {ردءا} لبيان الأول"},{"id":"mutash-kirmani:308","bookId":"mutash-kirmani","type":"section","surah":20,"num":308,"title":"سورة طه","page":"ج1 ص175","text":"قوله {فقولا إنا رسولا ربك} وبعده {إنا رسول رب العالمين} لأن الرسول مصدر يسمى به فحيث وحده حمله على المصدر وحيث ثنى حمل على الاسم ويجوز أن يقال حيث وحد حمل على الرسالة لأنهما رسلا لشيء واحد وحيث ثنى حمل على الشخصين وأكثر ما فيه من المتشابه سبق"},{"id":"mutash-kirmani:309","bookId":"mutash-kirmani","type":"section","surah":20,"num":309,"title":"سورة طه","page":"ج1 ص175","text":"قوله {أفلم يهد لهم كم أهلكنا قبلهم من القرون} بالفاء من غير {من} وفي السجدة 26 بالواو وبعده {من} لأن الفاء للتعقيب والاتصال بالأول فطال الكلام فحسن حذف {من} والواو تدل على الاستئناف وإثبات {من} مستثقل وقد سبق الفرق بين إثباته وحذفه"},{"id":"mutash-kirmani:310","bookId":"mutash-kirmani","type":"section","surah":21,"num":310,"title":"سورة الأنبياء","page":"ج1 ص176","text":"قوله تعالى {ما يأتيهم من ذكر من ربهم محدث} وفي الشعراء {وما يأتيهم من ذكر من الرحمن محدث} خصت هذه السورة بقوله {من ربهم} بالإضافة لأن الرحمن لم يأت مضافا ولموافقته ما بعد وهو قوله {قال ربي يعلم} وخصت الشعراء بقوله {من الرحمن} لتكون كل سورة مخصوصة بوصف من أوصافه وليس في أوصاف الله اسم أشبه باسم الله من الرحمن لأنهما اسمان ممنوعان أن يسمى بهما غير الله عز وجل ولموافقة ما بعده وهو قوله {لهو العزيز الرحيم} لأن الرحمن الرحيم مصدر واحد"},{"id":"mutash-kirmani:311","bookId":"mutash-kirmani","type":"section","surah":21,"num":311,"title":"سورة الأنبياء","page":"ج1 ص176","text":"قوله {وما أرسلنا قبلك إلا رجالا} وبعده {وما أرسلنا من قبلك} كلاهما لاستيعاب الزمان المتقدم إلا أن {من} إذا دخل دل على الحصر بين الحدين وضبطه بذكر الطرفين ولم يأت {وما أرسلنا قبلك} إلا هذه وخصت بالحذف لأن قبلها {ما آمنت قبلهم من قرية} فبناه عليه لأنه هو وأخر {من} في الفرقان {وما أرسلنا قبلك من المرسلين إلا إنهم} وزاد في الثاني {من قبلك من رسول} على الأصل للحصر"},{"id":"mutash-kirmani:312","bookId":"mutash-kirmani","type":"section","surah":21,"num":312,"title":"سورة الأنبياء","page":"ج1 ص177","text":"قوله {كل نفس ذائقة الموت ونبلوكم بالشر والخير فتنة وإلينا ترجعون} وفي العنكبوت {ثم إلينا ترجعون} لأن ثم للتراخي والرجوع هو الرجوع إلى الجنة أو النار وذلك في القيامة فخصت سورة العنكبوت به وخصت هذه السورة بالواو لما حيل بين الكلامين بقوله {ونبلوكم بالشر والخير فتنة} وإنما ذكرا لتقدم ذكرهما فقام مقام التراخي وناب بالواو منابه"},{"id":"mutash-kirmani:313","bookId":"mutash-kirmani","type":"section","surah":21,"num":313,"title":"سورة الأنبياء","page":"ج1 ص177","text":"قوله {وإذا رآك الذين كفروا إن يتخذونك إلا هزوا} وفي الفرقان {وإذا رأوك إن يتخذونك إلا هزوا} لأنه ليس في هذه الآية التي تقدمتها ذكر الكفار هنا فصرح باسمهم وفي الفرقان قد سبق ذكر الكفار فخص الإظهار بهذه السورة والكناية بتلك"},{"id":"mutash-kirmani:314","bookId":"mutash-kirmani","type":"section","surah":21,"num":314,"title":"سورة الأنبياء","page":"ج1 ص177","text":"قوله {ما هذه التماثيل التي أنتم لها عاكفون} {قالوا وجدنا آباءنا} وفي الشعراء {قالوا بل وجدنا} بزيادة {بل} لأن قوله {وجدنا آباءنا} جواب لقوله {ما هذه التماثيل} وفي الشعراء أجابوا عن قوله {ما تعبدون} بقولهم {نعبد أصناما} ثم قال {هل يسمعونكم إذ تدعون} {أو ينفعونكم أو يضرون} فأتى بصورة الاستفهام ومعناه النفي قالوا {بل وجدنا} أي قالوا لا بل وجدنا عليه آباءنا لأن السؤال في الآية يقتضي في جوابهم أن ينفوا ما نفاه السائل فأضربوا عنه إضراب من ينفي الأول ويثبت الثاني فقالوا بل وجدنا فخصت السورة به"},{"id":"mutash-kirmani:315","bookId":"mutash-kirmani","type":"section","surah":21,"num":315,"title":"سورة الأنبياء","page":"ج1 ص178","text":"قوله {وأرادوا به كيدا فجعلناهم الأخسرين} وفي الصافات {الأسفلين} لأن في هذه السورة كادهم إبراهيم عليه السلام بقوله {لأكيدن أصنامكم} وكادوا هم إبراهيم بقوله {وأرادوا به كيدا} فجرت بينهم مكايده فغلهم إبراهيم لأنه كسر أصنامهم ولم يغلبوه لأنهم لم يبلغوا من إحراقه مرادهم فكانوا هم الأخسرين وفي الصافات {قالوا ابنوا له بنيانا فألقوه في الجحيم} فأججوا نارا عظيمة وبنوا بنيانا عاليا ورفعوه إليه ورموه منه إلى أسفل فرفعه الله وجعلهم في الدنيا من الأسفلين وردهم في العقبى أسفل سافلين فخصت الصافات بالأسفلين"},{"id":"mutash-kirmani:316","bookId":"mutash-kirmani","type":"section","surah":21,"num":316,"title":"سورة الأنبياء","page":"ج1 ص178","text":"قوله {ونجيناه} بالفاء سبق في يونس ومثله في الشعراء {فنجيناه وأهله أجمعين} {إلا عجوزا في الغابرين}"},{"id":"mutash-kirmani:317","bookId":"mutash-kirmani","type":"section","surah":21,"num":317,"title":"سورة الأنبياء","page":"ج1 ص178","text":"قوله {وأيوب إذ نادى ربه} ختم القصة بقوله {رحمة من عندنا} وقال في ص {رحمة منا} لأنه هنا بالغ في التضرع بقوله {وأنت أرحم الراحمين} فبالغ سبحانه في الإجابة وقال {رحمة من عندنا} لأن عند حيث جاء دل على أن الله سبحانه تولى ذلك من غير واسطة وفي ص لما بدأ القصة بقوله {واذكر عبدنا} ختم بقوله {منا} ليكون آخر الآية لفقا بالأول الآية"},{"id":"mutash-kirmani:318","bookId":"mutash-kirmani","type":"section","surah":21,"num":318,"title":"سورة الأنبياء","page":"ج1 ص178","text":"قوله {فاعبدون} {وتقطعوا} وفي المؤمنين {فاتقون} {فتقطعوا} لأن الخطاب في هذه السورة للكفار فأمرهم بالعبادة التي هي التوحيد ثم قال {وتقطعوا} بالواو لأن التقطع قد كان منهم قبل هذا القول لهم ومن جملة خطاب المؤمنين فمعناه داوموا على الطاعة وفي المؤمنين الخطاب للنبي صلى الله عليه وسلم وللمؤمنين بدليل قوله {يا أيها الرسل كلوا من الطيبات} والأنبياء والمؤمنون مأمورون بالتقوى ثم قال {فتقطعوا أمرهم} أي ظهر منهم التقطع بعد هذا القول والمراد أممهم"},{"id":"mutash-kirmani:319","bookId":"mutash-kirmani","type":"section","surah":21,"num":319,"title":"سورة الأنبياء","page":"ج1 ص179","text":"قوله {والتي أحصنت فرجها فنفخنا فيها} وفي التحريم {فنفخنا فيه} لأن المقصود في هذه السورة ذكرها وما آل إليه أمرها حتى ظهر فيها ابنها وصارت هي وابنها آية وذلك لا يكون إلا بالنفخ في حملها وتحملها والاستمرار على ذلك إلى ولادتها فلهذا اختصت بالتأنيث وما في التحريم مقصور على ذكر إحصانها وتصديقها بكلمات ربها وكأن النفخ أصاب فرجها وهو مذكر والمراد به فرج الجيب أو غيره فخصت بالتذكير"},{"id":"mutash-kirmani:320","bookId":"mutash-kirmani","type":"section","surah":22,"num":320,"title":"سورة الحج","page":"ج1 ص179","text":"قوله تعالى {يوم ترونها} وبعده {وترى الناس سكارى} محول على أيها المخاطب كما سبق في قوله {وترى الفلك}"},{"id":"mutash-kirmani:321","bookId":"mutash-kirmani","type":"section","surah":22,"num":321,"title":"سورة الحج","page":"ج1 ص179","text":"قوله {ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير} في هذه السورة وفي لقمان {ولا هدى ولا كتاب منير} لأن ما في هذه السورة وافق ما قبلها من الآيات وهي {قدير} {القبور} وكذلك في لقمان وافق ما قبلها وما بعدها وهي {الحمير} {السعير} {الأمور}"},{"id":"mutash-kirmani:322","bookId":"mutash-kirmani","type":"section","surah":22,"num":322,"title":"سورة الحج","page":"ج1 ص179","text":"قوله {من بعد علم شيئا} بزيادة {من} لقوله تعالى {من تراب ثم من نطفة} الآية وقد سبق في النحل"},{"id":"mutash-kirmani:323","bookId":"mutash-kirmani","type":"section","surah":22,"num":323,"title":"سورة الحج","page":"ج1 ص179","text":"قوله {ذلك بما قدمت يداك} وفي غيرها {أيديكم} لأن هذه الآية نزلت في النضر بن الحارث وقيل في أبي جهل فوحده وفي غيرها نزلت في الجماعة التي تقدم ذكرهم"},{"id":"mutash-kirmani:324","bookId":"mutash-kirmani","type":"section","surah":22,"num":324,"title":"سورة الحج","page":"ج1 ص180","text":"قوله {إن الذين آمنوا والذين هادوا والصابئين والنصارى} قدم الصابئين لتقدم زمانهم وقد تقدم في البقرة"},{"id":"mutash-kirmani:325","bookId":"mutash-kirmani","type":"section","surah":22,"num":325,"title":"سورة الحج","page":"ج1 ص180","text":"قوله {يسجد له من في السماوات} سبق في الرعد"},{"id":"mutash-kirmani:326","bookId":"mutash-kirmani","type":"section","surah":22,"num":326,"title":"سورة الحج","page":"ج1 ص180","text":"قوله {كلما أرادوا أن يخرجوا منها من غم أعيدوا فيها} وفي السجدة {منها أعيدوا فيها} لأن المراد بالغم الكرب والأخذ بالنفس حتى لا يجد صاحبه متنفسا وما قبله من الآيات يقتضي ذلك وهو {قطعت لهم ثياب من نار} إلى قوله {من حديد} فمن كان في ثياب من نار وفوق رأسه حميم يذوب من حره أحشاء بطنه حتى يذوب ظاهر جلده وعليه موكلون يضربونه بمقامع من حديد كيف يجد سرورا أو يجد متنفسا من تلك الكرب التي عليه وليس في السجدة من هذا ذكر وإنما قبلها {فمأواهم النار كلما أرادوا أن يخرجوا منها أعيدوا فيها}"},{"id":"mutash-kirmani:327","bookId":"mutash-kirmani","type":"section","surah":22,"num":327,"title":"سورة الحج","page":"ج1 ص180","text":"قوله {وذوقوا} وفي السجدة {وقيل لهم ذوقوا} القول ههنا مضمر وخص بالإضمار لطول الكلام بوصف العذاب وخصت السجدة بالإظهار موافقة للقول قبله في مواضع منها {أم يقولون افتراه} {وقالوا أئذا ضللنا} و {قل يتوفاكم} و {حق القول} وليس في الحج شيء منه"},{"id":"mutash-kirmani:328","bookId":"mutash-kirmani","type":"section","surah":22,"num":328,"title":"سورة الحج","page":"ج1 ص181","text":"قوله {إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار} مكررة وموجب هذا التكرار قوله {هذان خصمان} لأنه لما ذكر أحد الخصمين وهو {فالذين كفروا قطعت لهم ثياب من نار} لم يكن بد من ذكر الخصم الآخر فقال {إن الله يدخل الذين آمنوا وعملوا الصالحات} الآية"},{"id":"mutash-kirmani:329","bookId":"mutash-kirmani","type":"section","surah":22,"num":329,"title":"سورة الحج","page":"ج1 ص181","text":"قوله {وطهر بيتي للطائفين والقائمين} وفي البقرة {للطائفين والعاكفين} وحقه أن يذكر هناك لأن ذكر العاكف ههنا سبق في قوله {سواء العاكف فيه والباد} ومعنى {والقائمين والركع السجود} المصلون وقيل القائمون بمعنى المقيمين وهم العاكفون لكن لما تقدم ذكرهم عبر عنهم بعبارة أخرى"},{"id":"mutash-kirmani:330","bookId":"mutash-kirmani","type":"section","surah":22,"num":330,"title":"سورة الحج","page":"ج1 ص181","text":"قوله {فكلوا منها وأطعموا القانع والمعتر} كرر لأن الأول متصل بكلام إبراهيم وهو اعتراض ثم أعاده مع قوله {والبدن جعلناها لكم}"},{"id":"mutash-kirmani:331","bookId":"mutash-kirmani","type":"section","surah":22,"num":331,"title":"سورة الحج","page":"ج1 ص181","text":"قوله {فكأين من قرية أهلكناها} وبعده {وكأين من قرية أمليت لها} خص الأول بذكر الإهلاك لاتصاله بقوله {فأمليت للذين كفروا ثم أخذتهم} أي أهلكتهم والثاني بالإملاء لأن قبله {ويستعجلونك بالعذاب} فحسن ذكر الإملاء"},{"id":"mutash-kirmani:332","bookId":"mutash-kirmani","type":"section","surah":22,"num":332,"title":"سورة الحج","page":"ج1 ص182","text":"قوله {وأن ما يدعون من دونه هو الباطل} وفي سورة لقمان {من دونه الباطل} لأن في هذه السورة وقع بعد عشر آيات كل آية مؤكدة مرة أو مرتين ولهذا أيضا زيد في السورة اللام في قوله {وإن الله لهو الغني الحميد} وفي لقمان {إن الله هو الغني الحميد} إذ لم تكن سورة لقمان بهذه الصفة وإن شئت قلت لما تقدم في هذه السورة ذكر الله سبحانه وذكر الشيطان أكدهما فإنه خبر وقع بين خبرين ولم يتقدم في لقمان ذكر الشيطان فأكد ذكر الله تعالى وأهمل ذكر شيطان وهذه دقيقة"},{"id":"mutash-kirmani:333","bookId":"mutash-kirmani","type":"section","surah":22,"num":333,"title":"سورة الحج","page":"ج1 ص182","text":"قوله تبارك وتعالى {لكم فيها فواكه كثيرة ومنها تأكلون} بالجمع وبالواو وفي الزخرف فاكهة 73 على التوحيد {منها تأكلون} بغير واو راعى في السورتين لفظ الجنة فكانت هذه جنات بالجمع فقال {فواكه} بالجمع وفي الزخرف {وتلك الجنة} بلفظ التوحيد وإن كانت هذه جنة الخلد لكن راعى اللفظ فقال {فيها فاكهة} وقال في هذه السورة {ومنها تأكلون} بزيادة الواو لأن تقدير الآية منها تدخرون ومنها تبيعون وليس كذلك فاكهة الجنة فإنها للأكل فحسب فلذلك قال في الزخرف {منها تأكلون} ووافق هذه السورة ما بعدها أيضا وهو قوله {ولكم فيها منافع كثيرة ومنها تأكلون} فهذا القرآن معجزة وبرهان"},{"id":"mutash-kirmani:334","bookId":"mutash-kirmani","type":"section","surah":22,"num":334,"title":"سورة الحج","page":"ج1 ص182","text":"قوله {فقال الملأ الذين كفروا من قومه} وبعده {وقال الملأ من قومه الذين كفروا وكذبوا بلقاء الآخرة وأترفناهم في الحياة الدنيا}"},{"id":"mutash-kirmani:335","bookId":"mutash-kirmani","type":"section","surah":22,"num":335,"title":"سورة الحج","page":"ج1 ص183","text":"فقدم {من قومه} في الآية الأخرى وفي الأولى أخر لأن صلة {الذين} في الأولى اقتصرت على الفعل وضمير الفاعل ثم ذكر بعده الجار والمجرور ثم ذكر المفعول وهو المقول وليس كذلك في الأخرى فإن صلة الموصول طالت بذكر الفاعل والمفعول والعطف عليه مرة بعد أخرى فقدم الجار والمجرور ولأن تأخيره ملتبس وتوسطه ركيك فخص بالتقديم"},{"id":"mutash-kirmani:336","bookId":"mutash-kirmani","type":"section","surah":22,"num":336,"title":"سورة الحج","page":"ج1 ص183","text":"قوله {ولو شاء الله لأنزل ملائكة} وفي حم فصلت {لو شاء ربنا لأنزل ملائكة} لأن في هذه السورة تقدم ذكر الله وليس فيه ذكر الرب وفي فصلت تقدم ذكر رب العالمين سابقا على ذكر الله فصرح في هذه السورة بذكر الله وهناك بذكر الرب لإضافته إلى العالمين وهم جملتهم فقالوا إما اعتقادا وإما استهزاء {لو شاء ربنا لأنزل ملائكة} فأضافوا الرب إليهم"},{"id":"mutash-kirmani:337","bookId":"mutash-kirmani","type":"section","surah":22,"num":337,"title":"سورة الحج","page":"ج1 ص183","text":"قوله {واعملوا صالحا إني بما تعملون عليم} وفي سبأ {إني بما تعملون بصير} كلاهما من وصف الله سبحانه وتعالى وخص كل سورة بما وافق فواصل الآى"},{"id":"mutash-kirmani:338","bookId":"mutash-kirmani","type":"section","surah":22,"num":338,"title":"سورة الحج","page":"ج1 ص183","text":"قوله {فبعدا للقوم الظالمين} بالألف واللام وبعده {لقوم لا يؤمنون} لأن الأول لقوم صالح فعرفهم بدليل قوله {فأخذتهم الصيحة} والثاني نكرة وقبله {قرونا آخرين} فكانوا منكرين ولم يكن معهم قرينة عرفوا بها فخصهم بالنكرة"},{"id":"mutash-kirmani:339","bookId":"mutash-kirmani","type":"section","surah":22,"num":339,"title":"سورة الحج","page":"ج1 ص184","text":"قوله {لقد وعدنا نحن وآباؤنا هذا من قبل} وفي النمل {لقد وعدنا هذا نحن وآباؤنا من قبل} لأن ما في هذه السورة على القياس فإن الضمير المرفوع المتصل لا يجوز العطف عليه حتى يؤكد بالمنفصل فأكد {وعدنا نحن} ثم عطف عليه {آباؤنا} ثم ذكر المفعول وهو {هذا} وقدم في النمل المفعول موافقة لقوله {ترابا} لأن القياس فيه أيضا كنا نحن وآباؤنا ترابا فقدم ترابا ليسد مسد نحن فكانا لفقين"},{"id":"mutash-kirmani:340","bookId":"mutash-kirmani","type":"section","surah":22,"num":340,"title":"سورة الحج","page":"ج1 ص184","text":"قوله {سيقولون لله} وبعده {سيقولون لله} وبعده {سيقولون لله} الأول جواب لقوله {قل لمن الأرض ومن فيها} جواب مطابق لفظا ومعنى لأنه قال في السؤال قل لمن فقال في الجواب لله وأما الثاني والثالث فالمطابقة فيهما في المعنى لأن القائل إذا قال لك من مالك هذا الغلام فإن لك أن تقول زيد فيكون مطابقا لفظا ومعنى ولك أن تقول لزيد فيكون مطابقا للمعنى ولهذا قرأ أبو عمرو الثاني والثالث الله الله مراعاة للمطابقة"},{"id":"mutash-kirmani:341","bookId":"mutash-kirmani","type":"section","surah":22,"num":341,"title":"سورة الحج","page":"ج1 ص185","text":"قوله {ألم تكن آياتي تتلى عليكم} وقبله {قد كانت آياتي تتلى عليكم} ليس بتكرار لأن الأول في الدنيا عند نزول العذاب وهو الجدب عند بعضهم ويوم بدر عند بعضهم والثاني في القيامة وهم في الجحيم بدليل قوله {ربنا أخرجنا منها}"},{"id":"mutash-kirmani:342","bookId":"mutash-kirmani","type":"section","surah":24,"num":342,"title":"سورة النور","page":"ج1 ص185","text":"قوله تعالى على رأس العشر {ولولا فضل الله عليكم ورحمته وأن الله تواب حكيم} محذوف الجواب تقديره لفضحكم وهو متصل ببيان حكم الزانيين وحكم القاذف وحكم اللعان وجواب لولا محذوفا أحسن منه ملفوظا به وهو المكان الذي يكون الإنسان فيه أفصح ما يكون إذا سكت"},{"id":"mutash-kirmani:343","bookId":"mutash-kirmani","type":"section","surah":24,"num":343,"title":"سورة النور","page":"ج1 ص186","text":"وقوله على رأس العشرين {ولولا فضل الله عليكم ورحمته وأن الله رؤوف رحيم} فحذف الجواب أيضا تقديره لعجل لكم العذاب وهو متصل بقصتها رضي الله عنها وعن أبيها وقيل دل عليه قوله {ولولا فضل الله عليكم ورحمته في الدنيا والآخرة لمسكم فيما أفضتم فيه عذاب عظيم} وقيل دل عليه قوله {ولولا فضل الله عليكم ورحمته ما زكا منكم من أحد أبدا} وفي خلال هذه الآيات {لولا إذ سمعتموه ظن المؤمنون} {لولا جاؤوا عليه بأربعة شهداء} {ولولا إذ سمعتموه قلتم} وليس هو الدال على امتناع الشيء لوجود غيره بل هو للتحضيض قال الشاعر تعدون عقر النيب أفضل مجدكم ... بني ضوطرى لولا الكمى المقنعا وهو في البيت للتحضيض والتحضيض يختص بالفعل والفعل في البيت مقدر تقديره هلا تعدون الكمى أو هلا تعقرون الكمى ويختص الثاني بالفعل والأول يختص بالاسم ويدخل المبتدأ ويلزم خبره الحذف"},{"id":"mutash-kirmani:344","bookId":"mutash-kirmani","type":"section","surah":24,"num":344,"title":"سورة النور","page":"ج1 ص186","text":"قوله {إن الله خبير بما يصنعون} متصل بآيات الغض وليس له نظير"},{"id":"mutash-kirmani:345","bookId":"mutash-kirmani","type":"section","surah":24,"num":345,"title":"سورة النور","page":"ج1 ص186","text":"قوله {ولقد أنزلنا إليكم آيات} وبعده {لقد أنزلنا آيات} لأن اتصال الأول بما قبله أشد فإن قوله {وموعظة للمتقين} محمول ومصروف إلى قوله {وليستعفف} وإلى قوله {فكاتبوهم} {ولا تكرهوا} فاقتضى الواو ليعلم أنه عطف على الأول واقتضى بيانه بقوله {إليكم} ليعلم أن المخاطبين بالآية الثانية هم المخاطبون بالآية الأولى وأما الثانية فاستئناف كلام فخص بالحذف"},{"id":"mutash-kirmani:346","bookId":"mutash-kirmani","type":"section","surah":24,"num":346,"title":"سورة النور","page":"ج1 ص186","text":"قوله {وعد الله الذين آمنوا منكم} إنما زاد {منكم} لأنهم المهاجرون وقبل عام و {من} للتبيين"},{"id":"mutash-kirmani:347","bookId":"mutash-kirmani","type":"section","surah":24,"num":347,"title":"سورة النور","page":"ج1 ص187","text":"قوله {وإذا بلغ الأطفال منكم الحلم} ختم الآية بقوله {كذلك يبين الله لكم آياته} وقبلها وبعدها الآيات 58 61 لأن الذي قبلها والذي بعدها يشتمل على علامات يمكن الوقوف عليها وهي في الأولى {ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم من الظهيرة ومن بعد صلاة العشاء} وفي الأخرى {من بيوتكم أو بيوت آبائكم أو بيوت أمهاتكم} الآية فعد فيها آيات كلها معلومة فختم الآيتين بقوله {لكم الآيات} ومثلها {يعظكم الله أن تعودوا لمثله أبدا إن كنتم مؤمنين ويبين الله لكم الآيات} يعني حد الزانيين وحد القاذف فختم بالآيات وأما بلوغ الأطفال فلم يذكر له علامات يمكن الوقوف عليها بل تفرد سبحانه بعلم ذلك فخصها بالإضافة إلى نفسه وختم كل آية بما اقتضى أولها"},{"id":"mutash-kirmani:348","bookId":"mutash-kirmani","type":"section","surah":25,"num":348,"title":"سورة الفرقان","page":"ج1 ص187","text":"قوله تعالى {تبارك} هذه لفظة لا تستعمل إلا لله ولا تستعمل إلا بلفظ الماضي وجاءت في هذه السورة في ثلاث مواضع {تبارك الذي نزل الفرقان على عبده} و {تبارك الذي إن شاء جعل} و {تبارك الذي جعل في السماء بروجا} تعظيما لذكر الله وخصت هذه المواضع بالذكر لأن ما بعدها عظائم الأول ذكر الفرقان وهو القرآن المشتمل على معاني جميع كتب الله والثاني ذكر النبي والله خاطبه بقوله لولاك يا محمد ما خلقت للكائنات والثالث ذكر للبروج والسيارات والشمس والقمر والليل والنهار ولولاها ما وجد في الأرض حيوان ولا نبات ومثلها {فتبارك الله رب العالمين} و {فتبارك الله أحسن الخالقين} و {تبارك الذي بيده الملك}"},{"id":"mutash-kirmani:349","bookId":"mutash-kirmani","type":"section","surah":25,"num":349,"title":"سورة الفرقان","page":"ج1 ص188","text":"قوله {من دونه} في هذه السورة وفي مريم 48 ويس 74 {من دون الله} لأن في هذه السورة وافق ما قبله وفي السورتين لو جاء {من دونه} لخالف ما قبله لأن ما قبله في السورتين بلفظ الجمع تعظيما فصرح"},{"id":"mutash-kirmani:350","bookId":"mutash-kirmani","type":"section","surah":25,"num":350,"title":"سورة الفرقان","page":"ج1 ص188","text":"قوله {ضرا ولا نفعا} قدم الضر موافقة لما قبله وما بعده فما قبله نفي وإثبات وما بعده موت وحياة وقد سبق"},{"id":"mutash-kirmani:351","bookId":"mutash-kirmani","type":"section","surah":25,"num":351,"title":"سورة الفرقان","page":"ج1 ص188","text":"قوله {ما لا ينفعهم ولا يضرهم} قدم النفع موافقة لقوله {هذا عذب فرات وهذا ملح أجاج} وقد سبق"},{"id":"mutash-kirmani:352","bookId":"mutash-kirmani","type":"section","surah":25,"num":352,"title":"سورة الفرقان","page":"ج1 ص188","text":"قوله {الذي خلق السماوات والأرض وما بينهما في ستة أيام ثم استوى على العرش الرحمن} ومثلها في السجدة يجوز أن يكون الذي في السورتين مبتدأ والرحمن خبره في الفرقان و {ما لكم من دونه} خبره في السجدة وجاز غير ذلك"},{"id":"mutash-kirmani:353","bookId":"mutash-kirmani","type":"section","surah":26,"num":353,"title":"سورة الشعراء","page":"ج1 ص188","text":"قوله تعالى {وما يأتيهم من ذكر من الرحمن محدث} سبق في الأنبياء"},{"id":"mutash-kirmani:354","bookId":"mutash-kirmani","type":"section","surah":26,"num":354,"title":"سورة الشعراء","page":"ج1 ص188","text":"قوله {فسيأتيهم} سبق في الأنعام وكذا {أو لم يروا} وما يتعلق بقصة موسى وفرعون سبق الأعراف {في}"},{"id":"mutash-kirmani:355","bookId":"mutash-kirmani","type":"section","surah":26,"num":355,"title":"سورة الشعراء","page":"ج1 ص189","text":"قوله {إن في ذلك لآية} إلى آخر الآية مذكور في ثمانية مواضع أولها في محمد صلى الله عليه وسلم وإن لم يتقدم ذكره صريحا فقد تقدم كناية ووضوحا والثانية في قصة موسى 67 ثم إبراهيم 103 ثم نوح 121 ثم هود ثم 139 ثم صالح 158 ثم لوط 174 ثم شعيب 190 عليهم السلام"},{"id":"mutash-kirmani:356","bookId":"mutash-kirmani","type":"section","surah":26,"num":356,"title":"سورة الشعراء","page":"ج1 ص189","text":"قوله {ألا تتقون} إلى قوله {العالمين} مذكور في خمسة مواضع في قصة نوح 106 109 وهود 124 127 وصالح 142 45 ولوط 161 164 وشعيب 177 180 عليهم السلام ثم كرر {فاتقوا الله وأطيعون} في قصة نوح 110 وهود 131 وصالح 50 فصار ثمانية مواضع وليس في قصة النبي صلى الله عليه وسلم عليه السلام لأنه رباه فرعون حيث قال {ألم نربك فينا وليدا} ولا في قصة إبراهيم عليه السلام لأن أباه في المخاطبين حيث يقول {إذ قال لأبيه وقومه} وهو رباه واستحيا موسى وإبراهيم أن يقولا {ما أسألكم عليه من أجر} وإن كانا منزهين من طلب الأجرة"},{"id":"mutash-kirmani:357","bookId":"mutash-kirmani","type":"section","surah":26,"num":357,"title":"سورة الشعراء","page":"ج1 ص189","text":"قوله تعالى في قصة إبراهيم {ما تعبدون} وفي الصافات {ماذا تعبدون} لأن {ما} لمجرد الاستفهام فأجابوا فقالوا {نعبد أصناما} {وماذا} فيه مبالغة وقد تضمن في الصافات معنى التوبيخ فلما وبخهم قال {أئفكا آلهة دون الله تريدون} {فما ظنكم برب العالمين} فجاء في كل سورة ما اقتضاه ما قبله وما بعده"},{"id":"mutash-kirmani:358","bookId":"mutash-kirmani","type":"section","surah":26,"num":358,"title":"سورة الشعراء","page":"ج1 ص189","text":"قوله {الذي خلقني فهو يهدين} {والذي هو يطعمني ويسقين} {وإذا مرضت فهو يشفين} زاد هو في الإطعام والشفاء لأنهما مما يدعي الإنسان أن يفعله فيقال زيد يطعم وعمرو يداوي فأكد إعلاما أن ذلك منه سبحانه لا من غيره وأما الخلق والموت والحياة فلا يدعيهما مدع فأطلق"},{"id":"mutash-kirmani:359","bookId":"mutash-kirmani","type":"section","surah":26,"num":359,"title":"سورة الشعراء","page":"ج1 ص190","text":"قوله في قصة صالح {ما أنت} بغير واو وفي قصة شعيب {وما أنت} لأنه في قصة صالح بدل من الأولى وفي الثانية عطف وخصت أولى بالبدل في الخطاب فأكثروا"},{"id":"mutash-kirmani:360","bookId":"mutash-kirmani","type":"section","surah":27,"num":360,"title":"سورة النمل","page":"ج1 ص190","text":"قوله تبارك وتعالى {فلما جاءها نودي} وفي القصص 30 وطه 11 {فلما أتاها نودي} لأنه قال في هذه السورة {سآتيكم منها بخبر أو آتيكم بشهاب قبس} فكرر {آتيكم} فاستثقل الجمع بينهما وبين {فلما أتاها} فعدل إلى قوله {فلما جاءها} بعد أن كانا بمعنى واحد وأما في السورتين فلم يكن إلا {لعلي آتيكم} {فلما أتاها}"},{"id":"mutash-kirmani:361","bookId":"mutash-kirmani","type":"section","surah":27,"num":361,"title":"سورة النمل","page":"ج1 ص190","text":"قوله {وألق عصاك} وفي القصص {وأن ألق عصاك} لأن في هذه السورة {نودي أن بورك من في النار ومن حولها وسبحان الله رب العالمين} {يا موسى إنه أنا الله العزيز الحكيم} {وألق عصاك} فحيل بينهما بهذه الجملة فاستغنى عن إعادة أن وفي القصص {أن يا موسى إني أنا الله رب العالمين وأن ألق عصاك} فلم يكن بينهما جملة أخرى عطف بها على الأول فحسن إدخال {إن}"},{"id":"mutash-kirmani:362","bookId":"mutash-kirmani","type":"section","surah":27,"num":362,"title":"سورة النمل","page":"ج1 ص191","text":"قوله {لا تخف} وفي القصص {أقبل ولا تخف} خصت هذه السورة بقوله {لا تخف} لأنه بنى على ذكر الخوف كلام يليق به وهو قوله {إني لا يخاف لدي المرسلون} وفي القصص اقتصر على قوله {لا تخف} ولم يبن عليه كلام فزيد قبله {أقبل} ليكون في مقابلة {مدبرا} أي أقبل آمنا غير مدبر ولا تخف فخصت هذه السورة به"},{"id":"mutash-kirmani:363","bookId":"mutash-kirmani","type":"section","surah":27,"num":363,"title":"سورة النمل","page":"ج1 ص191","text":"قوله {وأدخل يدك في جيبك تخرج بيضاء من غير سوء} وفي القصص {اسلك يدك} خصت هذه السورة بأدخل لأنه أبلغ من قوله {اسلك} لأن {اسلك} يأتي لازما ومتعديا {وأدخل} متعد لا غير ولأن في هذه السورة {في تسع آيات} أي مع تسع آيات مرسلا إلى فرعون وخصت القصص بقوله {اسلك} موافقة لقوله {اضمم} ثم قال {فذانك برهانان من ربك} فكان دون الأول فخص بالأدنى والأقرب من اللفظين"},{"id":"mutash-kirmani:364","bookId":"mutash-kirmani","type":"section","surah":27,"num":364,"title":"سورة النمل","page":"ج1 ص191","text":"قوله {إلى فرعون وقومه إنهم كانوا قوما فاسقين} وفي القصص {إلى فرعون وملئه} لأن الملأ أشراف القوم وكانوا في هذه السورة موصوفين بما وصفهم الله به من قوله {فلما جاءتهم آياتنا مبصرة قالوا هذا سحر مبين} {وجحدوا بها} الآية فلم يسمهم ملأ بل سماهم قوما وفي القصص لم يكونوا موصوفين بتلك الصفات فسماهم ملأ وعقبه {وقال فرعون يا أيها الملأ ما علمت لكم من إله غيري} وما يتعلق بقصة موسى سوى هذه الكلمات قد سبق"},{"id":"mutash-kirmani:365","bookId":"mutash-kirmani","type":"section","surah":27,"num":365,"title":"سورة النمل","page":"ج1 ص192","text":"قوله {وأنجينا الذين آمنوا} وفي حم فصلت {ونجينا الذين آمنوا وكانوا يتقون} نجينا وأنجينا بمعنى واحد وخصت هذه السورة بأنجينا لموافقته لما بعده وهو {فأنجيناه وأهله} وبعده {وأمطرنا} {وأنزل} {فأنبتنا} كله على لفظ أفعل وخص حم فصلت بنجينا لموافقته ما قبله {وزينا} وبعده {قيضنا لهم} وكله على لفظ فعلنا"},{"id":"mutash-kirmani:366","bookId":"mutash-kirmani","type":"section","surah":27,"num":366,"title":"سورة النمل","page":"ج1 ص192","text":"قوله {أإله مع الله} في خمس آيات وختم الأولى بقوله {بل هم قوم يعدلون} ثم {بل أكثرهم لا يعلمون} ثم قال {قليلا ما تذكرون} ثم {تعالى الله عما يشركون} ثم {إن كنتم صادقين} أي عدلوا إلى الذنوب وأول الذنوب العدل عن الحق ثم لم يعلموا ولو علموا ما عدلوا ثم لم يذكروا فيعلموا بالنظر والاستدلال فأشركوا عن غير حجة وبرهان قل لهم يا محمد {هاتوا برهانكم إن كنتم صادقين}"},{"id":"mutash-kirmani:367","bookId":"mutash-kirmani","type":"section","surah":27,"num":367,"title":"سورة النمل","page":"ج1 ص193","text":"قوله {ويوم ينفخ في الصور ففزع من في السماوات} وفي الزمر {فصعق} خصت هذه السورة بقوله {ففزع} موافقة لقوله {وهم من فزع يومئذ آمنون} وخصت الزمر بقوله {فصعق} موافقة لقوله {وإنهم ميتون} لأن معناه مات"},{"id":"mutash-kirmani:368","bookId":"mutash-kirmani","type":"section","surah":28,"num":368,"title":"سورة القصص","page":"ج1 ص193","text":"قوله تبارك وتعالى {ولما بلغ أشده واستوى} أي كمل أربعين سنة وقيل كمل قوله وقيل خرجت لحيته وفي يوسف {ولما بلغ أشده آتيناه} لأنه أوحى إليه في صباه"},{"id":"mutash-kirmani:369","bookId":"mutash-kirmani","type":"section","surah":28,"num":369,"title":"سورة القصص","page":"ج1 ص194","text":"قوله {وجاء رجل من أقصى المدينة يسعى} وفي يس {وجاء من أقصى المدينة رجل يسعى} اسمه حزبيل من آل فرعون وهو النجار وقيل شمعون وقيل حبيب وفي يس هو هو وقوله {من أقصى المدينة} يحتمل ثلاثة أوجه أحدها أن يكون من أقصى المدينة صفة لرجل والثاني أن يكون صلة لجاء والثالث أن يكون صلة ليسعى والأظهر في هذه السورة أن يكون وصفا وفي يس أن يكون صلة وخصت هذه السورة بالتقديم لقوله قبله {فوجد فيها رجلين يقتتلان} ثم قال {وجاء رجل} وخصت سورة يس بقوله {وجاء من أقصى المدينة} لما جاء في التفسير أنه كان يعبد الله في جبل فلما سمع خبر الرسل سعى مستعجلا"},{"id":"mutash-kirmani:370","bookId":"mutash-kirmani","type":"section","surah":28,"num":370,"title":"سورة القصص","page":"ج1 ص194","text":"قوله {ستجدني إن شاء الله من الصالحين} وفي الصافات {من الصابرين} لأن ما في هذه السورة من كلام شعيب أي من الصالحين في حسن المعاشرة والوفاء بالعهد وفي الصافات من كلام إسماعيل حين قال له أبوه {إني أرى في المنام أني أذبحك فانظر ماذا ترى} فأجاب {يا أبت افعل ما تؤمر ستجدني إن شاء الله من الصابرين}"},{"id":"mutash-kirmani:371","bookId":"mutash-kirmani","type":"section","surah":28,"num":371,"title":"سورة القصص","page":"ج1 ص194","text":"قوله {ربي أعلم بمن جاء} وبعده {من جاء} بغير باء الأول هو أم الأجه لأن أفعل هذا فيه معنى الفعل ومعنى الفعل لا يعمل في المفعول به فزيد بعده باء تقوية للعمل وخص الأول بالأصل ثم حذف من الآخر الباء اكتفاء بدلالة الأول عليه ومحله نصب بفعل آخر أي يعلم من جاء بالهدى ولم يقتض تغييرا كما قلنا في الأنعام لأن دلالة الأول قام مقام التغيير وخص الثاني به لأنه فرع"},{"id":"mutash-kirmani:372","bookId":"mutash-kirmani","type":"section","surah":28,"num":372,"title":"سورة القصص","page":"ج1 ص195","text":"قوله {لعلي أطلع إلى إله موسى} وفي المؤمن {لعلي أبلغ الأسباب} {أسباب السماوات فأطلع إلى إله موسى} لأن قوله {أطلع إلى إله موسى} في هذه السورة خبر لعلي وجعل قوله {أبلغ الأسباب} في المؤمن خبر لعلي ثم أبدلت منه {أسباب السماوات} وإنما زادها ليقع في مقابلة قوله {أو أن يظهر في الأرض الفساد} لأنه {زعم} أنه إله الأرض فقال {ما علمت لكم من إله غيري} أي في الأرض ألا ترى أنه قال {فأطلع إلى إله موسى} فجاء على كل سورة ما اقتضاه ما قبله"},{"id":"mutash-kirmani:373","bookId":"mutash-kirmani","type":"section","surah":28,"num":373,"title":"سورة القصص","page":"ج1 ص195","text":"قوله {وإني لأظنه من الكاذبين} وفي المؤمن {كاذبا} لأن التقدير في هذه السورة وإني لأظنه كاذبا من الكاذبين فزيد {من} لرءوس الآيات ثم أضمر كاذبا لدلالة الكاذبين عليه وفي المؤمن جاء على الأصل ولم يكن فيه موجب تغيير"},{"id":"mutash-kirmani:374","bookId":"mutash-kirmani","type":"section","surah":28,"num":374,"title":"سورة القصص","page":"ج1 ص195","text":"قوله {وما أوتيتم من شيء} بالواو وفي الشورى {فما أوتيتم} بالفاء لأنه لم يتعلق في هذه السورة بما قبله كبير تعلق فاقتصر على الواو لعطف جملة على جملة وتعلق في الشورى بما قبلها أشد تعلق لأنه عقب ما لهم من المخافة بما أوتوا من الأمنة والفاء حرف للتعقيب"},{"id":"mutash-kirmani:375","bookId":"mutash-kirmani","type":"section","surah":28,"num":375,"title":"سورة القصص","page":"ج1 ص195","text":"قوله {فمتاع الحياة الدنيا وزينتها} وفي الشورى {فمتاع الحياة الدنيا} فحسب لأن في هذه السورة ذكر جميع ما بسط من الرزق وأعراض الدنيا كلها مستوعبة بهذين اللفظين فالمتاع ما لا غنى عنه في الحياة من المأكول والمشروب والملبوس والمسكن والمنكوح والزينة ما يتجمل به الإنسان وقد يستغنى عنه كالثياب الفاخرة والمراكب الرائقة والدور المجصصة والأطعمة الملبقة وأما في الشورى فلم يقصد الاستيعاب بل ما هو مطلوبهم في تلك الحالة من النجاة والأمن في الحياة فلم يحتج إلى ذكر الزينة"},{"id":"mutash-kirmani:376","bookId":"mutash-kirmani","type":"section","surah":28,"num":376,"title":"سورة القصص","page":"ج1 ص196","text":"قوله {إن جعل الله عليكم الليل سرمدا} وبعده {إن جعل الله عليكم النهار سرمدا} قدم الليل على النهار لأن ذهاب الليل بطلوع الشمس أكثر فائدة من ذهاب النهار بدخول الليل ثم ختم الآية الأولى بقوله {أفلا تسمعون} بناء على الليل وختم الأخرى بقوله {أفلا تبصرون} بناء على النهار والنهار مبصر وآية النهار مبصرة"},{"id":"mutash-kirmani:377","bookId":"mutash-kirmani","type":"section","surah":28,"num":377,"title":"سورة القصص","page":"ج1 ص196","text":"قوله {ويكأن} {ويكأنه} ليس بتكرار لأن كل واحد منهما متصل بغير ما اتصل به الآخر قال ابن عباس وى صلة وإليه ذهب سيبويه فقال وى كلمة يستعملها النادم بإظهار ندامته وهي مفصولة من كأنه وقال الأخفش أصله ويك وأن الله بعده منصوب بإضمار العلم أي أعلم أن الله وقال بعضهم أصله ويلك وفيه ضعف وقال الضحاك الياء والكاف صلة وتقديره وإن الله وهذا كلام مزيف"},{"id":"mutash-kirmani:378","bookId":"mutash-kirmani","type":"section","surah":29,"num":378,"title":"سورة العنكبوت","page":"ج1 ص196","text":"قوله تعالى {ووصينا الإنسان بوالديه حسنا} وفي لقمان {ووصينا الإنسان بوالديه حملته} وفي الأحقاف {بوالديه إحسانا} الجمهور على أن الآيات الثلاث نزلت في سعد بن مالك وهو سعد ابن أبي وقاص وأنها في سورة لقمان اعتراض بين كلام لقمان لأبنه ولم يذكر في لقمان {حسنا} لأن قوله بعده {أن اشكر لي ولوالديك}"},{"id":"mutash-kirmani:379","bookId":"mutash-kirmani","type":"section","surah":29,"num":379,"title":"سورة العنكبوت","page":"ج1 ص197","text":"قام مقامه ولم يذكر في هذه السورة حملنه {ولا} {وضعته} موافقة لما قبله من الاختصار وهو قوله {والذين آمنوا وعملوا الصالحات لنكفرن عنهم سيئاتهم ولنجزينهم أحسن الذي كانوا يعملون} فإنه ذكر فيها جميع ما يقع بالمؤمنين بأوجز كلام وأحسن نظام ثم قال {ووصينا الإنسان} أي ألزمناه {حسنا} في حقهما وقياما بأمرهما وإعراضا عنهما وخلافا لقولهما إن امراه بالشرك بالله وذكر في لقمان والأحقاف حالة حملهما ووضعهما"},{"id":"mutash-kirmani:380","bookId":"mutash-kirmani","type":"section","surah":29,"num":380,"title":"سورة العنكبوت","page":"ج1 ص197","text":"قوله {وإن جاهداك لتشرك بي} وفي لقمان {على أن تشرك} لأن ما في هذه السورة وافق ما قبله لفظا وهو قوله {ومن جاهد فإنما يجاهد لنفسه} وفي لقمان محمول على المعنى لأن التقدير وإن حملاك على أن تشرك"},{"id":"mutash-kirmani:381","bookId":"mutash-kirmani","type":"section","surah":29,"num":381,"title":"سورة العنكبوت","page":"ج1 ص197","text":"قوله {يعذب من يشاء ويرحم من يشاء} بتقديم العذاب على الرحمة في هذه السورة فحسب لأن إبراهيم خاطب به نمروذ وأصحابه وأن العذاب وقع بهم في الدنيا"},{"id":"mutash-kirmani:382","bookId":"mutash-kirmani","type":"section","surah":29,"num":382,"title":"سورة العنكبوت","page":"ج1 ص198","text":"قوله {وما أنتم بمعجزين في الأرض ولا في السماء} وفي الشورى {وما أنتم بمعجزين في الأرض} لأنه في هذه السورة خطاب لنمروذ حين صعد الجو موهما أنه يحاول السماء فقال إبراهيم له ولقومه {وما أنتم بمعجزين في الأرض} أي من في الأرض من الجن والإنس ولا من في السماء من الملائكة فكيف تعجزون الله وقيل ما أنتم بفائتين عليه ولو هربتم في الأرض أو صعدتم في السماء فقال {وما أنتم بمعجزين في الأرض ولا في السماء} لو كنتم فيها وما في الشورى خطاب للمؤمنين وقوله {وما أصابكم من مصيبة فبما كسبت أيديكم} يدل عليه وقد جاء {وما هم بمعجزين} في قوله {والذين ظلموا من هؤلاء سيصيبهم سيئات ما كسبوا} من غير ذكر الأرض ولا السماء"},{"id":"mutash-kirmani:383","bookId":"mutash-kirmani","type":"section","surah":29,"num":383,"title":"سورة العنكبوت","page":"ج1 ص198","text":"قوله {فأنجاه الله من النار إن في ذلك لآيات لقوم يؤمنون} وقال بعده {خلق الله السماوات والأرض بالحق إن في ذلك لآية للمؤمنين} فجمع الأولى ووحد الثانية لأن الأولى إشارة إلى إثبات النبوة وفي النبيين صلوات الله عليهم كثرة والثاني إشارة إلى التوحيد وهو سبحانه واحد لا شريك له"},{"id":"mutash-kirmani:384","bookId":"mutash-kirmani","type":"section","surah":29,"num":384,"title":"سورة العنكبوت","page":"ج1 ص198","text":"قوله {أئنكم} جمع بين استفهامين قد سبق في الأعراف"},{"id":"mutash-kirmani:385","bookId":"mutash-kirmani","type":"section","surah":29,"num":385,"title":"سورة العنكبوت","page":"ج1 ص199","text":"قوله {ولما أن جاءت رسلنا لوطا} وفي هود {ولما جاءت} بغير {إن} لأن {لما} يقتضي جوابا وإذا اتصل به {إن} دل على أن الجواب وقع في الحال من غير تراخ كما في هذه السورة وهو قوله {سيء بهم وضاق بهم ذرعا} ومثله في يوسف {فلما أن جاء البشير ألقاه على وجهه فارتد بصيرا} وفي هود اتصل به كلام بعد كلام إلى قوله {قالوا يا لوط إنا رسل ربك لن يصلوا إليك} فلما طال لم يحسن دخول أن"},{"id":"mutash-kirmani:386","bookId":"mutash-kirmani","type":"section","surah":29,"num":386,"title":"سورة العنكبوت","page":"ج1 ص199","text":"قوله {وإلى مدين أخاهم شعيبا فقال} هو عطف على قوله {ولقد أرسلنا نوحا إلى قومه فلبث}"},{"id":"mutash-kirmani:387","bookId":"mutash-kirmani","type":"section","surah":29,"num":387,"title":"سورة العنكبوت","page":"ج1 ص199","text":"قوله {قل كفى بالله بيني وبينكم شهيدا} أخره في هذه السورة لما وصف وقد سبق"},{"id":"mutash-kirmani:388","bookId":"mutash-kirmani","type":"section","surah":29,"num":388,"title":"سورة العنكبوت","page":"ج1 ص199","text":"قوله {الله يبسط الرزق لمن يشاء من عباده ويقدر له} وفي القصص {يبسط الرزق لمن يشاء من عباده ويقدر} وفي الرعد 26 والشورى 12 {لمن يشاء ويقدر} لأن ما في هذه السورة اتصل بقوله {وكأين من دابة لا تحمل رزقها} الآية وفيها عموم فصار تقدير الآية يبسط الرزق لمن يشاء من عباده أحيانا ويقدر له أحيانا لأن الضمير يعود إلى من وقيل يقدر له البسط من التقدير وفي القصص تقديره يبسط الرزق لمن يشاء ويقدر لمن يشاء وكل واحد منهما غير الآخر بخلاف الأولى وفي السورتين يحتمل الوجهين فأطلق"},{"id":"mutash-kirmani:389","bookId":"mutash-kirmani","type":"section","surah":29,"num":389,"title":"سورة العنكبوت","page":"ج1 ص199","text":"قوله {من بعد موتها} وفي البقرة والجاثية والروم {بعد موتها} لأن في هذه السورة وافق ما قبله وهو {من قبله} فإنهما يتوافقان وفيه شيء آخر وهو أن ما في هذه السورة سؤال وتقرير والتقرير يحتاج إلى التحقيق فوق غيره فقيد الظرف بمن فجمع بين طرفيه كما سبق"},{"id":"mutash-kirmani:390","bookId":"mutash-kirmani","type":"section","surah":29,"num":390,"title":"سورة العنكبوت","page":"ج1 ص200","text":"قوله {نعم أجر العاملين} بغير واو لاتصاله بالأول أشد اتصال وتقديره ذلك نعم أجر العاملين"},{"id":"mutash-kirmani:391","bookId":"mutash-kirmani","type":"section","surah":30,"num":391,"title":"سورة الروم","page":"ج1 ص200","text":"قوله تعالى {أو لم يسيروا في الأرض} هنا وفي فاطر 44 وأول المؤمن 21 بالواو وفي غيرهن بالفاء لأن ما قبلها في هذه السورة {أو لم يتفكروا} وكذلك بعدها {وأثاروا الأرض} بالواو فوافق ما قبلها وما بعدها وفي فاطر أيضا وافق ما قبله وما بعده فإن قبله {ولن تجد لسنة الله تحويلا} وبعدها {وما كان الله ليعجزه من شيء} وكذلك أول المؤمن قبله {والذين يدعون من دونه} وأما في آخر المؤمن فوافق ما قبله وما بعده وكانا بالفاء وهو قوله {فأي آيات الله تنكرون} وبعده {فما أغنى عنهم}"},{"id":"mutash-kirmani:392","bookId":"mutash-kirmani","type":"section","surah":30,"num":392,"title":"سورة الروم","page":"ج1 ص201","text":"قوله {كيف كان عاقبة الذين من قبلهم كانوا أشد منهم قوة} {من قبلهم} متصل بكون آخر مضمر وقوله {كانوا أشد منهم قوة} إخبار عما كانوا عليه قبل الإهلاك وخصت هذه السورة بهذا النسق لما يتصل من الآيات بعده وكله إخبار عما كانوا عليه وهو {وأثاروا الأرض وعمروها} وفي فاطر {كيف كان عاقبة الذين من قبلهم وكانوا} بزيادة الواو لأن التقدير فينظروا كيف أهلكوا وكانوا أشد منهم قوة وخصت هذه السورة به لقوله {وما كان الله ليعجزه من شيء} الآية وفي المؤمن {كيف كان عاقبة الذين كانوا من قبلهم كانوا هم أشد منهم قوة} فأظهر {كان} العامل {في} {من قبلهم} وزاد {هم} لأن في هذه السورة وقعت في أوائل قصة نوح وهي تتم في ثلاثين آية فكان اللائق البسط وفي آخر المؤمن {كيف كان عاقبة الذين من قبلهم كانوا أكثر منهم وأشد قوة} فلم يبسط القول لأن أول السورة يدل عليه"},{"id":"mutash-kirmani:393","bookId":"mutash-kirmani","type":"section","surah":30,"num":393,"title":"سورة الروم","page":"ج1 ص201","text":"قوله {ومن آياته أن خلق لكم من أنفسكم أزواجا} وختم الآية بقوله {يتفكرون} لأن الفكر يؤدي إلى الوقوف على المعاني التي خلقن لها من التآنس والتجانس وسكون كل واحد منهما إلى الآخر"},{"id":"mutash-kirmani:394","bookId":"mutash-kirmani","type":"section","surah":30,"num":394,"title":"سورة الروم","page":"ج1 ص201","text":"قوله {ومن آياته خلق السماوات والأرض} وختم بقوله {للعالمين} لأن الكل تظلهم السماء وتقلهم الأرض وكل واحد منفرد بلطيفة في صوته يمتاز بها عن غيرها حتى لا ترى اثنين في ألف يتشابه صوتاهما ويلتبس كلامهما وكذلك ينفرد كل واحد بدقيقة في صورته يتميز بها من بين الأنام فلا ترى اثنين يتشابهان وهذا يشترك في معرفته الناس جميعا فلهذا قال {لآيات للعالمين} ومن حمل اختلاف الألسن على اللغات واختلاف الألوان على السواد والبياض والشقرة والسمرة فالاشتراك في معرفتها أيضا ظاهر ومن قرأ {للعالمين} بكسر اللام فقد أحسن لأن بالعلم يمكن الوصول إلى معرفة ما سبق ذكره"},{"id":"mutash-kirmani:395","bookId":"mutash-kirmani","type":"section","surah":30,"num":395,"title":"سورة الروم","page":"ج1 ص202","text":"قوله {ومن آياته منامكم بالليل} وختم بقوله {يسمعون} فإن من سمع أن النوم من صنع الله الحكيم ولا يقدر أحد على إجتلابه إذا امتنع ولا على دفعه إذا ورد تيقن أن له صانعا مدبرا قال الخطيب معنى {يسمعون} ههنا يستجيبون إلى ما يدعوهم إليه الكتاب وختم الآية الرابعة بقوله {يعقلون} لأن العقل ملاك أمر في هذه الأبواب وهو المؤدي إلى العلم فختم بذكره"},{"id":"mutash-kirmani:396","bookId":"mutash-kirmani","type":"section","surah":30,"num":396,"title":"سورة الروم","page":"ج1 ص202","text":"قوله {ومن آياته يريكم} أي انه يريكم وقيل تقديره ويريكم من آياته البرق وقيل أن يريكم فلما حذف {إن} سكن الياء وقيل من آياته كلام كاف كما تقول منها كذا ومنها كذا ومنها وتسكت تريد الكثرة"},{"id":"mutash-kirmani:397","bookId":"mutash-kirmani","type":"section","surah":30,"num":397,"title":"سورة الروم","page":"ج1 ص202","text":"قوله {أو لم يروا أن الله يبسط الرزق} وفي الزمر {أولم يعلموا} لأن بسط الرزق مما يشاهد ويرى فجاء في هذه السورة على ما يقتضيه اللفظ والمعنى وفي الزمر اتصل بقوله {أوتيته على علم} وبعده {ولكن أكثرهم لا يعلمون} فحسن {أولم يعلموا}"},{"id":"mutash-kirmani:398","bookId":"mutash-kirmani","type":"section","surah":30,"num":398,"title":"سورة الروم","page":"ج1 ص203","text":"قوله {ولتجري الفلك بأمره} وفي الجاثية {فيه بأمره} لأن في هذه السورة تقدم ذكر الرياح وهو قوله {أن يرسل الرياح مبشرات} بالمطر وإذاقة الرحمة {ولتجري الفلك} بالرياح بأمر الله تعالى ولم يتقدم ذكر البحر وفي الجاثية تقدم ذكر البحر وهو قوله {الله الذي سخر لكم البحر} فكنى عنه فقال {لتجري الفلك فيه بأمره}"},{"id":"mutash-kirmani:399","bookId":"mutash-kirmani","type":"section","surah":31,"num":399,"title":"سورة لقمان","page":"ج1 ص203","text":"قوله تعالى {كأن لم يسمعها كأن في أذنيه وقرا} وفي الجاثية {كأن لم يسمعها فبشره} زاد في هذه السورة {كأن في أذنيه وقرا} جل المفسرين على أن الآيتين نزلتا في النضر بن الحارث وذلك أنه ذهب إلى فارس فاشترى كتاب كليلة ودمنة وأخبار رستم واسفنديار وأحاديث الأكاسرة فجعل يرويها ويحدث بها قريشا ويقول إن محمدا يحدثكم بحديث عاد وثمود وأنا أحدثكم بحديث رستم واسفنديار ويستملحون حديثه ويتركون استماع القرآن فأنزل الله هذه الآيات وبالغ في ذمه لتركه استماع القرآن فقال {كأن في أذنيه وقرا} أي صمما لا يقرع مسامعه صوت ولم يبالغ في الجاثية هذه المبالغة لما ذكر بعده {وإذا علم من آياتنا شيئا اتخذها هزوا} لأن العلم لا يحصل إلا بالسماع أو ما يقوم مقامه من خط أو غيره"},{"id":"mutash-kirmani:400","bookId":"mutash-kirmani","type":"section","surah":31,"num":400,"title":"سورة لقمان","page":"ج1 ص203","text":"قوله {كل يجري إلى أجل مسمى} وفي الزمر {لأجل} قد سبق شطر من هذا ونزيده بيانا أن {إلى} متصل بآخر الكلام ودال على الانتهاء واللام متصل بأول الكلام ودال على الصلة والسلام"},{"id":"mutash-kirmani:401","bookId":"mutash-kirmani","type":"section","surah":32,"num":401,"title":"سورة السجدة","page":"ج1 ص204","text":"قوله {في يوم كان مقداره ألف سنة} وفي المعارج {خمسين ألف سنة} موضع بيانه التفسير والغريب فيه ما روي عن عكرمة في جماعة أن اليوم في المعارج عبارة عن أول أيام الدنيا إلى انقضائها وأنها خمسون ألف سنة لا يدري أحد كم مضى وكم بقي إلا الله عز وجل ومن الغريب أن هذه عبارة عن الشدة واستطالة أهلها إياها كالعادة في استطالة أيام الشدة والحزن واستقصار أيام الراحة والسرور حتى قال القائل سنة الوصل سنة بكسر السين وسنة الهجر سنة بفتح السين وخصت هذه السورة بقوله {ألف سنة} لما قبله وهو قوله {في ستة أيام}"},{"id":"mutash-kirmani:402","bookId":"mutash-kirmani","type":"section","surah":32,"num":402,"title":"سورة السجدة","page":"ج1 ص204","text":"وتلك الأيام من جنس ذلك اليوم وخصت المعارج بقوله {خمسين ألف سنة} لأن فيها ذكر القيامة وأهوالها فكان اللائق بها"},{"id":"mutash-kirmani:403","bookId":"mutash-kirmani","type":"section","surah":32,"num":403,"title":"سورة السجدة","page":"ج1 ص204","text":"قوله {ثم أعرض عنها} {ثم} ههنا تدل على الإعراض عقب التذكير"},{"id":"mutash-kirmani:404","bookId":"mutash-kirmani","type":"section","surah":32,"num":404,"title":"سورة السجدة","page":"ج1 ص204","text":"قوله {عذاب النار الذي كنتم به تكذبون} وفي سبأ {التي كنتم} لأن النار في هذه السورة وقعت موقع الكناية لتقدم ذكرها والكنايات لا توصف فوصف العذاب وفي سبأ لم يتقدم ذكر النار قبل 6 فحسن وصف النار"},{"id":"mutash-kirmani:405","bookId":"mutash-kirmani","type":"section","surah":32,"num":405,"title":"سورة السجدة","page":"ج1 ص204","text":"قوله {أولم يهد لهم} بالواو {من قبلهم} بزيادة {من} سبق في طه"},{"id":"mutash-kirmani:406","bookId":"mutash-kirmani","type":"section","surah":32,"num":406,"title":"سورة السجدة","page":"ج1 ص205","text":"قوله {إن في ذلك لآيات أفلا يسمعون} ليس غيره لأنه لما ذكر القرون والمساكن بالجمع حسن جمع الآيات ولما تقدم ذكر الكتاب وهو مسموع حسن ذكر لفظ السماع فختم الآية به"},{"id":"mutash-kirmani:407","bookId":"mutash-kirmani","type":"section","surah":33,"num":407,"title":"سورة الأحزاب","page":"ج1 ص205","text":"ذهب بعض القراء إلى أنه ليس في هذه السورة ما يذكر في المتشابه وبعضهم أورد فيها كلمات وليس في ذلك كثير تشابه بل قد يلتبس على الحافظ القليل البضاعة وعلى الصبي القليل التجارب فأوردتها إذ لم تخل من فائدة وذكرت مع بعضها علامة يستعين بها المبتدئ في تلاوته"},{"id":"mutash-kirmani:408","bookId":"mutash-kirmani","type":"section","surah":33,"num":408,"title":"سورة الأحزاب","page":"ج1 ص205","text":"منها قوله {ليسأل الصادقين عن صدقهم} وبعده {ليجزي الله الصادقين بصدقهم} ليس فيها تشابه لأن الأول من لفظ السؤال وصلته {عن صدقهم} وبعده {وأعد للكافرين} والثاني من لفظ الجزاء وفاعله {الله} وصلته {بصدقهم} بالباء وبعده {ويعذب المنافقين}"},{"id":"mutash-kirmani:409","bookId":"mutash-kirmani","type":"section","surah":33,"num":409,"title":"سورة الأحزاب","page":"ج1 ص205","text":"ومنها قوله {يا أيها الذين آمنوا اذكروا نعمة الله عليكم} وبعده {اذكروا الله ذكرا كثيرا} فيقال للمبتدئ إن الذي يأتي بعد العذاب الأليم نعمة من الله على المؤمنين وما يأتي قبل قوله {هو الذي يصلي عليكم} {اذكروا الله ذكرا كثيرا} شكرا على أن أنزلكم منزلة نبيه في صلاته وصلاة ملائكته عليه حيث يقول {إن الله وملائكته يصلون على النبي}"},{"id":"mutash-kirmani:410","bookId":"mutash-kirmani","type":"section","surah":33,"num":410,"title":"سورة الأحزاب","page":"ج1 ص206","text":"ومنها قوله {يا أيها النبي قل لأزواجك إن كنتن} {يا أيها النبي قل لأزواجك وبناتك} ليس من المتشابه لأن الأول في التخيير والثاني في الحجاب"},{"id":"mutash-kirmani:411","bookId":"mutash-kirmani","type":"section","surah":33,"num":411,"title":"سورة الأحزاب","page":"ج1 ص206","text":"ومنها قوله {سنة الله في الذين خلوا من قبل} في موضعين وفي الفتح {سنة الله التي قد خلت} التقدير في الآيات سنة الله التي قد خلت في الذين خلوا فذكر في كل سورة الطرف الذي هو أعم واكتفى به عن الطرف الآخر والمراد بما في أول هذه السورة النكاح نزلت حين عيروا رسول الله صلى الله عليه وسلم بنكاحه زينب فأنزل الله {سنة الله في الذين خلوا من قبل} أي النكاح سنة في النبيين على العموم وكانت لداود تسع وتسعون فضم إليهم المرأة التي خطبها أوريا وولدت سليمان والمراد بما في آخره هذه السورة القتل نزلت في المنافقين والشاكين الذين في قلوبهم مرض والمرجفين في المدينة على العموم وما في سورة الفتح يريد به نصرة الله لأنبيائه والعموم في النصرة أبلغ منه في النكاح والقتل ومثله في حم {غافر} {سنة الله التي قد خلت في عباده} فإن المراد بها عدم الانتفاع بالإيمان عند البأس فلهذا قال {قد خلت}"},{"id":"mutash-kirmani:412","bookId":"mutash-kirmani","type":"section","surah":33,"num":412,"title":"سورة الأحزاب","page":"ج1 ص206","text":"ومنها قوله {إن الله كان لطيفا خبيرا} {وكان الله على كل شيء رقيبا} {وكان الله قويا عزيزا} {وكان الله عليما حليما} وهذا من باب الإعراب وإنما نصب لدخول كان على الجملة فتفردت السورة به وحسن دخول كان عليها مراعاة لفواصل الآي والله أعلم"},{"id":"mutash-kirmani:413","bookId":"mutash-kirmani","type":"section","surah":34,"num":413,"title":"سورة سبأ","page":"ج1 ص207","text":"قوله تعالى {مثقال ذرة في السماوات ولا في الأرض} مرتين بتقديم السموات خلاف يونس فإن فيها {مثقال ذرة في الأرض ولا في السماء} لأن في هذه السورة تقدم ذكر السموات في أول السورة {الحمد لله الذي له ما في السماوات وما في الأرض} وقد سبق في يونس"},{"id":"mutash-kirmani:414","bookId":"mutash-kirmani","type":"section","surah":34,"num":414,"title":"سورة سبأ","page":"ج1 ص207","text":"قوله {أفلم يروا} بالفاء ليس غيره زيد الحرف لأن الاعتبار فيها بالمشاهدة على ما ذكرناه وخصت بالفاء لشدة اتصالها بالأول لأن الضمير يعود إلى الذين قسموا الكلام في النبي صلى الله عليه وسلم وقالوا محمد إما غافل أو كاذب وإما مجنون هاذ وهو قولهم {أفترى على الله كذبا أم به جنة} فقال الله تعالى بل تركتم القسمة الثالثة وهي وإما صحيح العقل صادق"},{"id":"mutash-kirmani:415","bookId":"mutash-kirmani","type":"section","surah":34,"num":415,"title":"سورة سبأ","page":"ج1 ص207","text":"قوله {قل ادعوا الذين زعمتم من دون الله} وفي سبحان {من دونه} لأنه في هذه السورة اتصلت الآية بآية ليس فيها لفظ الله فكان الصريح أحسن وفي سبحان اتصل بآيتين فيهما بضعة عشر مرة ذكر الله صريحا وكناية فكانت الكناية أولى وقد سبق"},{"id":"mutash-kirmani:416","bookId":"mutash-kirmani","type":"section","surah":34,"num":416,"title":"سورة سبأ","page":"ج1 ص207","text":"قوله {إن في ذلك لآية لكل عبد منيب} وبعده {إن في ذلك لآيات لكل صبار شكور} بالجمع لأن المراد الأول لآية على إحياء الموتى فخصت بالتوحيد وفي قصة سبأ جمع لأنهم صاروا اعتبارا يضرب بهم المثل تفرقوا أيادي سبأ وفرقوا كل مفرق ومزقوا كل ممزق فرفع بعضهم إلى الشام وبعضهم {ذهب} إلى يثرب وبعضهم إلى عمان فختم بالجمع وخصت به لكثرتهم وكثرة من يعتبر بهم فقال {لآيات لكل صبار} على الجنة {شكور} على النعمة أي المؤمنين"},{"id":"mutash-kirmani:417","bookId":"mutash-kirmani","type":"section","surah":34,"num":417,"title":"سورة سبأ","page":"ج1 ص208","text":"قوله {قل إن ربي يبسط الرزق لمن يشاء ويقدر} وبعده {لمن يشاء من عباده ويقدر له} سبق وخص هذه السورة بذكر الرب لأنه تكرر فيها مرات كثيرة منها {بلى وربي} {بلدة طيبة ورب غفور} {ربنا باعد بين} {يجمع بيننا ربنا} {موقوفون عند ربهم} ولم يذكر مع الأول {من عباده} لأن المراد بهم الكفار وذكره مع الثاني لأنهم المؤمنون وزاد {له} وقد سبق بيانه"},{"id":"mutash-kirmani:418","bookId":"mutash-kirmani","type":"section","surah":34,"num":418,"title":"سورة سبأ","page":"ج1 ص208","text":"قوله {وما أرسلنا في قرية من نذير} ولم يقل {من قبلك} ولا {قبلك} خصت السورة به لأنه في هذه السورة إخبار مجرد وفي غيرها إخبار للنبي صلى الله عليه وسلم وتسلية له فقال {قبلك} و {من قبلك}"},{"id":"mutash-kirmani:419","bookId":"mutash-kirmani","type":"section","surah":34,"num":419,"title":"سورة سبأ","page":"ج1 ص208","text":"قوله {ولا نسأل عما تعملون} وفي غيرها {عما كنتم تعملون} لأن قوله {أجرمنا} بلفظ الماضي أي قبل هذا ولم يقل نجرم فيقع في مقابلة تعملون لأن من شرط الإيمان ووصف المؤمن أن يعزم ألا يجرم وقوله {تعملون} خطاب للكفار وكانوا مصرين على الكفر في الماضي من الزمان والمستقبل فاستغنت به الآية عن قوله {كنتم}"},{"id":"mutash-kirmani:420","bookId":"mutash-kirmani","type":"section","surah":35,"num":420,"title":"سورة فاطر","page":"ج1 ص208","text":"قوله جل وعلا {والله الذي أرسل الرياح} بلفظ الماضي موافقة لأول السورة {الحمد لله فاطر السماوات والأرض جاعل الملائكة رسلا} لأنهما للماضي لا غير وقد سبق"},{"id":"mutash-kirmani:421","bookId":"mutash-kirmani","type":"section","surah":35,"num":421,"title":"سورة فاطر","page":"ج1 ص209","text":"قوله {وترى الفلك فيه مواخر} بتقديم { فيه} موافقة لتقدم {ومن كل تأكلون} وقد سبق"},{"id":"mutash-kirmani:422","bookId":"mutash-kirmani","type":"section","surah":35,"num":422,"title":"سورة فاطر","page":"ج1 ص209","text":"قوله {جاءتهم رسلهم بالبينات وبالزبر وبالكتاب} بزيادة الباءات قد سبق"},{"id":"mutash-kirmani:423","bookId":"mutash-kirmani","type":"section","surah":35,"num":423,"title":"سورة فاطر","page":"ج1 ص209","text":"قوله {مختلفا ألوانها} وبعده {ألوانها} ثم {ألوانه} لأن الأول يعود إلى {ثمرات} والثاني يعود إلى {الجبال} وقيل يعود إلى الحمر والثالث يعود إلى بعض الدال عليه {من} لأنه ذكر {من} ولم يفسره كما فسره في قوله {ومن الجبال جدد بيض وحمر} فاختص الثالث بالتذكير"},{"id":"mutash-kirmani:424","bookId":"mutash-kirmani","type":"section","surah":35,"num":424,"title":"سورة فاطر","page":"ج1 ص209","text":"قوله {إن الله بعباده لخبير بصير} بالصريح وبزيادة اللام وفي الشورى {إنه بعباده خبير بصير} لأن الآية المتقدمة في هذه السورة لم يكن فيها ذكر الله فصرح باسمه سبحانه وفي الشورى متصل بقوله {ولو بسط الله الرزق} فخص بالكناية ودخل اللام في الخبر وموافقة لقوله {إن ربنا لغفور شكور}"},{"id":"mutash-kirmani:425","bookId":"mutash-kirmani","type":"section","surah":35,"num":425,"title":"سورة فاطر","page":"ج1 ص209","text":"قوله {جعلكم خلائف في الأرض} على الأصل قد سبق و {أو لم يسيروا} سبق و {على ظهرها} سبق بيانه"},{"id":"mutash-kirmani:426","bookId":"mutash-kirmani","type":"section","surah":35,"num":426,"title":"سورة فاطر","page":"ج1 ص210","text":"قوله {فلن تجد لسنة الله تبديلا ولن تجد لسنة الله تحويلا} كرر وقال في الفتح {ولن تجد لسنة الله تبديلا} وقال في سبحان {ولا تجد لسنتنا تحويلا} التبديل تغيير الشيء عما كان عليه قيل مع بقاء مادة الأصل كقوله تعالى {بدلناهم جلودا غيرها} وكذلك {تبدل الأرض غير الأرض والسماوات} والتحويل نقل الشيء من مكان إلى مكان آخر وسنة الله سبحانه لا تبدل ولا تحول فخص هذا الموضع بالجمع بين الوصفين لما وصف الكفار بوصفين وذكر لهم غرضين وهو قوله {ولا يزيد الكافرين كفرهم عند ربهم إلا مقتا} {ولا يزيد الكافرين كفرهم إلا خسارا} وقوله {استكبارا في الأرض ومكر السيء} وقيل هما بدلان من {نفورا} فكما ثنى الأول والثاني ثنى الثالث ليكون الكلام كله على غرار واحد وقال في الفتح {ولن تجد لسنة الله تبديلا} فاقتصر على مرة واحدة لما لم يكن للتكرار موجب وخص {سبحان} بقوله تحويلا 77 لأن قريشا قالوا لرسول الله صلى الله عليه وسلم لو كنت نبيا لذهبت إلى الشام فإنها أرض المبعث والمحشر فهم النبي صلى الله عليه وسلم بالذهاب إليها فهيأ أسباب الرحيل والتحويل فنزل جبريل عليه السلام بهذه الآيات {وإن كادوا ليستفزونك من الأرض ليخرجوك منها} وختم الآيات بقوله {تحويلا} تطبيقا للمعنى"},{"id":"mutash-kirmani:427","bookId":"mutash-kirmani","type":"section","surah":36,"num":427,"title":"سورة يس","page":"ج1 ص210","text":"قوله تبارك وتعالى {وجاء من أقصى المدينة رجل يسعى} قد سبق"},{"id":"mutash-kirmani:428","bookId":"mutash-kirmani","type":"section","surah":36,"num":428,"title":"سورة يس","page":"ج1 ص211","text":"قوله {إن كانت إلا صيحة واحدة} مرتين ليس بتكرار لأن الأولى هي النفخة التي يموت بها الخلق والثانية هي التي يحيا بها الخلق"},{"id":"mutash-kirmani:429","bookId":"mutash-kirmani","type":"section","surah":36,"num":429,"title":"سورة يس","page":"ج1 ص211","text":"قوله {فلا يحزنك قولهم إنا نعلم} وفي يونس {ولا يحزنك قولهم إن العزة لله جميعا} تشابها في الوقف على {قولهم} في السورتين لأن الوقف عليه لازم و {إن} فيهما مكسورة بالابتداء بالكتابة ومحكى القول محذوف ولا يجوز الوصل لأن النبي صلى الله عليه وسمل منزه من أن يخاطب بذلك"},{"id":"mutash-kirmani:430","bookId":"mutash-kirmani","type":"section","surah":36,"num":430,"title":"سورة يس","page":"ج1 ص211","text":"قوله {وصدق المرسلون} وفي الصافات {وصدق المرسلين} ذكر في المتشابه وما يتعلق بالإعراب لا يعد في المتشابه"},{"id":"mutash-kirmani:431","bookId":"mutash-kirmani","type":"section","surah":37,"num":431,"title":"سورة الصافات","page":"ج1 ص211","text":"قوله تبارك وتعالى {أئذا متنا وكنا ترابا وعظاما أئنا لمبعوثون} وبعدها {أئذا متنا وكنا ترابا وعظاما أئنا لمدينون} لأن الأول حكاية كلام الكافرين وهم منكرون للبعث والثاني قول أحد الفريقين لصاحبه عند وقوع الحساب والجزاء وحصوله فيه كان لي قرين ينكر الجزاء وما نحن فيه فهل أنتم تطلعونني عليه {فاطلع فرآه في سواء الجحيم قال تالله إن كدت لتردين} قيل كانا أخوين وقيل كانا شريكين وقيل هما بطروس الكافر ويهوذا مسلم وقيل القرين هو إبليس"},{"id":"mutash-kirmani:432","bookId":"mutash-kirmani","type":"section","surah":37,"num":432,"title":"سورة الصافات","page":"ج1 ص212","text":"قوله {وأقبل بعضهم على بعض يتساءلون} وبعده {فأقبل} بالفاء وكذلك في {ن والقلم} لأن الأول لعطف جملة على جملة فحسب والثاني لعطف جملة على جملة بينهما مناسبة والتئام لأنه حكى أحوال أهل الجنة ومذاكرتهم فيها ما كان يجري في الدنيا بينهم وبين أصدقائهم وهو قوله {وعندهم قاصرات الطرف عين} {كأنهن بيض مكنون} {فأقبل بعضهم على بعض يتساءلون} أي يتذاكرون وكذلك في {ن والقلم} هو من كلام أصحاب الجنة بصنعاء لما رأوها كالصريم وندموا على ما كان منهم وجعلوا يقولون {سبحان ربنا إنا كنا ظالمين} بعد أن ذكرهم التسبيح أوسطهم ثم قال {فأقبل بعضهم على بعض يتلاومون} أي على تركهم الاستثناء وتخافتهم {أن لا يدخلنها اليوم عليكم مسكين}"},{"id":"mutash-kirmani:433","bookId":"mutash-kirmani","type":"section","surah":37,"num":433,"title":"سورة الصافات","page":"ج1 ص212","text":"قوله {إنا كذلك نفعل بالمجرمين} وفي المرسلات {كذلك نفعل بالمجرمين} لأن في هذه السورة حيل بين الضمير وبين كذلك بقوله {فإنهم يومئذ في العذاب مشتركون} فأعاد وفي المرسلات متصل بالأول وهو قوله {ثم نتبعهم الآخرين كذلك نفعل بالمجرمين} فلم يحتج إلى إعادة الضمير"},{"id":"mutash-kirmani:434","bookId":"mutash-kirmani","type":"section","surah":37,"num":434,"title":"سورة الصافات","page":"ج1 ص213","text":"قوله {إذا قيل لهم لا إله إلا الله} وفي القتال {فاعلم أنه لا إله إلا الله} بزيادة {أنه} وليس لهما في القرآن ثالث لأن ما في هذه السورة وقع بعد القول فحكى المقول وفي القتال وقع بعد العلم فزيد قبله {أنه} ليصير مفعول العلم ثم يتصل به ما بعده"},{"id":"mutash-kirmani:435","bookId":"mutash-kirmani","type":"section","surah":37,"num":435,"title":"سورة الصافات","page":"ج1 ص213","text":"قوله {وتركنا عليه في الآخرين} {سلام على نوح في العالمين} وبعده {سلام على إبراهيم} ثم {سلام على موسى وهارون} وكذلك {سلام على إل ياسين} فيمن جعله لغة في إلياس ولم يقل في قصة لوط ولا يونس ولا إلياس {سلام} لأنه لما قال {وإن لوطا لمن المرسلين} {وإن يونس لمن المرسلين} وكذلك {وإن إلياس لمن المرسلين} فقد قال سلام على كل واحد منهم لقوله في آخر السورة {وسلام على المرسلين}"},{"id":"mutash-kirmani:436","bookId":"mutash-kirmani","type":"section","surah":37,"num":436,"title":"سورة الصافات","page":"ج1 ص213","text":"قوله {إنا كذلك نجزي المحسنين} وفي قصة إبراهيم {كذلك} لأنه تقدم في قصته {إنا كذلك نجزي المحسنين}"},{"id":"mutash-kirmani:437","bookId":"mutash-kirmani","type":"section","surah":37,"num":437,"title":"سورة الصافات","page":"ج1 ص213","text":"ولا بقي من قصته شيء وفي سائرها بعد الفراغ ولم يقل في قصتي لوط ويونس {إنا كذلك نجزي المحسنين} {إنه من عبادنا المؤمنين} لأنه لما اقتصر من التسليم على ما سبق ذكره اكتفى بذلك"},{"id":"mutash-kirmani:438","bookId":"mutash-kirmani","type":"section","surah":37,"num":438,"title":"سورة الصافات","page":"ج1 ص214","text":"قوله {بغلام حليم} وفي الذاريات {عليم} وكذلك في الحجر 53 لأن التقدير بغلام حليم في صباه عليم في كبره وخصت هذه السورة بحليم لأنه عليه السلام حليم فاتقاه وأطاعه وقال {يا أبت افعل ما تؤمر ستجدني إن شاء الله من الصابرين} والأظهر أن الحليم إسماعيل والعليم إسحاق لقوله {فأقبلت امرأته في صرة فصكت وجهها} قال مجاهد العليم والحليم في السورتين إسماعيل وقيل هما في السورتين إسحاق وهذا عند من زعم أن الذبيح إسحاق وذكرت ذلك بشرحه في موضعه"},{"id":"mutash-kirmani:439","bookId":"mutash-kirmani","type":"section","surah":37,"num":439,"title":"سورة الصافات","page":"ج1 ص215","text":"قوله {وأبصرهم فسوف يبصرون} ثم قال {وأبصر فسوف يبصرون} كرر وحذف الضمير من الثاني لأنه لما نزل {وأبصرهم} قالوا متى هذا الوعد الذي توعدونا به فأنزل الله {أفبعذابنا يستعجلون} كرر تأكيدا وقيل الأولى في الدنيا والثانية في العقبى والتقدير أبصر ما ينالهم فسوف يبصرون ذلك وقيل أبصر حالهم بقلبك فسوف يبصرون معاينة وقيل بعد ما ضيعوا من أمرنا فسوف يبصرون ما يحل بهم وحذف الضمير من الثاني اكتفاء بالأول {وقيل} الضمير مضمر تقديره ترى اليوم خيرهم إلى تول وترى بعد اليوم ما تحتقر ما شاهدتهم فيه من عذاب الدنيا وذكر في المتشابه {فقال ألا تأكلون} بالفاء وفي الذاريات {قال ألا تأكلون} بغير فاء لأن ما في هذه السورة اتصلت جملة بخمس جمل مبدوءة بالفاء على التوالي وهي {فما ظنكم} الآيات 87 90 والخطاب للأوثان تقريعا لمن زعم أنها تأكل وتشرب وفي الذاريات متصل بمضمر تقديره فقربه إليهم فلم يأكلوا فلما رآهم لا يأكلون قال ألا تأكلون والخطاب للملائكة فجاء في كل موضع بما يلائمه"},{"id":"mutash-kirmani:440","bookId":"mutash-kirmani","type":"section","surah":38,"num":440,"title":"سورة ص","page":"ج1 ص215","text":"قوله تعالى {وعجبوا أن جاءهم منذر منهم وقال الكافرون} بالواو وفي ق {فقال} بالفاء لأن اتصاله بما قبله في هذه السورة معنوي وهو أنهم عجبوا من مجيء المنذر وقالوا هذا المنذر ساحر كذاب واتصاله في ق معنوي ولفظي وهو أنهم عجبوا فقالوا {هذا شيء عجيب} فراعى المطابقة والعجز والصدر وختم بما بدأ به وهو النهاية في البلاغة"},{"id":"mutash-kirmani:441","bookId":"mutash-kirmani","type":"section","surah":38,"num":441,"title":"سورة ص","page":"ج1 ص215","text":"قوله {أأنزل عليه الذكر من بيننا} وفي القمر {أؤلقي الذكر عليه من بيننا} لأن ما في هذه السورة حكاية عن كفار قريش يجيبون محمدا صلى الله عليه وسلم حين قرأ عليهم {وأنزلنا إليك الذكر لتبين للناس} فقالوا {أأنزل عليه الذكر من بيننا} ومثله {الحمد لله الذي أنزل على عبده الكتاب} و {تبارك الذي نزل الفرقان على عبده} وهو كثير وما في القمر حكاية عن قوم صالح وكان يأتي الأنبياء يومئذ صحف مكتوبة وألواح مسطورة كما جاء إبراهيم وموسى فلهذا قالوا {أؤلقي الذكر عليه} مع أن لفظ الإلقاء يستعمل لما يستعمل له الإنزال"},{"id":"mutash-kirmani:442","bookId":"mutash-kirmani","type":"section","surah":38,"num":442,"title":"سورة ص","page":"ج1 ص216","text":"قوله {ومثلهم معهم رحمة منا} وفي الأنبياء {رحمة من عندنا} لأن الله سبحانه وتعالى ميز أيوب بحسن صبره على بلائه بين أنبيائه فحيث قال لهم {من عندنا} قال له {منا} وحيث لم يقل لهم من عندنا قال له {من عندنا} فخصت هذه السورة بقوله {منا} لما تقدم في حقهم {من عندنا} في مواضع وخصت سورة الأنبياء بقوله {من عندنا} لتفرده بذلك"},{"id":"mutash-kirmani:443","bookId":"mutash-kirmani","type":"section","surah":38,"num":443,"title":"سورة ص","page":"ج1 ص216","text":"قوله {كذبت قبلهم قوم نوح وعاد وفرعون ذو الأوتاد} وفي ق {كذبت قبلهم قوم نوح وأصحاب الرس وثمود} إلى قوله {فحق وعيد} قال الخطيب سورة ص بنيت فواصلها على ردف أواخرها بالباء والواو فقال في هذه السورة {الأوتاد} {الأحزاب} {عقاب} وجاء بإزاء ذلك في ق {ثمود} {وعيد} ومثله في الصافات {قاصرات الطرف عين} وفي ص {قاصرات الطرف أتراب} فالقصد للتوفيق بالألفاظ مع وضوح المعاني"},{"id":"mutash-kirmani:444","bookId":"mutash-kirmani","type":"section","surah":38,"num":444,"title":"سورة ص","page":"ج1 ص216","text":"قوله في قصة آدم {إني خالق بشرا من طين} قد سبق"},{"id":"mutash-kirmani:445","bookId":"mutash-kirmani","type":"section","surah":39,"num":445,"title":"سورة الزمر","page":"ج1 ص217","text":"قوله عز وجل {إنا أنزلنا إليك الكتاب بالحق} وفي هذه أيضا {إنا أنزلنا إليك الكتاب بالحق لتحكم بين الناس} الفرق بين أنزلنا إليك الكتاب وأنزلنا عليك قد سبق في البقرة ونزيده وضوحا أن كل موضع خاطب النبي صلى الله عليه وسلم بقوله {إنا أنزلنا إليك} ففيه تكليف وإذا خاطبه بقوله {أنا أنزلنا عليك} ففيه تخفيف واعتبر بما في هذه السورة فالذي في أول السورة {إليك} فكلفه الإخلاص في العبادة والذي في آخرها {عليك} فختم الآية بقوله {وما أنت عليهم بوكيل} أي لست بمسئول عنهم فخفف عنه ذلك"},{"id":"mutash-kirmani:446","bookId":"mutash-kirmani","type":"section","surah":39,"num":446,"title":"سورة الزمر","page":"ج1 ص217","text":"قوله {إني أمرت أن أعبد الله مخلصا له الدين} {وأمرت لأن أكون أول المسلمين} زاد مع الثاني لاما لأن المفعول من الثاني محذوف تقديره فأمرت أن أعبد الله لأن أكون فاكتفى بالأول"},{"id":"mutash-kirmani:447","bookId":"mutash-kirmani","type":"section","surah":39,"num":447,"title":"سورة الزمر","page":"ج1 ص217","text":"قوله {قل الله أعبد مخلصا له ديني} بالإضافة والأول {مخلصا له الدين} لأن قوله {أعبد} إخبار صدر عن المتكلم فاقتضى الإضافة إلى المتكلم وقوله {أمرت أن أعبد الله} ليس بإخبار عن المتكلم وإنما الإخبار وما بعده فضله ومفعول"},{"id":"mutash-kirmani:448","bookId":"mutash-kirmani","type":"section","surah":39,"num":448,"title":"سورة الزمر","page":"ج1 ص217","text":"قوله {ويجزيهم أجرهم بأحسن الذي كانوا يعملون} وفي النحل {ولنجزين الذين صبروا أجرهم بأحسن ما كانوا يعملون} وكان حقه أن يذكر هناك خصت هذه السورة بالذي ليوافق ما قبله وهو {أسوأ الذي عملوا} وقبله {والذي جاء بالصدق} وخصت النحل بما للموافقة أيضا وهو قوله {إنما عند الله هو خير لكم} {ما عندكم ينفد وما عند الله باق} فتلائم اللفظان في السورتين"},{"id":"mutash-kirmani:449","bookId":"mutash-kirmani","type":"section","surah":39,"num":449,"title":"سورة الزمر","page":"ج1 ص218","text":"قوله {وبدا لهم سيئات ما كسبوا} وفي الجاثية {ما عملوا} علة الآية الأولى لأن ما كسبوا في هذه السورة وقع بين ألفاظ الكسب وهو {ذوقوا ما كنتم تكسبون} وفي الجاثية وقع بين ألفاظ العمل وهو {ما كنتم تعملون} {وعملوا الصالحات} وبعده {سيئات ما عملوا} فخصت كل سورة بما اقتضاه"},{"id":"mutash-kirmani:450","bookId":"mutash-kirmani","type":"section","surah":39,"num":450,"title":"سورة الزمر","page":"ج1 ص218","text":"قوله {ثم يهيج فتراه مصفرا ثم يجعله حطاما} وفي الحديد {ثم يكون حطاما} لأن الفعل الواقع بعد قوله {ثم يهيج} في هذه السورة مسند إلى الله تعالى وهو قوله {ثم يخرج به زرعا} فكذلك الفعل بعده {ثم يجعله} وأما الفعل قبله في الحديد فمسند إلى النبات وهو {أعجب الكفار نباته} فكذلك ما بعده وهو {ثم يكون} ليوافق في السورتين ما قبله وما بعده"},{"id":"mutash-kirmani:451","bookId":"mutash-kirmani","type":"section","surah":39,"num":451,"title":"سورة الزمر","page":"ج1 ص218","text":"قوله {فتحت أبوابها} وبعده {وفتحت} بالواو للحال أي جاءوها وقد فتحت أبوابها وقيل الواو في {وقال لهم خزنتها} زائدة وهو الجواب وقيل الواو واو الثمانية وقد سبق في الكهف"},{"id":"mutash-kirmani:452","bookId":"mutash-kirmani","type":"section","surah":39,"num":452,"title":"سورة الزمر","page":"ج1 ص218","text":"قوله {فمن اهتدى فلنفسه} وفي آخرها {فإنما يهتدي لنفسه} لأن هذه السورة متأخرة عن تلك السورة فاكتفى بذكره فيها"},{"id":"mutash-kirmani:453","bookId":"mutash-kirmani","type":"section","surah":40,"num":453,"title":"سورة غافر","page":"ج1 ص218","text":"قوله تعالى {أولم يسيروا في الأرض} ما يتعلق بذكرها قد سبق"},{"id":"mutash-kirmani:454","bookId":"mutash-kirmani","type":"section","surah":40,"num":454,"title":"سورة غافر","page":"ج1 ص219","text":"قوله {ذلك بأنهم كانت تأتيهم رسلهم} وفي التغابن {بأنه كانت} لأن هاء الكتابة إذا زيدت لامتناع { إن} عن الدخول على كان فخصت هذه السورة بكناية المتقدم ذكرهم موافقة لقوله {كانوا هم أشد منهم قوة} وخصت سورة التغابن بضمير الأمر والشأن توصلا إلى كان"},{"id":"mutash-kirmani:455","bookId":"mutash-kirmani","type":"section","surah":40,"num":455,"title":"سورة غافر","page":"ج1 ص219","text":"قوله {فلما جاءهم بالحق} في هذه السورة فحسب لأن الفعل لموسى وفي سائر القرآن الفعل للحق"},{"id":"mutash-kirmani:456","bookId":"mutash-kirmani","type":"section","surah":40,"num":456,"title":"سورة غافر","page":"ج1 ص219","text":"قوله {إن الساعة لآتية} وفي طه {آتيه} لأن اللام إنما تزداد لتأكيد الخبر وتأكيد الخبر إنما يحتاج إليه إذا كان المخبر به شاكا في الخبر فالمخاطبون في هذه السورة الكفار فأكد وكذلك أكد {لخلق السماوات والأرض أكبر من خلق الناس} في هذه السورة باللام"},{"id":"mutash-kirmani:457","bookId":"mutash-kirmani","type":"section","surah":40,"num":457,"title":"سورة غافر","page":"ج1 ص219","text":"قوله {ولكن أكثر الناس لا يشكرون} وفي يونس {ولكن أكثرهم لا يشكرون} وقد سبق لأنه وافق ما قبله في هذه السورة {ولكن أكثر الناس لا يعلمون} وبعده {أكثر الناس لا يؤمنون} ثم قال {ولكن أكثر الناس لا يشكرون}"},{"id":"mutash-kirmani:458","bookId":"mutash-kirmani","type":"section","surah":40,"num":458,"title":"سورة غافر","page":"ج1 ص219","text":"قوله في الآية الأولى {لا يعلمون} أي لا يعلمون أن خلق الأكبر أسهل من خلق الأصغر ثم قال {لا يؤمنون} بالبعث ثم قال {لا يشكرون} أي لا يشكرون الله على فضله فختم كل آية بما اقتضاه"},{"id":"mutash-kirmani:459","bookId":"mutash-kirmani","type":"section","surah":40,"num":459,"title":"سورة غافر","page":"ج1 ص220","text":"قوله تعالى {الحمد لله رب العالمين} مدح نفسه سبحانه وختم ثلاث آيات على التوالي بقوله {رب العالمين} وليس له في القرآن نظير"},{"id":"mutash-kirmani:460","bookId":"mutash-kirmani","type":"section","surah":40,"num":460,"title":"سورة غافر","page":"ج1 ص220","text":"قوله {وخسر هنالك المبطلون} وختم السورة بقوله {وخسر هنالك الكافرون} لأن الأول متصل بقوله {قضي بالحق} ونقيض الحق الباطل والثاني متصل بإيمان غير مجد ونقيض الإيمان الكفر"},{"id":"mutash-kirmani:461","bookId":"mutash-kirmani","type":"section","surah":41,"num":461,"title":"سورة فصلت","page":"ج1 ص221","text":"قوله تعالى {في أربعة أيام} أي مع اليومين الذين تقدما قوله {خلق الأرض في يومين} لئلا يزيد العدد على ستة أيام فيتطرق إليه كلام المعترض وإنما جمع بينهما ولم يذكر اليومين على الانفراد بعدهما لدقيقة لا يهتدي إليها كل أحد وهي أن قوله {خلق الأرض في يومين} صلة الذي و {وتجعلون له أندادا} عطف على قوله {لتكفرون} و {وجعل فيها رواسي} عطف على قوله {خلق الأرض} وهذا تفريع في الإعراب لا يجوز في الكلام وهو في الشعر من أقبح الضرورات لا يجوز أن يقال جاءني الذي يكتب وجلس ويقرأ لأنه لا يحال بين صلة الموصول وما يعطف بأجنبي من الصلة فإذا امتنع هذا لم يكن بد من إضمار فعل يصح الكلام به ومعه فيضمر خلق الأرض بعد قوله {ذلك رب العالمين} فيصير التقدير ذلك رب العالمين خلق الأرض وجعل فيها رواسي من فوقها وبارك فيها وقدر فيها أقواتها في أربعة أيام ليقع هذا كله في أربعة أيام ويسقط الاعتراض والسؤال وهذه معجزة وبرهان"},{"id":"mutash-kirmani:462","bookId":"mutash-kirmani","type":"section","surah":41,"num":462,"title":"سورة فصلت","page":"ج1 ص221","text":"قوله {حتى إذا ما جاؤوها شهد عليهم سمعهم} وفي الزخرف وغيره {حتى إذا جاءنا} {حتى إذا جاءونا} بغير {ما} لأن حتى ههنا هي التي تجري مجرى واو العطف نحو قولك أكلت السمكة حتى رأسها أي ورأسها وتقدير الآية فهم يوزعون إذا جاءوها و {ما} هي التي تزاد مع الشروط نحو أينما وحيثما و {حتى} في غيرها من السور للغاية"},{"id":"mutash-kirmani:463","bookId":"mutash-kirmani","type":"section","surah":41,"num":463,"title":"سورة فصلت","page":"ج1 ص221","text":"قوله {وإما ينزغنك من الشيطان نزغ فاستعذ بالله إنه هو السميع العليم} ومثله في الأعراف لكنه ختم بقوله {إنه سميع عليم} لأن الآية في هذه السورة متصلة بقوله {وما يلقاها إلا الذين صبروا وما يلقاها إلا ذو حظ عظيم} فكان مؤكدا بالتكرار وبالنفي والإثبات فبالغ في قوله {إنه هو السميع العليم} بزيادة {هو} وبالألف واللام ولم يكن في الأعراف هذا النوع من الاتصال فأتى على القياس المخبر عنه معرفة والخبر نكرة"},{"id":"mutash-kirmani:464","bookId":"mutash-kirmani","type":"section","surah":41,"num":464,"title":"سورة فصلت","page":"ج1 ص222","text":"قوله {ولولا كلمة سبقت من ربك لقضي بينهم} وفي {حم عسق} بزيادة قوله {إلى أجل مسمى} وزاد فيها أيضا {بغيا بينهم} لأن المعنى تفرق قول اليهود في التوراة وتفرق قول الكافرين في القرآن ولولا كلمة سبقت من ربك بتأخر العذاب إلى يوم الجزاء لقضى بينهم بإنزال العذاب عليهم وخصت حمعسق بزيادة قوله {إلى أجل مسمى} لأنه ذكر البداية في أول الآية وهو {وما تفرقوا إلا من بعد ما جاءهم العلم} وهو مبدأ كفرهم فحسن ذكر النهاية التي أمهلوا إليها ليكون محدودا من الطرفين"},{"id":"mutash-kirmani:465","bookId":"mutash-kirmani","type":"section","surah":41,"num":465,"title":"سورة فصلت","page":"ج1 ص222","text":"قوله {وإن مسه الشر فيؤوس قنوط} وبعده {وإذا مسه الشر فذو دعاء عريض} لا منافاة بينهما لأن معناه قنوط من الضيم دعاء الله وقيل يئوس قنوط بالقلب دعاء باللسان وقيل الأول في قوم والثاني في آخرين وقيل الدعاء مذكور في الآيتين ودعاء عريض في الثاني"},{"id":"mutash-kirmani:466","bookId":"mutash-kirmani","type":"section","surah":41,"num":466,"title":"سورة فصلت","page":"ج1 ص222","text":"قوله {ولئن أذقناه رحمة منا من بعد ضراء مسته} بزيادة {منا} و {من} وفي هود {ولئن أذقناه نعماء بعد ضراء مسته} لأن ما في هذه السورة بين جهة الرحمة وبالكلام حاجة إلى ذكرها وحذف في هود اكتفاء بما قبله وهو قوله {ولئن أذقنا الإنسان منا رحمة} وزاد في هذه السورة {من} لأنه لما حد الرحمة والجهة الواقعة منها حد الطرف الذي بعدها ليتشاكلا في التحديد وفي هود لما أهمل الأول أهمل الثاني"},{"id":"mutash-kirmani:467","bookId":"mutash-kirmani","type":"section","surah":41,"num":467,"title":"سورة فصلت","page":"ج1 ص222","text":"قوله {أرأيتم إن كان من عند الله ثم كفرتم به} وفي الأحقاف {وكفرتم به} بالواو لأن معناه في هذه السورة كان عاقبة أمركم بعد الإمهال للنظر والتدبر الكفر فحسن دخول {ثم} وفي الأحقاف عطف عليه {وشهد شاهد} فلم يكن عاقبة أمرهم فكان من مواضع الواو"},{"id":"mutash-kirmani:468","bookId":"mutash-kirmani","type":"section","surah":42,"num":468,"title":"سورة الشورى","page":"ج1 ص223","text":"قوله {إن ذلك لمن عزم الأمور} وفي لقمان {من عزم الأمور} لأن الصبر على وجهين صبر على مكروه ينال الإنسان ظلما كمن قتل بعض بعض أعزته فالصبر على الأول أشد والعزم عليه أوكد وكان ما في هذه السورة من الجنس الأول لقوله {ولمن صبر وغفر} فأكد الخبر باللام وفي لقمان من الجنس الثاني فلم يؤكده"},{"id":"mutash-kirmani:469","bookId":"mutash-kirmani","type":"section","surah":42,"num":469,"title":"سورة الشورى","page":"ج1 ص223","text":"قوله {ومن يضلل الله فما له من ولي} وبعده {ومن يضلل الله فما له من سبيل}"},{"id":"mutash-kirmani:470","bookId":"mutash-kirmani","type":"section","surah":42,"num":470,"title":"سورة الشورى","page":"ج1 ص223","text":"ليس بتكرار لأن المعنى ليس له من هاد ولا ملجأ"},{"id":"mutash-kirmani:471","bookId":"mutash-kirmani","type":"section","surah":42,"num":471,"title":"سورة الشورى","page":"ج1 ص223","text":"قوله {إنه علي حكيم} ليس له نظير والمعنى تعالى أن يكلم أو يتناهى حكيم في تقسيم وجوه التكليم"},{"id":"mutash-kirmani:472","bookId":"mutash-kirmani","type":"section","surah":42,"num":472,"title":"سورة الشورى","page":"ج1 ص223","text":"قوله {لعل الساعة قريب} وفي الأحزاب {تكون قريبا} زيد معه {تكون} مراعاة للفواصل وقد سبق"},{"id":"mutash-kirmani:473","bookId":"mutash-kirmani","type":"section","surah":43,"num":473,"title":"سورة الزخرف","page":"ج1 ص224","text":"قوله {ما لهم بذلك من علم إن هم إلا يخرصون} وفي الجاثية {إن هم إلا يظنون} لأن ما في هذه السورة متصل بقوله {وجعلوا الملائكة الذين هم عباد الرحمن إناثا} والمعنى أنهم قالوا الملائكة بنات الله وإن الله قد شاء منا عبادتنا إياهم وهذا جهل منهم وكذب فقال سبحانه {ما لهم بذلك من علم إن هم إلا يخرصون} أي يكذبون وفي الجاثية خلطوا الصدق بالكذب فإن قولهم {نموت ونحيا} صدق فإن المعنى يموت السلف ويحيى الخلف وهي كذلك إلى أن تقوم الساعة وكذبوا في إنكارهم البعث وقولهم {وما يهلكنا إلا الدهر} ولهذا قال {إن هم إلا يظنون} أي هم شاكون فيما يقولون"},{"id":"mutash-kirmani:474","bookId":"mutash-kirmani","type":"section","surah":43,"num":474,"title":"سورة الزخرف","page":"ج1 ص224","text":"قوله {وإنا على آثارهم مهتدون} وبعده {مقتدون} خص الأول بالاهتداء لأنه كلام العرب في محاجتهم رسول الله صلى الله عليه وسلم وادعائهم {إن} آباءهم كانوا مهتدين فنحن مهتدون ولهذا قال عقبة {قال أولو جئتكم بأهدى} والثانية حكاية عمن كان قبلهم من الكفار وادعوا الاقتداء بالآباء دون الاهتداء فاقتضت كل آية ما ختمت به"},{"id":"mutash-kirmani:475","bookId":"mutash-kirmani","type":"section","surah":43,"num":475,"title":"سورة الزخرف","page":"ج1 ص224","text":"قوله {وإنا إلى ربنا لمنقلبون} وفي الشعراء {إلى ربنا منقلبون} لأن ما في هذه السورة عام لمن ركب سفينة أو دابة وقيل معناه إلى ربنا لمنقلبون على مركب آخر وهو الجنازة فحسن إدخال اللام على الخبر للعموم وما في الشعراء كلام السحرة حين آمنوا ولم يكن فيه عموم"},{"id":"mutash-kirmani:476","bookId":"mutash-kirmani","type":"section","surah":44,"num":476,"title":"سورة الدخان","page":"ج1 ص224","text":"قوله تعالى {إن هي إلا موتتنا الأولى} مرفوع وفي الصافات منصوب ذكر في المتشابه وليس منه لأن ما في هذه السورة مبتدأ وخبر وما في الصافات استثناء"},{"id":"mutash-kirmani:477","bookId":"mutash-kirmani","type":"section","surah":44,"num":477,"title":"سورة الدخان","page":"ج1 ص225","text":"قوله {ولقد اخترناهم على علم على العالمين} أي على علم منا ولم يقل في الجاثية وفضلناهم على علم بل قال { وفضلناهم على العالمين} لأنه مكرر في {وأضله الله على علم}"},{"id":"mutash-kirmani:478","bookId":"mutash-kirmani","type":"section","surah":45,"num":478,"title":"سورة الجاثية","page":"ج1 ص225","text":"قوله {وآتيناهم بينات من الأمر} نزلت في اليهود وقد سبق"},{"id":"mutash-kirmani:479","bookId":"mutash-kirmani","type":"section","surah":45,"num":479,"title":"سورة الجاثية","page":"ج1 ص225","text":"قوله {نموت ونحيا} قيل فيه تقديم {نموت} وتأخير {نحيا} قيل يحيا البعض ويموت البعض وقيل هو كلام من يقول بالتناسخ"},{"id":"mutash-kirmani:480","bookId":"mutash-kirmani","type":"section","surah":45,"num":480,"title":"سورة الجاثية","page":"ج1 ص225","text":"قوله {ولتجزى كل نفس بما كسبت} بالياء موافقة لقوله {ليجزي قوما بما كانوا يكسبون}"},{"id":"mutash-kirmani:481","bookId":"mutash-kirmani","type":"section","surah":45,"num":481,"title":"سورة الجاثية","page":"ج1 ص225","text":"قوله {سيئات ما عملوا} لتقدم {كنتم تعملون} {وعملوا الصالحات}"},{"id":"mutash-kirmani:482","bookId":"mutash-kirmani","type":"section","surah":45,"num":482,"title":"سورة الجاثية","page":"ج1 ص225","text":"قوله {ذلك هو الفوز المبين} تعظيما لإدخال الله المؤمنين في رحمته"},{"id":"mutash-kirmani:483","bookId":"mutash-kirmani","type":"section","surah":46,"num":483,"title":"سورة الأحقاف","page":"ج1 ص226","text":"ما في هذه السورة من التشابه قد سبق وذكر في المتشابه 14 و {أولئك} أي لم يجتمع في القرآن همزتان مضمومتان في غيرها"},{"id":"mutash-kirmani:484","bookId":"mutash-kirmani","type":"section","surah":46,"num":484,"title":"سورة الأحقاف","page":"ج1 ص226","text":"قوله {لولا نزلت سورة فإذا أنزلت سورة} نزل وأنزل كلاهما متعد وقيل نزل للتعدي والمبالغة وأنزل للتعدي وقيل نزل دفعة مجموعا وأنزل متفرقا وخص الأولى بنزلت لأنه من كلام المؤمنين وذكر بلفظ المبالغة وكانوا يأنسون لنزول الوحي ويستوحشون لإبطائه والثاني من كلام الله ولأن في أول السورة {نزل على محمد} وبعده {أنزل الله} كذلك في هذه الآية قال {نزلت} ثم {أنزلت}"},{"id":"mutash-kirmani:485","bookId":"mutash-kirmani","type":"section","surah":46,"num":485,"title":"سورة الأحقاف","page":"ج1 ص226","text":"قوله {من بعد ما تبين لهم الهدى الشيطان سول لهم} نزلت في اليهود وبعده {من بعد ما تبين لهم الهدى لن يضروا الله شيئا} نزلت في قوم ارتدوا وليس بتكرار"},{"id":"mutash-kirmani:486","bookId":"mutash-kirmani","type":"section","surah":48,"num":486,"title":"سورة الفتح","page":"ج1 ص226","text":"قوله عز وجل {ولله جنود السماوات والأرض وكان الله عليما حكيما} وبعده {عزيزا حكيما} لأن الأول متصل بإنزال السكينة وازدياد إيمان المؤمنين فكان الموضع موضع علم وحكمة وقد تقدم ما اقتضاه الفتح عند قوله {وينصرك الله نصرا عزيزا} وأما الثاني والثالث الذي بعده فمتصلان بالعذاب والغضب وسلب الأموال والغنائم فكان الموضع موضع عز وغلبة وحكمة"},{"id":"mutash-kirmani:487","bookId":"mutash-kirmani","type":"section","surah":48,"num":487,"title":"سورة الفتح","page":"ج1 ص227","text":"قوله {قل فمن يملك لكم من الله شيئا إن أراد بكم ضرا} وفي المائدة {فمن يملك من الله شيئا إن أراد أن يهلك المسيح} زاد في هذه السورة {لكم} لأن ما في هذه السورة نزلت في قوم بأعيانهم وهو المخلفون وما في المائدة عام لقوله {أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعا}"},{"id":"mutash-kirmani:488","bookId":"mutash-kirmani","type":"section","surah":48,"num":488,"title":"سورة الفتح","page":"ج1 ص227","text":"قوله {كذلكم قال الله} بلفظ الجمع وليس له نظير وهو خطاب للمضمرين في قوله {لن تتبعونا}"},{"id":"mutash-kirmani:489","bookId":"mutash-kirmani","type":"section","surah":49,"num":489,"title":"سورة الحجرات","page":"ج1 ص227","text":"قوله {إنما المؤمنون} مذكورة في السورة خمس مرات والمخاطبون المؤمنون والمخاطب به أمر ونهي وذكر في السادس {يا أيها الناس} فعم المؤمنين والكافرين والمخاطب به قوله {إنا خلقناكم من ذكر وأنثى} لأن الناس كلهم في ذلك شرع سواء"},{"id":"mutash-kirmani:490","bookId":"mutash-kirmani","type":"section","surah":50,"num":490,"title":"سورة ق","page":"ج1 ص227","text":"قوله {وقال قرينه} وبعده {قال قرينه} لأن الأول خطاب الإنسان من قرينه ومتصل بكلامه والثاني استئناف خطاب الله سبحانه به من غير اتصال بالمخاطب الأول وهو قوله {ربنا ما أطغيته}"},{"id":"mutash-kirmani:491","bookId":"mutash-kirmani","type":"section","surah":50,"num":491,"title":"سورة ق","page":"ج1 ص228","text":"وكذلك الجواب بغير واو وهو قوله {لا تختصموا لدي} وكذلك {ما يبدل القول لدي} فجاء الأول على نسق واحد"},{"id":"mutash-kirmani:492","bookId":"mutash-kirmani","type":"section","surah":50,"num":492,"title":"سورة ق","page":"ج1 ص228","text":"قوله {قبل طلوع الشمس وقبل الغروب} وفي طه {وقبل غروبها} لأن في هذه السورة راعى الفواصل وفي طه راعى القياس لأن الغروب للشمس كما أن الطلوع لها"},{"id":"mutash-kirmani:493","bookId":"mutash-kirmani","type":"section","surah":51,"num":493,"title":"سورة الذاريات","page":"ج1 ص228","text":"قوله {إن المتقين في جنات وعيون} {آخذين} وفي الطور {في جنات ونعيم} {فاكهين} ليس بتكرار لأن ما في هذه السورة متصل بذكر ما به يصل الإنسان إليها وهو قوله {كانوا قبل ذلك محسنين} وفي الطور متصل بما ينال الإنسان فيها إذا وصل إليها وهو قوله {ووقاهم ربهم عذاب الجحيم} {كلوا واشربوا} الآيات 18 19 20"},{"id":"mutash-kirmani:494","bookId":"mutash-kirmani","type":"section","surah":51,"num":494,"title":"سورة الذاريات","page":"ج1 ص228","text":"قوله {إني لكم منه نذير مبين} وبعده {إني لكم منه نذير مبين} ليس بتكرار لأن كل واحد منهما متعلق بغير ما تعلق به الآخر فالأول متعلق بترك الطاعة إلى المعصية والثاني متعلق بالشرك بالله تعالى"},{"id":"mutash-kirmani:495","bookId":"mutash-kirmani","type":"section","surah":52,"num":495,"title":"سورة الطور","page":"ج1 ص228","text":"قوله تعالى {أم يقولون شاعر} أعاد {أم} خمس عشرة مرة وكلها إلزامات ليس للمخاطبين بها جواب"},{"id":"mutash-kirmani:496","bookId":"mutash-kirmani","type":"section","surah":52,"num":496,"title":"سورة الطور","page":"ج1 ص229","text":"قوله {ويطوف عليهم} بالواو عطف على قوله { وأمددناهم} وكذلك {وأقبل} بالواو وفي الواقعة {يطوف} بغير واو فيحتمل أن يكون حالا أو يكون خبرا وفي الإنسان {ويطوف} عطف على {ويطاف}"},{"id":"mutash-kirmani:497","bookId":"mutash-kirmani","type":"section","surah":53,"num":497,"title":"سورة النجم","page":"ج1 ص229","text":"قوله تعالى {إن يتبعون إلا الظن} وبعده {إن يتبعون إلا الظن} ليس بتكرار لأن الأول متصل بعبادتهم اللات والعزى ومناة والثاني بعبادتهم الملائكة ثم ذم الظن فقال {وإن الظن لا يغني من الحق شيئا}"},{"id":"mutash-kirmani:498","bookId":"mutash-kirmani","type":"section","surah":53,"num":498,"title":"سورة النجم","page":"ج1 ص229","text":"قوله {ما أنزل الله بها من سلطان} في جميع القرآن بالألف إلا في الأعراف وقد سبق"},{"id":"mutash-kirmani:499","bookId":"mutash-kirmani","type":"section","surah":54,"num":499,"title":"سورة القمر","page":"ج1 ص229","text":"قصة نوح وعاد وثمود ولوط في كل واحدة منها من التخويف والتحذير مما حل بهم فيتعظ بها حامل القرآن وتاليه ويعظ غيره"},{"id":"mutash-kirmani:500","bookId":"mutash-kirmani","type":"section","surah":54,"num":500,"title":"سورة القمر","page":"ج1 ص230","text":"وأعاد في قصة عاد {فكيف كان عذابي ونذر} لأن الأولى في الدنيا والثانية في العقبى كما قال في هذه القصة {لنذيقهم عذاب الخزي في الحياة الدنيا ولعذاب الآخرة أخزى} وقيل الأول لتحذيرهم قبل إهلاكهم والثاني لتحذير غيرهم بهم بعد هلاكهم"},{"id":"mutash-kirmani:501","bookId":"mutash-kirmani","type":"section","surah":55,"num":501,"title":"سورة الرحمن","page":"ج1 ص230","text":"قوله {ووضع الميزان} أعاده ثلاث مرات فصرح ولم يضمر لكون كل واحد قائما بنفسه غير محتاج إلى الأول وقيل لأن كل واحد غير الآخر الأول ميزان الدنيا والثاني ميزان الآخرة والثالث ميزان العقل وقيل نزلت متفرقة فاقتضى الإظهار"},{"id":"mutash-kirmani:502","bookId":"mutash-kirmani","type":"section","surah":55,"num":502,"title":"سورة الرحمن","page":"ج1 ص230","text":"قوله {فبأي آلاء ربكما تكذبان} كرر الآية إحدى وثلاثين مرة ثمانية منها ذكرت عقيب آيات فيها تعداد عجائب خلق الله وبدائع صنعه ومبدأ الخلق ومعادهم ثم سبعة منها عقيب آيات فيها ذكر النار وشدائدها على عدد أبواب جهنم وحسن ذكر الآلاء عقيبها لأن في صرفها ودفعها نعما توازي النعم المذكورة أو لأنها حلت بالأعداء وذلك يعد أكبر النعماء وبعد هذه السبعة ثمانية في وصف الجنان وأهلها على عدد أبواب الجنة ثمانية أخرى بعدها للجنتين اللتين دونهما فمن اعتقد الثمانية الأولى وعمل بموجبها استحق كلتا الثمانيتين من الله ووقاه السبعة السابقة والله تعالى أعلم"},{"id":"mutash-kirmani:503","bookId":"mutash-kirmani","type":"section","surah":56,"num":503,"title":"سورة الواقعة","page":"ج1 ص231","text":"قوله {فأصحاب الميمنة ما أصحاب الميمنة} أعاد ذكرها وكذلك {المشأمة} ثم قال {والسابقون} لأن التقدير عند بعضهم والسابقون ما السابقون فحذف { ما} لدلالة ما قبله عليه وقيل تقديره أزواجا أزواجا ثلاثة فأصحاب الميمنة وأصحاب المشئمة والسابقون ثم ذكر عقيب كل واحد منهم تعظيما وتهويلا فقال {ما أصحاب الميمنة} {ما أصحاب المشأمة} {والسابقون} أي هم السابقون والكلام فيه"},{"id":"mutash-kirmani:504","bookId":"mutash-kirmani","type":"section","surah":56,"num":504,"title":"سورة الواقعة","page":"ج1 ص231","text":"قوله تعالى {أفرأيتم ما تمنون} {أفرأيتم ما تحرثون} {أفرأيتم الماء الذي تشربون} {أفرأيتم النار التي تورون} بدأ بذكر خلق الإنسان ثم {ذكر} مالا غنى له عنه وهو الحب الذي منه قوامه وقرته ثم الماء الذي منه سوغه وعجنه ثم النار التي منه نضجه وصلاحه وذكر عقيب كل ما يأتي عليه ويفسده فقال في الأولى {نحن قدرنا بينكم الموت} وفي الثانية {لو نشاء لجعلناه حطاما} وفي الثالثة {لو نشاء جعلناه أجاجا} ولم يقل في الرابعة ما يفسدها بل قال {نحن جعلناها تذكرة} يتعظون بها {ومتاعا للمقوين} أي المفسرين ينتفعون بها"},{"id":"mutash-kirmani:505","bookId":"mutash-kirmani","type":"section","surah":57,"num":505,"title":"سورة الحديد","page":"ج1 ص231","text":"قوله تعالى {سبح لله} وكذلك الحشر والصف ثم {يسبح} في الجمعة 1 والتغابن 1 هذه الكلمة استأثر الله بها فبدأ بالمصدر في بني إسرائيل الإسراء لأنه الأصل ثم بالماضي لأنه أسبق الزمانين ثم بالمستقبل ثم بالأمر في سورة الأعلى استيعابا لهذه الكلمة من جميع جهاتها وهي أربع المصدر والماضي والمستقبل والأمر للمخاطب"},{"id":"mutash-kirmani:506","bookId":"mutash-kirmani","type":"section","surah":57,"num":506,"title":"سورة الحديد","page":"ج1 ص232","text":"قوله {ما في السماوات والأرض} وفي السور الخمس {ما في السماوات وما في الأرض} إعادة {ما} هو الأصل وخصت هذه السورة بالحذف موافقة لما بعدها وهو {خلق السماوات والأرض} وبعدها {له ملك السماوات والأرض} لأن التقدير في هذه السورة سبح لله خلق السموات والأرض وكذلك قال في آخر الحشر بعده قوله {الخالق البارئ المصور له الأسماء الحسنى يسبح له ما في السماوات والأرض} أي خلقهما"},{"id":"mutash-kirmani:507","bookId":"mutash-kirmani","type":"section","surah":57,"num":507,"title":"سورة الحديد","page":"ج1 ص232","text":"قوله {له ملك السماوات والأرض} وبعده {له ملك السماوات والأرض} ليس بتكرار لأن الأولى {في الدنيا} يحيي ويميت والثاني في العقبى لقوله {وإلى الله ترجع الأمور}"},{"id":"mutash-kirmani:508","bookId":"mutash-kirmani","type":"section","surah":57,"num":508,"title":"سورة الحديد","page":"ج1 ص232","text":"قوله {ذلك هو الفوز العظيم} بزيادة {هو} لأن {بشراكم} مبتدأ وجنات خبره {تجري من تحتها} صفة لها {خالدين فيها} حال {ذلك} إشارة إلى ما قبله و {هو} تنبيه على عظم شأن المذكور {الفوز العظيم} خبره"},{"id":"mutash-kirmani:509","bookId":"mutash-kirmani","type":"section","surah":57,"num":509,"title":"سورة الحديد","page":"ج1 ص232","text":"قوله {لقد أرسلنا رسلنا بالبينات} ابتداء الكلام {ولقد أرسلنا نوحا} عطف عليه"},{"id":"mutash-kirmani:510","bookId":"mutash-kirmani","type":"section","surah":57,"num":510,"title":"سورة الحديد","page":"ج1 ص233","text":"قوله {ما أصاب من مصيبة في الأرض ولا في أنفسكم} وفي التغابن {من مصيبة إلا بإذن الله} فصل في هذه السورة وأجمل هناك موافقة لما قبلها في هذه السورة فإنه فصل أحوال الدنيا والآخرة فيها بقوله {اعلموا أنما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الأموال والأولاد}"},{"id":"mutash-kirmani:511","bookId":"mutash-kirmani","type":"section","surah":58,"num":511,"title":"سورة المجادلة","page":"ج1 ص233","text":"قوله تعالى {الذين يظاهرون منكم من نسائهم} وبعده {والذين يظاهرون من نسائهم} لأن الأول خطاب للعرب وكان طلاقهم في الجاهلية الظهار فقيده بقوله {منكم} وبقوله {وإنهم ليقولون منكرا من القول وزورا} ثم بين أحكام الظهار للناس عامة فعطف عليه فقال {والذين يظاهرون من نسائهم} فجاء في كل آية ما اقتضاه معناه"},{"id":"mutash-kirmani:512","bookId":"mutash-kirmani","type":"section","surah":58,"num":512,"title":"سورة المجادلة","page":"ج1 ص233","text":"قوله {وللكافرين عذاب أليم} وبعده {وللكافرين عذاب مهين}"},{"id":"mutash-kirmani:513","bookId":"mutash-kirmani","type":"section","surah":58,"num":513,"title":"سورة المجادلة","page":"ج1 ص233","text":"لأن الأول متصل بضده وهو الإيمان فتوعد على الكفر بالعذاب الأليم الذي هو جزاء الكافرين والثاني متصل بقوله {كبتوا كما كبت الذين من قبلهم} وهو الإذلال والإهانة فوصف العذاب بمثل ذلك فقال {مهين}"},{"id":"mutash-kirmani:514","bookId":"mutash-kirmani","type":"section","surah":58,"num":514,"title":"سورة المجادلة","page":"ج1 ص234","text":"قوله {جهنم يصلونها فبئس المصير} بالفاء لما فيه من معنى التعقيب أي بئس المصير ما صاروا إليه وهو جهنم"},{"id":"mutash-kirmani:515","bookId":"mutash-kirmani","type":"section","surah":58,"num":515,"title":"سورة المجادلة","page":"ج1 ص234","text":"قوله {من الله شيئا أولئك} بغير فاء موافقة للجمل التي قبلها وموافقة لقوله {أولئك حزب الله}"},{"id":"mutash-kirmani:516","bookId":"mutash-kirmani","type":"section","surah":59,"num":516,"title":"سورة الحشر","page":"ج1 ص234","text":"قوله {وما أفاء الله} وبعدها {ما أفاء} بغير واو لأن الأول معطوف على قوله {ما قطعتم من لينة} والثاني استئناف كلام وليس له به تعلق وقول من قال إنه بدل من الأول مزيف عند أكثر المفسرين"},{"id":"mutash-kirmani:517","bookId":"mutash-kirmani","type":"section","surah":59,"num":517,"title":"سورة الحشر","page":"ج1 ص234","text":"قوله {ذلك بأنهم قوم لا يفقهون} وبعده {قوم لا يعقلون} لأن الأول متصل بقوله {لأنتم أشد رهبة في صدورهم من الله} لأنهم يرون الظاهر ولا يفقهون علم ما استتر عليهم والفقه معرفة ظاهر الشيء وغامضه بسرعة فطنة فنفى عنهم ذلك والثاني متصل بقوله {تحسبهم جميعا وقلوبهم شتى} أي لو عقلوا لاجتمعوا على الحق ولم يتفرقوا"},{"id":"mutash-kirmani:518","bookId":"mutash-kirmani","type":"section","surah":60,"num":518,"title":"سورة الممتحنة","page":"ج1 ص235","text":"قوله تعالى {تلقون إليهم بالمودة} وبعده {تسرون إليهم بالمودة} الأول حال من المخاطبين وقيل أتلقون إليهم والاستفهام مقدر وقيل خبر مبتدأ أي أنتم تلقون والثاني بدل من الأول على الوجوه المذكورة والباء زيادة عند الأخفش وقيل بسبب أن تودوا وقال الزجاج تلقون إليهم أخبار النبي صلى الله عليه وسلم وسره بالمودة"},{"id":"mutash-kirmani:519","bookId":"mutash-kirmani","type":"section","surah":60,"num":519,"title":"سورة الممتحنة","page":"ج1 ص235","text":"قوله {قد كانت لكم أسوة حسنة} وبعده {لقد كان لكم فيهم أسوة حسنة} أنث الفعل الأول مع الحائل وذكر الثاني لكثرة الحائل وإنما كرر لأن الأول في القول والثاني في الفعل وقيل الأول في إبراهيم والثاني في محمد صلى الله عليه وسلم"},{"id":"mutash-kirmani:520","bookId":"mutash-kirmani","type":"section","surah":61,"num":520,"title":"سورة الصف","page":"ج1 ص235","text":"قوله {ومن أظلم ممن افترى على الله الكذب} بالألف واللام في غرها {افترى على الله كذبا} بالنكرة لأنها أكثر استعمالا في المصدر في المعرفة وخصت هذه السورة بالمعرفة لأنه إشارة إلى ما تقدم من قول اليهود والنصارى"},{"id":"mutash-kirmani:521","bookId":"mutash-kirmani","type":"section","surah":61,"num":521,"title":"سورة الصف","page":"ج1 ص235","text":"قوله {ليطفئوا} باللام لأن المفعول محذوف وقيل اللام زيادة وقيل محمول على المصدر"},{"id":"mutash-kirmani:522","bookId":"mutash-kirmani","type":"section","surah":61,"num":522,"title":"سورة الصف","page":"ج1 ص235","text":"قوله {يغفر لكم ذنوبكم} جزم على جواب الأمر فإن قوله {تؤمنون} محمول على الأمر أي آمنوا وليس بعده {من} ولا {خالدين}"},{"id":"mutash-kirmani:523","bookId":"mutash-kirmani","type":"section","surah":62,"num":523,"title":"سورة الجمعة","page":"ج1 ص235","text":"قوله {ولا يتمنونه} وفي البقرة {ولن يتمنوه} سبق"},{"id":"mutash-kirmani:524","bookId":"mutash-kirmani","type":"section","surah":63,"num":524,"title":"سورة المنافقون","page":"ج1 ص236","text":"قوله {ولكن المنافقين لا يفقهون} وبعده {لا يعلمون} لأن الأول متصل بقوله {ولله خزائن السماوات والأرض} وفي معرفتها غموض يحتاج إلى فطنة والمنافق لا فطنة له والثاني متصل بقوله {ولله العزة ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون} معز لأوليائه ومذل لأعدائه"},{"id":"mutash-kirmani:525","bookId":"mutash-kirmani","type":"section","surah":64,"num":525,"title":"سورة التغابن","page":"ج1 ص236","text":"قوله {يسبح لله ما في السماوات وما في الأرض} {يعلم ما في السماوات والأرض ويعلم ما تسرون وما تعلنون} إنما كرر {ما} في أول السورة لاختلاف تسبيح أهل الأرض وتسبيح أهل اسم السماء في الكثرة والقلة والبعد والقرب من المعصية والطاعة وكذلك {ما تسرون وما تعلنون} فإنهما ضدان ولم يكرر معها {يعلم} لأن الكل بالإضافة إلى علم الله سبحانه جنس واحد لا يخفى عليه شيء"},{"id":"mutash-kirmani:526","bookId":"mutash-kirmani","type":"section","surah":64,"num":526,"title":"سورة التغابن","page":"ج1 ص236","text":"قوله {ومن يؤمن بالله ويعمل صالحا يكفر عنه سيئاته ويدخله جنات تجري من تحتها الأنهار خالدين فيها أبدا} ومثله في الطلاق سواء لكنه زاد هنا {يكفر عنه سيئاته} لأن ما في هذه السورة جاء بعد قوله {أبشر يهدوننا} الآيات فأخبر عن الكفار سيئات تحتاج إلى تفكير إذا آمنوا بالله ولم يتقدم الخبر عن الكفار بسيئات في الطلاق فلم يحتج إلى ذكرها"},{"id":"mutash-kirmani:527","bookId":"mutash-kirmani","type":"section","surah":65,"num":527,"title":"سورة الطلاق","page":"ج1 ص237","text":"قوله تعالى {ومن يتق الله يجعل له مخرجا} أمر بالتقوى في أحكام الطلاق ثلاث مرات ووعد في كل مرة نوعا من الجزاء فقال أولا {يجعل له مخرجا} يخرجه مما دخل فيه وهو يكرهه ويبيح له محبوبه من حيث لا يأمل وقال في الثاني يسهل عليه الصعب من أمره ويبيح له خيرا ممن طلقها والثالث وعد عليه أفضل الجزاء وهو ما يكون في الآخرة من النعماء"},{"id":"mutash-kirmani:528","bookId":"mutash-kirmani","type":"section","surah":66,"num":528,"title":"سورة التحريم","page":"ج1 ص237","text":"قوله {خيرا منكن مسلمات مؤمنات} ذكر الجميع بغير واو ثم ختم بالواو فقال {وأبكارا} لأنه استحال العطف على ثيبات فعطفها على أول الكلام ويحسن الوقف على ثيبيات لما استحال عطف أبكارا عليها وقول من قال إنها واو والثمانية بعيد وقد سبق"},{"id":"mutash-kirmani:529","bookId":"mutash-kirmani","type":"section","surah":67,"num":529,"title":"سورة الملك","page":"ج1 ص238","text":"قوله {فارجع البصر} وبعده {ثم ارجع البصر كرتين} أي مع الكرة الأولى وقيل هي ثلاث مرات أي ارجع البصر وهذه مرة ثم أرجع البصر كرتين فمجموعهما ثلاث مرات قلت يحتمل أن يكون أربع مرات لأن قوله {أرجع} يدل على سابقه مرة"},{"id":"mutash-kirmani:530","bookId":"mutash-kirmani","type":"section","surah":67,"num":530,"title":"سورة الملك","page":"ج1 ص238","text":"قوله {أأمنتم من في السماء أن يخسف بكم الأرض} وبعده {أن يرسل عليكم حاصبا} خوفهم بالخسف أولا لكونهم على الأرض وبعده {أن يرسل عليكم حاصبا} فلذلك جاء ثانية"},{"id":"mutash-kirmani:531","bookId":"mutash-kirmani","type":"section","surah":67,"num":531,"title":"سورة الملك","page":"ج1 ص238","text":"قوله تعالى {حلاف مهين} إلى قوله {زنيم} أوصاف تسعة ولم يدخل بينها واو العطف ولا بعد السابع فدل على ضعف القول بواو الثمانية"},{"id":"mutash-kirmani:532","bookId":"mutash-kirmani","type":"section","surah":69,"num":532,"title":"سورة الحاقة","page":"ج1 ص239","text":"قوله {فأما من أوتي كتابه بيمينه} بالفاء وبعده {وأما} بالواو لأن الأول متصل بأحوال القيامة وأهوالها فاقتضى الفاء للتعقيب والثاني متصل بالأول فأدخل الواو لأنه للجمع"},{"id":"mutash-kirmani:533","bookId":"mutash-kirmani","type":"section","surah":69,"num":533,"title":"سورة الحاقة","page":"ج1 ص239","text":"قوله {وما هو بقول شاعر قليلا ما تؤمنون} {ولا بقول كاهن قليلا ما تذكرون} خص ذكر الشعر بقوله {ما تؤمنون} لأن من قال القرآن شعر ومحمد شاعر بعد ما علم اختلاف آيات القرآن في الطول والقصر واختلاف حروف مقاطعه فلكفره وقلة إيمانه فإن الشعر كلام موزون مقفى وخص ذكر الكهانة بقوله {ما تذكرون} لأن من ذهب إلى أن القرآن كهانة وأن محمدا كاهن فهو ذاهل عن كلام الكهان فإنه أسجاع لا معاني تحتها وأوضاع تنبو الطباع عنها ولا يكون في كلامهم ذكر الله تعالى"},{"id":"mutash-kirmani:534","bookId":"mutash-kirmani","type":"section","surah":70,"num":534,"title":"سورة المعارج","page":"ج1 ص240","text":"قوله {إلا المصلين} وعقيبه ذكر الخصال المذكورة أول سورة المؤمنين وزاد فيها {والذين هم بشهاداتهم قائمون} لأنه وقع عقيب قوله {لأماناتهم وعهدهم راعون} وإقامة الشهادة أمانة يؤديها إذا احتاج إليها صاحبها لإحياء حق فهي إذن من جملة الأمانة وقد ذكرت الأمانة في سورة المؤمنين وخصت هذه السورة بزيادة بيانها كما خصت بإعادة ذكر الصلاة حيث قال {والذين هم على صلواتهم يحافظون} بعد قوله {إلا المصلين} { الذين هم على صلاتهم دائمون}"},{"id":"mutash-kirmani:535","bookId":"mutash-kirmani","type":"section","surah":71,"num":535,"title":"سورة نوح","page":"ج1 ص240","text":"قوله {قال نوح} بغير واو ثم قال {وقال نوح} بزيادة الواو لأن الأول ابتداء دعاء والثاني عطف عليه"},{"id":"mutash-kirmani:536","bookId":"mutash-kirmani","type":"section","surah":71,"num":536,"title":"سورة نوح","page":"ج1 ص240","text":"قوله {ولا تزد الظالمين إلا ضلالا} وبعده {إلا تبارا} لأن الأول وقع بعد قوله {وقد أضلوا كثيرا} والثاني بعد قوله {لا تذر على الأرض من الكافرين ديارا} فذكر في كل مكان ما اقتضاه معناه"},{"id":"mutash-kirmani:537","bookId":"mutash-kirmani","type":"section","surah":72,"num":537,"title":"سورة الجن","page":"ج1 ص241","text":"قوله {وأنه تعالى جد ربنا} كرر {إن} مرات واختلف القراء في اثنتي عشرة منها وهي من قوله {وأنه تعالى} إلى قوله {وأنا منا المسلمون} ففتحها بعضهم عطفا على {أوحي إلي أنه} وكسرها بعضهم على قوله {إنا سمعنا} وبعضهم فتح أنه عطفا على {أنه} وكسر إنا عطفا على {إنا} وهو شاذ"},{"id":"mutash-kirmani:538","bookId":"mutash-kirmani","type":"section","surah":73,"num":538,"title":"سورة المزمل","page":"ج1 ص241","text":"قوله {فاقرؤوا ما تيسر من القرآن} وبعده {فاقرؤوا ما تيسر منه} لأن الأول في الفرض وقيل في النافلة وقيل خارج الصلاة ثم ذكر سبب التخفيف فقال {علم أن سيكون منكم مرضى} ثم أعاده فقال {فاقرؤوا ما تيسر منه} والأكثرون على أنه في صلاة المغرب والعشاء"},{"id":"mutash-kirmani:539","bookId":"mutash-kirmani","type":"section","surah":74,"num":539,"title":"سورة المدثر","page":"ج1 ص241","text":"قوله {إنه فكر وقدر} {فقتل كيف قدر} {ثم قتل كيف قدر} أعاد {كيف قدر} مرتين وأعاد {قدر} ثلاث مرات لأن التقدير إنه أي الوليد فكر في بيان محمد صلى الله عليه وسلم وما أتى به وقدر ما يمكنه أن يقول فيهما فقال الله سبحانه {فقتل كيف قدر} أي القول في محمد {ثم قتل كيف قدر} أي القول في القرآن"},{"id":"mutash-kirmani:540","bookId":"mutash-kirmani","type":"section","surah":74,"num":540,"title":"سورة المدثر","page":"ج1 ص242","text":"قوله {كلا إنه تذكرة} أي تذكير وعدل إليها للفاصلة وقوله {إنه تذكرة} {فمن شاء ذكره} وفي عبس {إنها تذكرة} لأن تقدير الآية في هذه السورة إن القرآن تذكرة وفي عبس إن آيات القرآن تذكرة وقيل حمل التذكرة على التذكير لأنها بمعناه"},{"id":"mutash-kirmani:541","bookId":"mutash-kirmani","type":"section","surah":75,"num":541,"title":"سورة القيامة","page":"ج1 ص242","text":"قوله {لا أقسم بيوم القيامة} ثم أعاد فقال {ولا أقسم بالنفس اللوامة} فيه ثلاثة أقوال أحدها أنه سبحانه أقسم بهما والثاني لم يقسم بهما والثالث أقسم بيوم القيامة ولم يقسم بالنفس اللوامة وقد سبق بيانه في التفسير"},{"id":"mutash-kirmani:542","bookId":"mutash-kirmani","type":"section","surah":75,"num":542,"title":"سورة القيامة","page":"ج1 ص242","text":"قوله {وخسف القمر} وكرر في الآية الثانية {وجمع الشمس والقمر} لأن الأول عبارة عن بياض العين بدليل قوله {فإذا برق البصر} وفيه قول ثان وهو قول الجمهور إنهما بمعنى واحد وجاز تكراره لأنه أخبر عنه بغير الخبر الأول وقيل الثاني وقع موقع الكناية كقوله {قد سمع الله قول التي تجادلك في زوجها وتشتكي إلى الله والله يسمع تحاوركما إن الله سميع بصير}"},{"id":"mutash-kirmani:543","bookId":"mutash-kirmani","type":"section","surah":75,"num":543,"title":"سورة القيامة","page":"ج1 ص242","text":"فصرح تعظيما وتفخيما وتيمنا قلت ويحتمل أن يقال أراد بالأول الشمس قياسا على القمرين ولهذا ذكر فقال {وجمع الشمس والقمر} أي جمع القمران فإن التثنية أخت العطف وهي دقيقة"},{"id":"mutash-kirmani:544","bookId":"mutash-kirmani","type":"section","surah":75,"num":544,"title":"سورة القيامة","page":"ج1 ص243","text":"قوله {أولى لك فأولى} كررها مرتين بل كررها أربع مرات فإن قوله {أولي} تام في الذم بدليل قوله {فأولى لهم} فإن جمهور المفسرين ذهبوا إلى أنه للتهديد وإنما كررها لأن المعنى أولى لك الموت فأولى لك العذاب في القبر ثم أولى لك أهوال القيامة وأولى لك عذاب النار نعوذ بالله منها"},{"id":"mutash-kirmani:545","bookId":"mutash-kirmani","type":"section","surah":76,"num":545,"title":"سورة الإنسان","page":"ج1 ص243","text":"قوله {ويطاف عليهم} وبعده {ويطوف عليهم} إنما ذكر الأول بلفظ المجهول لأن المقصود ما يطاف به لا الطائفون ولهذا قال {بآنية من فضة} ثم ذكر الطائفين فقال {ويطوف عليهم ولدان مخلدون}"},{"id":"mutash-kirmani:546","bookId":"mutash-kirmani","type":"section","surah":76,"num":546,"title":"سورة الإنسان","page":"ج1 ص243","text":"قوله {مزاجها كافورا} وبعدها {زنجبيلا} {سلسبيلا} لأن الثانية غير الأولى وقيل كافور اسم علم لذلك الماء واسم الثاني زنجبيل وقيل اسمها سلسبيلا قال ابن المبارك سل من الله إليه سلسبيلا ويجوز أن يكون اسمها زنجبيلا ثم ابتدأ فقال سل سبيلا ويجوز أن يكون اسمها هذه الجملة كقولهم تأبط شرا وبرق نحره ويجوز أن يكون معنى تسمى تذكر ثم قال الله سل سبيلا واتصاله في المصحف لا يمنع هذا التأويل لكثرة أمثاله فيه"},{"id":"mutash-kirmani:547","bookId":"mutash-kirmani","type":"section","surah":77,"num":547,"title":"سورة المرسلات","page":"ج1 ص244","text":"قوله {ويل يومئذ للمكذبين} مكرر عشرات مرات لأن كل واحد منها ذكرت عقيب آية غير الأولى فلا يكون تكرارا مستهجنا ولو لم يكرر كان متوعدا على بعض دون بعض وقيل إن من عادة العرب التكرار والإطناب كما في عادتهم الاقتصار والإيجاز ولأن بسط الكلام في الترغيب والترهيب أدعى إلا إدراك البغية من الإيجاز"},{"id":"mutash-kirmani:548","bookId":"mutash-kirmani","type":"section","surah":78,"num":548,"title":"سورة النبأ","page":"ج1 ص244","text":"قوله {كلا سيعلمون} {ثم كلا سيعلمون} قيل التكرار للتأكيد وقيل الأول للكفار والثاني للمؤمنين وقيل الأول عند النزع والثاني في القيامة وقيل الأول ردع عن الاختلاف والثاني عن الكفر"},{"id":"mutash-kirmani:549","bookId":"mutash-kirmani","type":"section","surah":78,"num":549,"title":"سورة النبأ","page":"ج1 ص244","text":"قوله {جزاء وفاقا} وبعده {جزاء من ربك عطاء حسابا} لأن الأول للكفار وقد قال الله تعالى {وجزاء سيئة سيئة مثلها} فيكون جزاؤهم على وفق أعمالهم والثاني للمؤمنين وجزائهم جزاء وافيا كافيا فلهذا قال {حسابا} أي كافيا من قولك حسبي وظني"},{"id":"mutash-kirmani:550","bookId":"mutash-kirmani","type":"section","surah":79,"num":550,"title":"سورة النازعات","page":"ج1 ص245","text":"قوله {فإذا جاءت الطامة الكبرى} وفي غيرها {الصاخة} لأن الطامة مشتقة من طممت البئر إذا كسبتها وسميت القيامة طامة لأنها تكبس كل شيء وتكسره وسميت الصاخة والصاخة من الصخ الصوت الشديد لأنه بشدة صوتها يجثو لها الناس كما ينتبه النائم بالصوت الشديد وخصت النازعات بالطامة لأن الطم قبل الصخ والفزع قبل الصوت فكانت هي السابقة وخصت عبس بالصاخة لأنها بعدها وهي اللاحقة"},{"id":"mutash-kirmani:551","bookId":"mutash-kirmani","type":"section","surah":81,"num":551,"title":"سورة التكوير","page":"ج1 ص245","text":"قوله {وإذا البحار سجرت} وفي الإنفطار {وإذا البحار فجرت} لأن معنى سجرت عند أكثر المفسرين أوقدت فصارت نارا من قولهم سجرت التنور وقيل هي بحار جهنم تملأ حميما فيعاقب بها أهل النار فخصت هذه السورة بسجرت موافقة لقوله {سعرت} ليقع الوعيد بتسعير النار وتسجير البحار وفي الانفطار وافق قوله {وإذا الكواكب انتثرت} أي تساقطت {وإذا البحار فجرت} أي سألت مياهها ففاضت على وجه الأرض {وإذا القبور بعثرت} قلبت وأثيرت وهذه الأشياء كلها زايلت أماكنها فلاقت كل واحدة قرائنها"},{"id":"mutash-kirmani:552","bookId":"mutash-kirmani","type":"section","surah":81,"num":552,"title":"سورة التكوير","page":"ج1 ص246","text":"قوله {علمت نفس ما أحضرت} وفي الانفطار {ما قدمت وأخرت} لأن ما في هذه السورة متصل بقوله {وإذا الصحف نشرت} فقرأها أربابها فعلموا ما أحضرت وفي الانفطار متصل بقوله {وإذا القبور بعثرت} والقبور كانت في الدنيا فيذكرون ما قدموا في الدنيا وما أخروا في العقبى فكل خاتمة لائقة بمكانها وهذه السورة من أولها شرط وجزاء وقسم وجواب"},{"id":"mutash-kirmani:553","bookId":"mutash-kirmani","type":"section","surah":82,"num":553,"title":"سورة الانفطار","page":"ج1 ص246","text":"سبق ما فيها وقوله {وما أدراك ما يوم الدين ثم ما أدراك ما يوم الدين} تكرار أفاد التعظيم ليوم الدين وقيل أحدهما للمؤمن والثاني للكافر"},{"id":"mutash-kirmani:554","bookId":"mutash-kirmani","type":"section","surah":83,"num":554,"title":"سورة المطففين","page":"ج1 ص246","text":"قوله {كلا إن كتاب الفجار لفي سجين} {وما أدراك ما سجين} {كتاب مرقوم} وبعده {كلا إن كتاب الأبرار لفي عليين} {وما أدراك ما عليون} {كتاب مرقوم} التقدير فيهما إن كتاب الفجار لكتاب مرقوم في سجين وإن كتاب الأبرار لكتاب مرقوم في عليين ثم ختم الأول بقوله {ويل يومئذ للمكذبين} لأنه في حق الفجار وختم الثاني بقوله {يشهده المقربون} فختم كل واحد بما لا يصلح سواه مكانه"},{"id":"mutash-kirmani:555","bookId":"mutash-kirmani","type":"section","surah":84,"num":555,"title":"سورة الانشقاق","page":"ج1 ص246","text":"قوله {وأذنت لربها وحقت} مرتين لأن الأول متصل بالسماء والثاني متصل بالأرض ومعنى أذنت سمعت وانقادت وحق لها أن تسمع وتطيع وإذا اتصل بغير ما اتصل به الآخر لا يكون تكرارا"},{"id":"mutash-kirmani:556","bookId":"mutash-kirmani","type":"section","surah":84,"num":556,"title":"سورة الانشقاق","page":"ج1 ص247","text":"قوله {بل الذين كفروا يكذبون} وفي البروج {في تكذيب} راعى فواصل الآي مع صحة اللفظ وجودة المعنى"},{"id":"mutash-kirmani:557","bookId":"mutash-kirmani","type":"section","surah":84,"num":557,"title":"سورة الانشقاق","page":"ج1 ص247","text":"قوله {ذلك الفوز الكبير} ذلك مبتدأ والفوز خبره والكبير صفته وليس في القرآن نظير"},{"id":"mutash-kirmani:558","bookId":"mutash-kirmani","type":"section","surah":86,"num":558,"title":"سورة الطارق","page":"ج1 ص247","text":"قوله {فمهل الكافرين أمهلهم رويدا} هذا تكرار وتقديره مهل مهل مهل لكنه عدل في الثاني إلى أن أمهل لأنه من أصله وبمعناه كراهة التكرار وعدل في الثالث إلى قوله {رويدا} لأنه بمعناه أي إروادا ثم إروادا ثم صغر إروادا تصغير الترخيم فصار رويدا وذهب بعضهم إلى أن رويدا صفة مصدر محذوف أي إمهالا رويدا فيكون التكرار مرتين وهذه أعجوبة"},{"id":"mutash-kirmani:559","bookId":"mutash-kirmani","type":"section","surah":87,"num":559,"title":"سورة الأعلى","page":"ج1 ص248","text":"قوله {سبح اسم ربك الأعلى} {الذي خلق فسوى} وفي العلق {اقرأ باسم ربك الذي خلق} زاد في هذه السورة {الأعلى} مراعاة للفواصل وفي هذه السورة {الذي خلق فسوى} وفي العلق {خلق الإنسان من علق}"},{"id":"mutash-kirmani:560","bookId":"mutash-kirmani","type":"section","surah":88,"num":560,"title":"سورة الغاشية","page":"ج1 ص248","text":"قوله {وجوه يومئذ} وبعده {وجوه يومئذ} ليس بتكرار لأن الأول هم الكفار والثاني المؤمنون وكان القياس أن يكون الثاني بالواو للعطف لكنه جاء على وفاق الجمل قبلها وبعدها وليس معهن واو العطف ألبته"},{"id":"mutash-kirmani:561","bookId":"mutash-kirmani","type":"section","surah":88,"num":561,"title":"سورة الغاشية","page":"ج1 ص248","text":"قوله {وأكواب موضوعة} {ونمارق} كلها قد سبق وقوله {إلى السماء} و {وإلى الجبال} ليس من الجمل بل هي أتباع لما قبلها"},{"id":"mutash-kirmani:562","bookId":"mutash-kirmani","type":"section","surah":89,"num":562,"title":"سورة الفجر","page":"ج1 ص248","text":"قوله تعالى {فأما الإنسان إذا ما ابتلاه ربه} وبعده {وأما إذا ما ابتلاه} لأن التقدير في الثاني أيضا وأما الإنسان فاكتفى بذكره في الأول والفاء لازم بعده لأن المعنى مهما يكن من شيء فالإنسان بهذه الصفة لكن الفاء أخرت ليكون على لفظ الشرط والجزاء"},{"id":"mutash-kirmani:563","bookId":"mutash-kirmani","type":"section","surah":90,"num":563,"title":"سورة البلد","page":"ج1 ص249","text":"قوله {لا أقسم بهذا البلد} ثم قال {وأنت حل بهذا البلد} كرره وجعله فاصلا في الآيتين وقد سبق القول في مثل هذا ومما ذكر في هذه السورة على الخصوص أن التقدير لا أقسم بهذا البلد وهو حرام وأنت حل بهذا البلد وهو حلال لأنه أحلت له مكة حتى قتل فيها من شاء وقاتل فلما اختلف معناه صار كأنه غير الأول ودخل في القسم الذي يختلف معناه ويتفق لفظه"},{"id":"mutash-kirmani:564","bookId":"mutash-kirmani","type":"section","surah":91,"num":564,"title":"سورة الشمس","page":"ج1 ص249","text":"قوله {إذ انبعث أشقاها} قيل هما رجلان قدار ابن سالف ومصدع بن يزدهر فوحد لروى الآية"},{"id":"mutash-kirmani:565","bookId":"mutash-kirmani","type":"section","surah":92,"num":565,"title":"سورة الليل","page":"ج1 ص249","text":"قوله {فسنيسره لليسرى} وبعده {فسنيسره للعسرى} أي نسهله للحالة اليسرى والحالة العسرى وقيل الأولى الجنة والثانية النار ولفظة سنيسره وجاء في الخبر اعملوا فكل ميسر لما خلق له"},{"id":"mutash-kirmani:566","bookId":"mutash-kirmani","type":"section","surah":93,"num":566,"title":"سورة الضحى","page":"ج1 ص250","text":"قوله تعالى {فأما اليتيم فلا تقهر} كرر {أما} ثلاث مرات لأنها وقعت في مقابلة ثلاث آيات أيضا وهي {ألم يجدك يتيما فآوى ووجدك ضالا فهدى} {ووجدك عائلا فأغنى} { فأما اليتيم فلا تقهر} واذكر يتمك {وأما السائل فلا تنهر} واذكر فقرك {وأما بنعمة ربك فحدث} واذكر ضلالك والإسلام ولقوله {ضالا} وجوه ذكرت في موضعها"},{"id":"mutash-kirmani:567","bookId":"mutash-kirmani","type":"section","surah":32,"num":567,"title":"سورة السجدة","page":"ج1 ص250","text":"قوله تعالى {فإن مع العسر يسرا} {إن مع العسر يسرا} ليس بتكرار لأن المعنى إن مع العسر الذي أنت فيه من مقاساة الكفار يسرا في العاجل وإن مع العسر الذي أنت فيه من الكفار يسرا في الآجل فالعسر واحد واليسر اثنان وعن عمر رضي الله عنه لن يغلب عسر يسرين"},{"id":"mutash-kirmani:568","bookId":"mutash-kirmani","type":"section","surah":95,"num":568,"title":"سورة التين","page":"ج1 ص251","text":"قوله تعالى {لقد خلقنا الإنسان في أحسن تقويم} وقال في البلد {لقد خلقنا الإنسان في كبد} ولا مناقضة بينهما لأن معناه عند كثير من المفسرين منتصب القامة معتدلها فيكون في معنى أحسن تقويم ولمراعاة الفواصل في السورتين جاء على ما جاء"},{"id":"mutash-kirmani:569","bookId":"mutash-kirmani","type":"section","surah":96,"num":569,"title":"سورة العلق","page":"ج1 ص251","text":"قوله {اقرأ باسم ربك} وبعده {اقرأ وربك} وكذلك {الذي خلق} وبعده {خلق} ومثله {علم بالقلم} {علم الإنسان} لأن قوله {اقرأ} مطلق فقيده بالثاني والذي خلق عام فخصه بما بعده و {علم} مبهم ففسره فقال {علم الإنسان ما لم يعلم}"},{"id":"mutash-kirmani:570","bookId":"mutash-kirmani","type":"section","surah":97,"num":570,"title":"سورة القدر","page":"ج1 ص252","text":"قوله تعالى {إنا أنزلناه في ليلة القدر} {وما أدراك ما ليلة القدر} ثم قال {ليلة القدر} فصرح به وكان حقه الكناية رفعا لمنزلتها فإن الاسم قد يذكر بالتصريح في موضع الكناية تعظيما وتخويفا كما قال الشاعر لا أرى الموت يسبق الموت حتى ... نغص الموت ذا الغنى والفقيرا فصرح باسم الموت ثلاث مرات تخويفا وهو من أبيات الكتاب"},{"id":"mutash-kirmani:571","bookId":"mutash-kirmani","type":"section","surah":98,"num":571,"title":"سورة البينة","page":"ج1 ص252","text":"المتشابه فيها إعادة البينة والبرية مرتين وقد سبق"},{"id":"mutash-kirmani:572","bookId":"mutash-kirmani","type":"section","surah":99,"num":572,"title":"سورة الزلزلة","page":"ج1 ص252","text":"قوله {فمن يعمل مثقال ذرة} وأعاده مرة أخرى ليس بتكرار لأن الأول متصل بقوله {خيرا يره} والثاني متصل بقوله {شرا يره}"},{"id":"mutash-kirmani:573","bookId":"mutash-kirmani","type":"section","surah":100,"num":573,"title":"سورة العاديات","page":"ج1 ص252","text":"قوله {والعاديات} أقسم بثلاثة أشياء {والعاديات} {فالموريات} {فالمغيرات} وجعل جواب القسم أيضا ثلاثة أشياء {إن الإنسان لربه لكنود} {وإنه على ذلك لشهيد} {وإنه لحب الخير لشديد}"},{"id":"mutash-kirmani:574","bookId":"mutash-kirmani","type":"section","surah":101,"num":574,"title":"سورة القارعة","page":"ج1 ص252","text":"قوله {فأما من ثقلت موازينه} ثم {وأما من خفت موازينه} جمع ميزان وله كفان وعمود لسان وإنما جمع لاختلاف الموزونات وتجدد الوزن وكثرة الموزون لهم كقوله {عن الأهلة} وإنما هو هلال واحد وقيل هي جمع موزون"},{"id":"mutash-kirmani:575","bookId":"mutash-kirmani","type":"section","surah":102,"num":575,"title":"سورة التكاثر","page":"ج1 ص253","text":"قوله {كلا} في المواضع الثلاثة فيه قولان أحدها أن معناه الردع والزجر عن التكاثر فحسن الوقف عليه والابتداء بما بعده والثاني أنه يجري مجرى القسم ومعناه"},{"id":"mutash-kirmani:576","bookId":"mutash-kirmani","type":"section","surah":102,"num":576,"title":"سورة التكاثر","page":"ج1 ص253","text":"قوله {سوف تعلمون} وبعده {سوف تعلمون} تكرار للتأكيد عند بعضهم وعند بعضهم هما في وقتين القبر والقيامة فلا يكون تكرارا وكذلك قول من قال الأول للكفار والثاني للمؤمنين"},{"id":"mutash-kirmani:577","bookId":"mutash-kirmani","type":"section","surah":102,"num":577,"title":"سورة التكاثر","page":"ج1 ص253","text":"قوله {لترون الجحيم} {ثم لترونها} تأكيد أيضا وقيل الأول قبل الدخول والثاني بعد الدخول ولهذا قال بعده {عين اليقين} أي عيانا لستم عنها بغائبين وقيل الأول من رؤية القلب والثاني من رؤية العين"},{"id":"mutash-kirmani:578","bookId":"mutash-kirmani","type":"section","surah":103,"num":578,"title":"سورة العصر","page":"ج1 ص254","text":"قوله {والعصر إن الإنسان} إنه أبو جهل {إلا الذين آمنوا} أبو بكر {وعملوا الصالحات} عمر {وتواصوا بالحق} عثمان {وتواصوا بالصبر} على رضى الله عن الخلفاء الأربع ولعن أبا جهل قوله وتواصوا بالحق وتواصوا بالصبر كرر لاختلاف المفعولين وهما بالحق وبالصبر وقيل لاختلاف الفاعلين فقد جاء مرفوعا إن الانسان"},{"id":"mutash-kirmani:579","bookId":"mutash-kirmani","type":"section","surah":104,"num":579,"title":"سورة الهمزة","page":"ج1 ص254","text":"قوله {الذي جمع} فيه اشتباه ويحسن الوقف على {لمزة} حيث لم يصلح أن يكون {الذي} وصفا له ولا بدلا عنه ويجوز أن يكون رفعا بالابتداء بحسب خبره ويجوز أن يرتفع بالخبر أي هو الذي جمع ويجوز أن يكون نصبا على الذم بإضمار أعني ويجوز أن يكون جرا بالبدل من قوله {لكل}"},{"id":"mutash-kirmani:580","bookId":"mutash-kirmani","type":"section","surah":105,"num":580,"title":"سورة الفيل","page":"ج1 ص254","text":"قوله {ألم تر كيف فعل} أتى في مواضع وهذا آخرها ومفعولاه محذوفان وكيف مفعول ولا يعمل فيه ما قبله لأنه استفهام والاستفهام لا يعمل فيه ما قبله"},{"id":"mutash-kirmani:581","bookId":"mutash-kirmani","type":"section","surah":106,"num":581,"title":"سورة قريش","page":"ج1 ص254","text":"قوله {لإيلاف قريش إيلافهم} كرر لأن الثاني بدل من الأول أفاد بيان المفعول وهو {رحلة الشتاء والصيف} وروى عن الكسائي وغيره ترك التسمية بين السورتين على أن اللام في {لإيلاف} متصل بالسورة الأولى وقد سبق بيانه في التفسير"},{"id":"mutash-kirmani:582","bookId":"mutash-kirmani","type":"section","surah":107,"num":582,"title":"سورة الماعون","page":"ج1 ص255","text":"قوله {الذين هم} كرر ولم يقتصر على مرة واحدة لامتناع عطف الفعل على الاسم ولم يقل الذين هم يمنعون لأنه فعل فحسن عطف الفعل على الفعل"},{"id":"mutash-kirmani:583","bookId":"mutash-kirmani","type":"section","surah":108,"num":583,"title":"سورة الكوثر","page":"ج1 ص255","text":"قوله {إنا أعطيناك الكوثر} وبعده {إن شانئك} قيد الخبرين بأن تأكيدا والخبر إذا أكد بإن قارب القسم"},{"id":"mutash-kirmani:584","bookId":"mutash-kirmani","type":"section","surah":109,"num":584,"title":"سورة الكافرون","page":"ج1 ص255","text":"قوله {لا أعبد ما تعبدون} في تكراره أقوال جمة ومعان كثيرة ذكرت في موضعها قال الشيخ الإمام وأقول هذا التكرار اختصار وهو إعجاز لأن الله نفى عن نبيه عبادة الأصنام في الماضي والحال والاستقبال ونفى {عن} الكفار المذكورين عبادة الله في الأزمنة الثلاثة أيضا فاقتضى القياس تكرار هذه اللفظة ست مرات فذكر لفظ الحال لأن الحال هو الزمان الموجود واسم الفاعل واقع موقع الحال وهو صالح للأزمنة الثلاثة واقتصر من الماضي على المسند إليهم فقال {ولا أنا عابد ما عبدتم} ولأن اسم الفاعل بمعنى الماضي فعمل على مذهب الكوفيين واقتصر من المستقبل على لفظ المسند إليه فقال {ولا أنتم عابدون} وكأن أسماء الفاعلين بمعنى المستقبل"},{"id":"mutash-kirmani:585","bookId":"mutash-kirmani","type":"section","surah":110,"num":585,"title":"سورة النصر","page":"ج1 ص256","text":"وتسمى أيضا سورة التوديع فإن جواب إذا مضمر تقديره إذا جاء نصر الله إياك على من ناوأك حضر أجلك وكان صلى الله عليه وسلم لما نزلت هذه السورة يقول نعى الله تعالى إلى نفسي"},{"id":"mutash-kirmani:586","bookId":"mutash-kirmani","type":"section","surah":111,"num":586,"title":"سورة المسد","page":"ج1 ص256","text":"قوله تعالى (تبت يدا) وبعده (وتب) ليس بتكرار لان الاول جرى مجرى الدعاء والثاني جزاء اي وقد تب وقيل تبت يدا ابي لهب اي عمله وتب ابو لهب وقال مجاهد وتب ابنه"},{"id":"mutash-kirmani:587","bookId":"mutash-kirmani","type":"section","surah":112,"num":587,"title":"سورة الإخلاص","page":"ج1 ص256","text":"قوله تعالى {الله أحد} {الله الصمد} كرر لتكون كل جملة منهما مستقلة بذاتها غير محتاجة إلى ما قبلها ثم نفى سبحانه عن نفسه الولد والصاحبة بقوله {ولم يكن له كفوا أحد}"},{"id":"mutash-kirmani:588","bookId":"mutash-kirmani","type":"section","surah":113,"num":588,"title":"سورة الفلق","page":"ج1 ص256","text":"نزلت في ابتداء خمس سور وصارت متلوا بها لأنها نزلت جوابا وكرر قوله {من شر} أربع مرات لأن شر كل واحد منها غير الآخر"},{"id":"mutash-kirmani:589","bookId":"mutash-kirmani","type":"section","surah":114,"num":589,"title":"سورة الناس","page":"ج1 ص258","text":"قوله تعالى {أعوذ برب الناس} ثم كرر الناس خمس مرات قيل كرر تبجيلا لهم على ما سبق وقيل كرر لانفصال كل آية من الأخرى لعدم حرف العطف وقيل المراد بالأول الأطفال ومعنى الربوبية يدل عليه وبالثاني الشبان ولفظ الملك المنبئ عن السياسة يدل عليه وبالثالث الشيوخ ولفظ إله المنبئ عن العبادة يدل عليه وبالرابع الصالحون والأبرار والشيطان يولع بإغوائهم وبالخامس المفسدون والأشرار وعطفه على المتعوذ منهم يدل على ذلك"}]};